// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Kamu ekonomisi: dışsallıklar, tam kamusal mallar, bedavacılık sorunu, Pigou vergisi, vergi tarifeleri ve gelir dağılımı (Lorenz, Gini) (orta).
const ozEconomics16Orta = <(String, String, List<String>, String)>[
  ('Paul Samuelson\'ın 1954 tarihli \'Kamu Harcamalarının Saf Teorisi\' makalesinde tam kamusal malları özel mallardan ayırmak için temel aldığı tüketim özelliği hangisidir?', 'Bireylerin maldan yararlanmasının diğerlerinin tüketim miktarını azaltmaması', ['Üretim maliyetinin her zaman özel sektör yatırımcıları tarafından karşılanması', 'Tüketicilerin mal için ödedikleri birim fiyatın gelirleriyle doğru orantılı artması', 'Piyasa arz eğrisinin her üretim düzeyinde tam esnek bir doğru biçiminde seyretmesi'], 'Samuelson saf kamusal malları, bir bireyin tüketiminin diğer bireylerin aynı maldan sağlayacağı faydayı azaltmadığı (tüketimde rekabetsiz) mallar olarak tanımlamıştır.'),
  ('Şifreli yayın yapan dijital bir film platformu aboneliği, ekonomik mal matrisinde neden \'kulüp malı\' kategorisine yerleştirilir?', 'Ücret ödemeyenlerin erişimi engellenirken mevcut abonelerin izlemesinin birbirini kısıtlamaması yüzünden', ['Devlet bütçesinden finanse edilip tüm vatandaşlara ücretsiz ve zorunlu olarak dağıtılması yüzünden', 'Abone sayısı arttıkça sunucu kapasitesinin anında tükenip diğer kullanıcıların yayından düşmesi yüzünden', 'Hiçbir teknik şifreleme yapılamadığı için şifresiz antenle herkesin yayını izleyebilmesi yüzünden'], 'Şifreli yayınlarda dışlanabilirlik vardır ancak kapasite sınırına kadar tüketimde rekabet yoktur; bu tür mallara kulüp malı denir.'),
  ('Gece vakti tenha bir otoyolda gişeden ücret ödeyerek geçen sürücülerin yararlandığı yol hizmeti hangi mal özelliğini gösterir?', 'Dışlanabilir fakat tüketimde rekabetsiz', ['Dışlanamaz fakat tüketimde tam rekabetçi', 'Hem dışlanamaz hem de tüketimde rekabetsiz', 'Hem dışlanabilir hem de tüketimde tam rekabetçi'], 'Ücretli gişe dışlanabilirliği sağlar; yol tenha olduğu için bir aracın geçişi diğerinin hızını düşürmez yani tüketimde rekabet yoktur.'),
  ('Ücretsiz bir şehir içi çevre yolu sabah işe gidiş saatlerinde tamamen kilitlendiğinde, bu yolun ekonomik niteliği nasıl bir dönüşüm geçirir?', 'Tam kamusal mal görünümünden çıkıp tüketimde rekabetçi bir ortak kaynağa dönüşür', ['Ortak kaynak niteliğini kaybederek dışlanabilirliği yüksek bir kulüp malı haline gelir', 'Saf özel mal yapısından uzaklaşıp bölünemez nitelikli tam kamusal mala evrilir', 'Tüketimde rekabetsiz hale gelerek marjinal sıkışıklık maliyetini sıfıra indirir'], 'Yol ücretsiz olduğu için dışlanamazdır; ancak trafik yoğunlaşınca her ek araç diğerlerini yavaşlatır ve tüketimde rekabet başlar, böylece ortak kaynak özelliği kazanır.'),
  ('İki tüketicili bir ekonomide özel bir malın piyasa talep eğrisi bireysel taleplerin yatay toplamıyla bulunurken, tam kamusal bir malın toplumsal talep eğrisi nasıl elde edilir?', 'Her bir üretim miktarında bireylerin marjinal ödeme istekliliklerinin dikey olarak toplanmasıyla', ['Bireylerin farklı fiyat düzeylerinde talep ettikleri miktarların aritmetik ortalamasının alınmasıyla', 'En yüksek gelire sahip tüketicinin talep eğrisinden en düşük gelirlinin talebinin çıkarılmasıyla', 'Birim üretim maliyetinin nüfus artış hızına bölünerek yatay eksende sağa kaydırılmasıyla'], 'Tam kamusal malı herkes aynı miktarda tükettiği için miktar sabit tutulur ve bireylerin o miktara ödemeye razı oldukları marjinal değerler dikey toplanır.'),
  ('Kurak bir tarım havzasında çiftçilerin derin kuyular açarak aynı yeraltı su akiferinden sınırsızca su çekmesi hangi ekonomik soruna yol açar?', 'Mülkiyet sınırı çizilemeyen ortak kaynağın su tablasını hızla düşürerek tüm çiftçilerin pompalama maliyetini artırmasına', ['Yeraltı suyunun kendiliğinden şifreli bir kulüp malına dönüşerek küçük çiftçilerin kuyularını tamamen kapatmasına', 'Akiferdeki suyun bölünemez tam kamusal mal niteliği kazanarak tarımsal sulama verimliliğini kalıcı biçimde yükseltmesine', 'Özel marjinal maliyetin sosyal marjinal maliyetin üzerine çıkarak havzada eksik su kullanımına neden olmasına'], 'Yeraltı su havzası (akifer) dışlanamaz ama rekabetçi bir ortak kaynaktır; her çiftçinin aşırı çekimi su seviyesini düşürüp ortak zarara yol açar.'),
  ('Şehir merkezindeki halka açık ücretsiz bir belediye parkı, hafta sonu aşırı kalabalıklaştığında oturacak bank kalmaması hangi kavramla açıklanır?', 'Kapasite sınırının aşılmasıyla başlayan tıkanıklık maliyeti', ['Fiyat mekanizmasının yarattığı tam dışlanabilirlik etkisi', 'Üretimde ölçeğe göre artan getirinin sıfırlanması', 'Bölünemezlik ilkesinin dikey talep toplamını güçlendirmesi'], 'Belirli bir kalabalık eşiğine kadar rekabetsiz görünen kamusal alanlar, kapasite dolduğunda tıkanıklık (congestion) maliyeti üretir ve rekabetçi hale gelir.'),
  ('İtfaiye teşkilatının yangın söndürme hizmeti değerlendirildiğinde, hangi durum bu hizmette kısmi tüketim rekabeti doğabileceğini gösterir?', 'Aynı anda şehrin iki farklı ucunda büyük yangın çıktığında araçların birine gitmesinin diğerine müdahaleyi geciktirmesi', ['Mahallede yangın çıkmadığı günlerde itfaiye erlerinin istasyonda nöbet tutarak hazır beklemesi', 'Bir apartmandaki yangının söndürülmesinin bitişikteki binaların da yanmasını kendiliğinden önlemesi', 'Belediye sınırları içindeki kiracıların emlak vergisi ödemeseler bile yangın ihbar hattını arayabilmesi'], 'İtfaiye kapasitesi sınırlı olduğunda eşzamanlı yangınlarda bir olaya ayrılan ekip diğer olayda kullanılamaz; bu da kısmi rekabetçilik yaratır.'),
  ('Bulaşıcı sıtma hastalığını önlemek amacıyla bataklıkların kurutulması ve ilaçlanması faaliyeti neden özel bir sigorta şirketince değil de kamu eliyle yürütülür?', 'Bölgede yaşayan herkes sivrisinek azalmasından otomatik yararlandığı için kimseye bireysel poliçe satılamaması', ['İlaçlama uçaklarının teknik bakımının yalnızca askeri hava üslerinde yapılabilmesi', 'Bataklık kurutulduğunda sivrisinek sayısının artarak tüketimde rekabeti yükseltmesi', 'Bireylerin hastalanma riskinin yaş gruplarına göre istatistiksel olarak hesaplanamaması'], 'Vektör kontrolü ve bataklık ıslahı bölgedeki kimseyi dışlayamadığından tam kamusal sağlık hizmetidir; özel piyasa ödeme toplamakta başarısız olur.'),
  ('Üç vatandaşın (K, L, M) bir mahalle bekçisi istihdam edilmesine verdiği marjinal değerler sırasıyla 250 TL, 300 TL ve 400 TL\'dir. Bekçinin maliyeti 850 TL ise etkinlik açısından hangi karar doğrudur?', 'Toplam marjinal fayda 950 TL olup maliyeti aştığı için bekçi istihdam edilmelidir', ['Hiçbir vatandaş tek başına 850 TL ödemeye razı olmadığı için hizmetten vazgeçilmelidir', 'Yalnızca en yüksek faydayı sağlayan M vatandaşı maliyetin tamamını üstlenirse bekçi tutulmalıdır', 'Ortalama bireysel fayda 316,6 TL olup 850 TL\'nin altında kaldığından kaynak israfı doğar'], 'Kamusal nitelikli mahalle güvenliğinde Samuelson koşulu uyarınca bireysel marjinal faydalar toplanır (250+300+400=950 TL); 950 > 850 olduğu için üretim etkindir.'),
  ('Dijital ortamda indirilebilen patentli bir bilgisayar yazılımı, kopya koruma lisansı sayesinde mal sınıflandırmasında nereye oturur?', 'Lisans anahtarıyla dışlanabilir, kopyalanma maliyeti sıfıra yakın olduğu için tüketimde rekabetsiz kulüp malı', ['Herkesin ücretsiz kopyalayabildiği fakat aynı anda yalnızca tek kişinin çalıştırabildiği ortak kaynak', 'Devletin zorunlu tuttuğu, kimsenin kullanımından dışlanamadığı bölünemez tam kamusal mal', 'Her indirildiğinde sunucudaki orijinal dosyayı silerek tüketen tam rekabetçi saf özel mal'], 'Yazılım şifre ve lisansla dışlanabilir kılınır; ancak bir kullanıcının indirmesi diğerlerinin indirmesini azaltmadığından tüketimde rekabetsizdir.'),
  ('Özel bir spor salonunun yıllık üyelik sistemiyle çalışması ancak akşam saat 19.00\'da koşu bantlarının önünde uzun kuyruklar oluşması neyi gösterir?', 'Kulüp malının belirli yoğunluk eşiğinden sonra kısmi tüketim rekabeti sergilediğini', ['Spor salonunun dışlanabilirlik özelliğini tamamen yitirerek açık meraya dönüştüğünü', 'Üyelik aidatlarının sıfırlanması halinde kuyrukların kendiliğinden ortadan kalkacağını', 'Hizmetin bölünemez tam kamusal mal niteliği taşıdığı için belediyeye devredilmesi gerektiğini'], 'Kulüp malları dışlanabilirdir; tenha saatlerde rekabetsizken pik saatlerde kapasite kısıtı nedeniyle kısmi rekabet (sıkışıklık) ortaya çıkar.'),
  ('Denizlerdeki balina türlerinin neslinin tükenme tehlikesiyle karşı karşıya kalırken çiftlik tavuklarının sayısının milyarlara ulaşması iktisadi olarak nasıl açıklanır?', 'Tavuklar üzerinde özel mülkiyet ve dışlanabilirlik varken açık okyanuslardaki balinaların sahipsiz ortak kaynak olmasıyla', ['Balina avcılığında kullanılan gemilerin marjinal yakıt maliyetinin tavuk yeminden çok daha düşük kalmasıyla', 'Tüketicilerin tavuk etine yönelik talep esnekliğinin sıfır, balina ürünlerine esnekliğinin sonsuz olmasıyla', 'Devletlerin tavuk çiftliklerine ağır çevre vergileri koyarken balina avcılığına yüksek sübvansiyon vermesiyle'], 'Özel mülkiyete konu olan varlıklar sahibi tarafından korunup çoğaltılırken, mülkiyet hakkı tanımlanmamış ortak kaynaklar aşırı avlanmaya maruz kalır.'),
  ('Bir malda dışlanabilirliğin teknik olarak mümkün olmasına rağmen ekonomik açıdan uygulanmamasının temel nedeni ne olabilir?', 'Gişe kurma, sayaç takma veya denetim yapma maliyetinin elde edilecek faydadan çok daha yüksek çıkması', ['Malın marjinal üretim maliyetinin her ek tüketicide üstel olarak sonsuza doğru yükselmesi', 'Özel sektör firmalarının tekel kârı elde etmekten gönüllü olarak vazgeçmeyi tercih etmesi', 'Tüketicilerin söz konusu mala yönelik toplam talebinin fiyat düştükçe hızla azalması'], 'Örneğin şehir içi kaldırımlara turnike koymak teknik olarak mümkün olsa bile işlem ve tahsilat maliyeti aşırı yüksek olduğundan dışlama uygulanmaz.'),
  ('Orman köylülerinin serbestçe mantar ve odun topladığı devlet ormanında, kaynak tahribatını önlemek için köylülere belirli parsel kullanım belgeleri verilmesi neyi amaçlar?', 'Dışlanamaz nitelikteki ortak kaynağa kullanım sınırı getirerek aşırı tüketim güdüsünü kırmayı', ['Orman ürünlerinin tüketimdeki rekabetçiliğini sıfırlayarak ormanı saf kamusal mala çevirmeyi', 'Köylülerin ormandan elde ettiği özel faydayı tamamen ortadan kaldırıp üretimi durdurmayı', 'Ağaçların doğal büyüme hızını düşürerek kereste fiyatlarını uluslararası borsada sabitlemeyi'], 'Ortak kaynaklarda mülkiyet veya kota/izin belgeleri tanımlamak, dışlanabilirlik yaratarak kaynağın sürdürülebilir kullanımını sağlar.'),
  ('Uygulamalı buluşlarda devletin mucitlere geçici süreli \'patent hakkı\' tanıması, mal sınıflandırması çerçevesinde hangi dönüşümü yaratır?', 'Doğası gereği rekabetsiz olan bilgiyi yasal olarak dışlanabilir kılarak geçici bir kulüp veya tekel malına dönüştürür', ['Bilginin tüketimdeki rekabetsizliğini ortadan kaldırıp aynı formülü iki firmanın kullanmasını fiziksel olarak imkânsızlaştırır', 'Özel sektörün araştırma geliştirme harcamalarını sıfırlayarak tüm icatların devlet laboratuvarlarında yapılmasını zorunlu kılar', 'Süresi dolan patentleri açık erişimli kamusal mal olmaktan çıkarıp sonsuza dek özel mülkiyete hapseder'], 'Bilgi tüketimde rekabetsizdir; patent yasası izinsiz kullanımı yasaklayarak yapay dışlanabilirlik oluşturur ve yenilik yapma teşvikini korur.'),
  ('Bir konser salonunda sahnelenen tiyatro oyunu, salonun koltuk kapasitesi dolana kadar hangi mal sınıfının özelliklerini taşır?', 'Bilet kontrolüyle dışlanabilen ve boş koltuk varken ek izleyicinin diğerlerini engellemediği kulüp malı', ['Kapıda bilet sorulmayan ancak içeri giren her seyircinin sahneyi küçülttüğü ortak mülkiyet kaynağı', 'Bilet fiyatı sıfır olan ve şehirdeki herkesin evinden izleyebildiği bölünemez tam kamusal mal', 'Her bir koltuğun satılmasıyla oyunun süresinin kısaldığı tam rekabetçi dayanıksız tüketim malı'], 'Boş koltuk bulunan bir tiyatro salonunda gişe ile dışlama vardır, ek seyirci diğerlerinin seyir zevkini azaltmadığından kapasiteye kadar rekabetsizdir.'),
  ('Aşağıdaki eşleştirmelerden hangisinde hem \'dışlanamazlık\' hem de \'tüketimde rekabet\' özelliği aynı anda güçlü biçimde gözlemlenir?', 'Avlanma yasağı denetimi bulunmayan açık göldeki sazan balığı popülasyonu', ['Karasal vericiden şifresiz yayın yapan ulusal televizyon kanalının haber bülteni', 'Tapusu tek bir aileye ait olan ve etrafı dikenli telle çevrili elma bahçesi', 'Aylık abonelik ücretiyle girilen bulut tabanlı e-kitap okuma kütüphanesi'], 'Denetimsiz açık gölde balık tutmak dışlanamazdır fakat yakalanan her balık göldeki stoku azaltarak diğer avcılarla rekabet yaratır.'),
  ('Üniversite amfisinde 200 kişilik yer varken dersi 60 öğrencinin dinlemesi ve kapıda öğrenci kimlik kartı okutularak içeri girilmesi hangi mal yapısını yansıtır?', 'Kimlikle dışlanabilen ve boş kapasite sayesinde ek öğrencinin diğerlerinin ders dinlemesini engellemediği kulüp/yarı kamusal mal', ['Hiç kimsenin amfiye girmekten men edilemediği ve her öğrencinin dersi tükettiği ortak kaynak', 'Kapasitesi tamamen dolmuş ve marjinal sıkışıklık maliyeti sonsuza ulaşmış saf özel tüketim malı', 'Bölünemez ve dışlanamaz olduğu için uzaktan geçen yayaların da eşit yararlandığı tam kamusal mal'], 'Kimlik kontrolü dışlanabilirliği sağlar; 200 kişilik salonda 60 kişi varken rekabet yoktur, ayrıca eğitimin dışsal faydaları onu yarı kamusal da kılar.'),
  ('Bir kasabadaki temiz nehir suyunun hem fabrikalarca atık boşaltmak için hem de halk tarafından yüzmek için ücretsiz kullanılabilmesi ne tür bir mülkiyet sorununa işaret eder?', 'Açık erişimli ortak kaynak niteliğindeki nehirde rakip kullanımlar arasında dışlama mekanizmasının bulunmamasına', ['Nehrin saf özel mal olması nedeniyle fabrikanın halka tazminat ödeyerek suyu satın almasına', 'Su kaynağının tüketimde rekabetsiz olması yüzünden atık boşaltılmasının yüzme kalitesini etkilememesine', 'Belediyenin nehir kıyısına yüksek giriş ücreti koyarak kulüp malı dengesini önceden kurmuş olmasına'], 'Atık dökme ve yüzme nehir suyunun kalitesi üzerinde birbirini dışlayan (rekabetçi) kullanımlardır; mülkiyet ve dışlama olmayınca nehir hızla kirlenir.'),
  ('Teknolojik gelişmelerin mal sınıflandırmasını değiştirebildiğine dair en yerinde tarihsel örnek aşağıdakilerden hangisidir?', 'Elektronik etiket (HGS/OGS) sistemlerinin icadıyla daha önce gişe kurulamayan şehir içi yollarda dışlanabilirliğin ucuzlaması', ['Matbaanın bulunmasıyla kitapların özel mal olmaktan çıkıp yalnızca sözlü aktarılan ortak kaynağa dönüşmesi', 'Buharlı gemilerin yapılmasıyla açık okyanuslardaki balık sürülerinin tüketimde rekabetsiz hale gelmesi', 'Tarımda traktör kullanılmasıyla buğdayın bölünemez nitelikte tam kamusal bir mala evrilmesi'], 'Dışlanabilirlik sabit bir doğa yasası değil, teknoloji ve maliyete bağlıdır; elektronik geçiş sistemleri dur-kalk olmadan yol fiyatlandırmasını mümkün kılmıştır.'),
  ('Tam kamusal mallarda bireysel talep eğrilerinin yatay değil de dikey toplanmasının arkasındaki mantıksal zorunluluk nedir?', 'Üretilen toplam miktarın tüm bireyler tarafından eşit ve ortaklaşa tüketilmesi zorunluluğu', ['Devletin her vatandaştan aynı miktarda gelir vergisi kesintisi yapması zorunluluğu', 'Kamusal malların üretiminde yalnızca sabit sermaye girdilerinin kullanılması zorunluluğu', 'Fiyat esnekliğinin tüm gelir gruplarında bire eşit çıkmasının matematiksel zorunluluğu'], 'Özel malda fiyat ortaktır miktarlar toplanır (yatay toplam); kamusal malda ise miktar ortaktır, o ortak miktar için bireylerin ödemeye razı olduğu fiyatlar toplanır (dikey toplam).'),
  ('Aşağıdakilerden hangisi Richard Musgrave\'in kamu maliyesinin üç temel işlevi sınıflandırmasında tam kamusal malların üretimiyle doğrudan ilişkili olan şubedir?', 'Kaynak tahsisi işlevi', ['Gelir dağılımı işlevi', 'İktisadi istikrar işlevi', 'Dış ticaret dengesi işlevi'], 'Musgrave\'in üçlü tasnifinde (tahsis, bölüşüm, istikrar), piyasanın üretemediği tam kamusal mallara kaynak ayrılması \'kaynak tahsisi\' (allocation branch) görevidir.'),
  ('Kablolu su şebekesiyle evlere dağıtılan içme suyunun sayaçlarla ölçülüp faturalandırılması, bu hizmeti mal sınıflandırmasında nereye yaklaştırır?', 'Sayaçla dışlanabilen ve kullanılan suyun başka haneye gidememesi nedeniyle rekabetçi olan özel/pazarlanabilir mal yapısına', ['Bölünemez nitelikte olduğu için bireysel tüketim miktarı saptanamayan tam kamusal mal yapısına', 'Hiçbir abonenin su kesintisiyle cezalandırılamadığı açık erişimli yeraltı ortak kaynak yapısına', 'Ne kadar çok abone su açarsa şebeke basıncının o kadar arttığı rekabetsiz kulüp malı yapısına'], 'Şebeke suyu doğal tekel altyapısıyla sunulsa da hane bazında ölçülebildiği, kesilebildiği (dışlanabilir) ve tüketildiğinde azaldığı (rekabetçi) için özel mal karakterindedir.'),
  ('Atmosferdeki temiz havanın sanayi devrimi öncesinde \'serbest mal\' (free good) sayılırken sanayileşme sonrasında \'ortak kaynak\' olarak ele alınmasının nedeni nedir?', 'Yoğun emisyonlarla temiz hava kapasitesinin kıtlaşması ve kirleticilerin kullanımının diğerlerinin temiz hava tüketimini daraltması', ['Havanın şişelenerek marketlerde yüksek fiyattan satılmasının tüm ülkelerde yasal zorunluluk haline gelmesi', 'Bitkilerin fotosentez yoluyla oksijen üretme hızının sanayileşmeyle birlikte tamamen sıfırlanması', 'Atmosferin ülke sınırlarına göre duvarlarla bölünerek dışlanabilir özel mülkiyete dönüştürülmesi'], 'Bir doğa unsuru bol iken rekabetsiz serbest maldır; ancak kirlilik kapasitesine ulaşıldığında kıtlaşır ve rakip kullanımlar nedeniyle ortak kaynağa dönüşür.'),
  ('Kamu mallarının sunumunda \'kamusal üretim\' ile \'kamusal finansman (sağlama)\' arasındaki ayrım hangi seçenekte doğru örneklendirilmiştir?', 'Belediyenin vergi gelirleriyle finanse ettiği sokak temizliği işini ihale yoluyla özel bir temizlik şirketine yaptırması', ['Özel bir otomobil fabrikasının kendi sermayesiyle ürettiği araçları bayiler aracılığıyla tüketicilere satması', 'Devlet memurlarının kendi maaşlarıyla mahalle bakkalından peynir ve zeytin satın alması', 'Vatandaşların imece usulüyle para toplayıp devlet hazinesine hiçbir vergi ödemeden özel bekçi tutması'], 'Kamusal malın bedelinin vergilerle devletçe karşılanması \'kamusal sağlama/finansman\'dır; ancak malın bizzat devlet işçisiyle değil özel firmaya ihale edilerek üretilmesi mümkündür.'),
  ('Bir ülkenin diplomatik temsilcilikleri aracılığıyla yürüttüğü dış politika ve uluslararası antlaşmalar ağı neden saf kamusal mal sayılır?', 'Sağlanan barış ve uluslararası itibardan tüm vatandaşların ayrım gözetilmeksizin ve birbirinin payını azaltmadan yararlanması', ['Büyükelçilik binalarının yurt dışındaki gayrimenkul piyasasında alınıp satılabilen mülkler olması', 'Konsolosluklarda pasaport yenileme işlemi yapılırken vatandaşlardan değerli kâğıt bedeli alınması', 'Dışişleri bakanlığı personelinin yabancı dil sınavıyla seçilerek sınırlı kadrolara atanması'], 'Diplomatik caydırıcılık ve uluslararası barış ortamı bölünemez, dışlanamaz ve tüketimde rekabetsiz bir ulusal kamusal maldır.'),
  ('Gönüllü katkı (Nash) modelinde yüksek gelirli bir hayırseverin mahalleye tek başına 5 adet çeşme yaptırması, düşük gelirli komşuların katkı davranışını nasıl etkiler?', 'Komşular mevcut çeşmeleri yeterli bularak kendi gönüllü katkılarını sıfıra çekerler', ['Komşular da gelirlerinin tamamını harcayarak en az 5\'er çeşme daha inşa ettirirler', 'Çeşmeler kendiliğinden dışlanabilir özel mala dönüşerek mahalleliye kilitlenir', 'Mahalledeki toplam çeşme talebi dikey toplam yerine yatay toplam kuralına geçer'], 'Kamusal malların gönüllü sunumunda zengin bireyin yaptığı katkı diğerlerinin marjinal katkı isteğini dışlar (crowding-out).'),
  ('Devletin sunduğu tam kamusal bir malın finansmanında genel vergi gelirleri yerine \'kullanıcı harcı\' uygulanamamasının temel sebebi nedir?', 'Malın faydalarının bireylere göre bölünememesi ve kimin ne kadar yararlandığının gişe benzeri bir araçla ölçülememesi', ['Anayasal olarak devletin vatandaşlardan vergi dışında hiçbir ad altında gelir tahsil edememesi', 'Kullanıcı harçlarının yalnızca ithal edilen lüks tüketim malları üzerinden gümrükte alınabilmesi', 'Tam kamusal malların üretiminde hiçbir parasal harcama yapılmadığı için finansman ihtiyacının doğmaması'], 'Harç ve resimler kişiye özel bölünebilir kamu hizmetlerinde (pasaport, tapu vb.) alınabilir; bölünemez tam kamusal malda bireysel kullanım ölçülemez.'),
  ('Bir deniz fenerinin ışığından yararlanan yük gemisinin yanında ikinci bir balıkçı teknesinin aynı rotadan geçmesi neden refah artışına yol açar?', 'Fenerin işletme maliyeti değişmezken ikinci teknenin güvenli seyir faydası elde ederek toplumsal net faydayı büyütmesi', ['İkinci teknenin geçişiyle birlikte fenerin elektrik tüketiminin yarı yarıya azalarak tasarruf sağlaması', 'Yük gemisinin fener ışığından aldığı pay azaldığı için deniz taşımacılığı navlun fiyatlarının yükselmesi', 'Balıkçı teknesinin geçişi sayesinde fenerin tüketimde tam rekabetçi bir özel mala dönüşmesi'], 'Tüketimde rekabetsiz bir malda ek kullanıcı sıfır marjinal maliyetle pozitif marjinal fayda elde eder; bu da toplumsal refahı doğrudan artırır.'),
  ('Yarı kamusal malların (örneğin yükseköğretimin) hem vakıf/özel üniversitelerce ücretli hem de devlet üniversitelerince ücretsiz sunulabilmesi malın hangi özelliğinden kaynaklanır?', 'Sınıf ve kontenjan yoluyla dışlanabilir olması yanında topluma yaydığı pozitif dışsallıkların kamu desteğini haklı kılmasından', ['Yükseköğretimin bölünemez nitelikte olması nedeniyle hiçbir öğrencinin kampüse girmekten alıkonulamamasından', 'Üniversite derslerinin tüketiminde tam rekabetsizlik bulunduğu için kontenjan sınırının hiç var olmamasından', 'Özel üniversitelerin kâr amacı gütmesinin tüm piyasa ekonomilerinde kesin olarak yasaklanmış olmasından'], 'Eğitim diploma ve kayıtla dışlanabilir olduğundan özel sektörce satılabilir; ancak yarattığı toplumsal fayda ve fırsat eşitliği nedeniyle devlet de sunar.'),
  ('Bir malın \'kamusal mal\' olarak nitelendirilmesi için o malın mutlaka devlet tarafından üretilmesi gerekir mi?', 'Hayır; malın kamusallığını üreten kurum değil dışlanamazlık ve tüketimde rekabetsizlik gibi teknik tüketim özellikleri belirler', ['Evet; devlet fabrikalarında üretilen demir-çelik ve şeker dahil her ürün iktisaden tam kamusal mal sayılır', 'Evet; özel bir hayırseverin ücretsiz ve açık erişimli kurduğu sokak çeşmesi hiçbir koşulda kamusal mal olamaz', 'Hayır; ancak yalnızca merkez bankasının bastığı kağıt paralar dışındaki tüm mallar özel mal kabul edilir'], 'İktisatta kamusal mal tanımı mülkiyet veya üreticiye göre değil malın tüketim karakterine göre yapılır; özel bir vakfın diktiği saat kulesi kamusal mal olabilirken devletin ürettiği şeker özel maldır.'),
  ('Sel taşkınlarını önlemek için bir nehir yatağına inşa edilen büyük baraj seti, ovadaki çiftçiler ve kasaba halkı açısından neden kamusal mal niteliğindedir?', 'Baraj taşkını tuttuğunda ovadaki vergi vermeyen tarla sahibini selden korumamanın imkânsız olması ve bir tarlanın korunmasının diğerini azaltmaması', ['Baraj inşaatında kullanılan çimento ve demirin özel sektör tedarikçilerinden piyasa fiyatıyla satın alınması', 'Sulama kanallarından tarlalara verilen suyun sayaçla ölçülerek metreküp başına ücretlendirilebilmesi', 'Baraj gölünde yapılan ticari alabalık yetiştiriciliğinin yalnızca lisanslı kooperatiflere kiralanması'], 'Barajın elektrik ve sulama suyu çıktıları özel/pazarlanabilir mal iken, ovayı taşkından koruma hizmeti dışlanamaz ve rekabetsiz bir tam kamusal maldır.'),
  ('Üç bireyli (A, B, C) bir toplumda kamusal malın marjinal maliyeti sabit ve 90 TL\'dir. Q=10 birim üretimde bireylerin marjinal faydaları sırasıyla 45 TL, 35 TL ve 25 TL ise üretim miktarı hakkında ne söylenebilir?', 'Toplam marjinal fayda 105 TL olup 90 TL\'lik marjinal maliyeti aştığı için üretim 10 birimin üzerine çıkarılmalıdır', ['Bireysel faydaların hiçbiri 90 TL\'ye ulaşamadığı için kamusal malın üretimi derhal sıfıra indirilmelidir', 'Ortalama marjinal fayda 35 TL olduğu için üretim miktarı azaltılarak 90 TL\'ye eşitlenmelidir', 'Toplam marjinal fayda marjinal maliyete tam eşit olduğundan 10 birimlik üretim sosyal optimumdur'], 'Q=10 düzeyinde ΣMB = 45 + 35 + 25 = 105 TL > MC (90 TL). Azalan marjinal fayda altında ΣMB = MC olana kadar üretimi artırmak refahı yükseltir.'),
  ('Tam kamusal mallarda \'tüketimden dışlanamazlık\' özelliği ile \'üretimde ölçek ekonomileri\' kavramlarını karıştırmamak için hangi ayrım bilinmelidir?', 'Dışlanamazlık ödeme yapmayanı engelleme güçlüğünü ifade ederken, ölçek ekonomileri üretim miktarı arttıkça uzun dönem ortalama maliyetin düşmesini anlatır', ['Dışlanamazlık yalnızca tarım ürünlerinde görülürken, ölçek ekonomileri yalnızca ulusal savunma hizmetlerinde görülür', 'Ölçek ekonomileri tüketimde rekabeti artırırken, dışlanamazlık marjinal üretim maliyetini her zaman sonsuza çıkarır', 'Her iki kavram da birebir aynı anlamı taşıdığı için ortalama maliyeti düşen her özel fabrika tam kamusal mal üretir'], 'Otomobil fabrikasında ölçek ekonomisi olabilir ama otomobil dışlanabilir özel maldır; dışlanamazlık maliyet eğrisiyle değil mülkiyet ve erişim kontrolüyle ilgilidir.'),
  ('Kırsal bir bölgede mera, orman veya balık yatağı gibi ortak kaynakların aşırı kullanımını önlemek için başvurulan aşağıdaki yöntemlerden hangisi kaynağı \'özel mala\' yaklaştırır?', 'Mera arazisinin kadastro ile parsellenip çitlerle çevrilerek köylülere bireysel tapu dağıtılması', ['Köy muhtarlığının meraya giriş saatlerini imece kurallarıyla mevsimlik nöbete bağlaması', 'Devletin merada otlatılan hayvan başına çobanlardan yıllık otlatma harcı tahsil etmesi', 'Bölgedeki hayvancılık kooperatifinin gönüllü eğitim seminerleriyle aşırı otlatmaya karşı bilinç oluşturması'], 'Ortak arazinin bölünüp çitlenerek bireysel mülkiyet tapusuna bağlanması (enclosure), hem dışlanabilirlik hem rekabetçilik sağlayarak kaynağı özel mala dönüştürür.'),
  ('Bir kamu malının fayda yayılım alanının tüm ülke yerine yalnızca tek bir ilçe sınırlarıyla kısıtlı olması durumunda mali yerelleşme (desantralizasyon) teoremi ne önerir?', 'Hizmetin yerel tercihleri daha iyi bilen ilçe belediyesince sunulup o ilçede yaşayanların yerel vergileriyle finanse edilmesini', ['İlçedeki çocuk parkının maliyetinin ülkedeki tüm illerin vatandaşlarından toplanan genel bütçe vergileriyle karşılanmasını', 'Yerel kamusal malların tamamının üretiminin durdurularak bütçenin yalnızca dış politikaya aktarılmasını', 'Faydası ilçeyle sınırlı olan hizmetlerin kararının uluslararası kuruluşlara devredilerek merkezileştirilmesini'], 'Wallace Oates\'un mali yerelleşme teoremine göre yerel kamusal malların yerel yönetimlerce bölge halkının tercihlerine uygun düzeyde sunulması refahı artırır.'),
  ('Bedavacılık (free-rider) sorununun gönüllü bağışlarla finanse edilen bir sokak aydınlatma projesinde piyasa başarısızlığına yol açmasının temel oyun kuramsal nedeni nedir?', 'Her hanenin diğerleri ödese de ödemese de katkı yapmamayı baskın strateji olarak seçmesi', ['Sokak lambalarının yaydığı ışığın haneler arasında eşit bölünemeyerek ilk evin tüm elektriği tüketmesi', 'Mahalle sakinlerinin elektrik mühendisliği bilgisi olmadığı için ampul gücünü yanlış hesaplaması', 'Aydınlatma direklerinin kurulum maliyetinin kullanıcı sayısı arttıkça üstel biçimde yükselmesi'], 'Mahpuslar ikilemine benzer biçimde, dışlanamazlık nedeniyle bireysel rasyonel davranış ödeme yapmamaktır; herkes böyle davranınca kamusal mal eksik üretilir.'),
  ('Erik Lindahl\'ın kamusal malların optimal finansmanı için geliştirdiği \'Lindahl dengesi\' modelinde her bireyin ödediği vergi fiyatı neye eşittir?', 'Kamusal malın ortak üretim düzeyinde o bireyin elde ettiği marjinal faydaya', ['Ülkedeki tüm mükelleflerin yıllık toplam servetlerinin aritmetik ortalamasına', 'Kamusal malın toplam üretim maliyetinin ülke nüfusuna bölünmesiyle bulunan sabit tutara', 'En yüksek gelirli vergi mükellefinin özel tüketim harcamalarının marjinal maliyetine'], 'Lindahl fiyatlamasında herkes aynı miktarda kamusal malı tüketir ancak her birey kendi marjinal değerlemesi (MB_i) kadar kişiselleştirilmiş vergi fiyatı öder.'),
  ('Lindahl fiyatlama mekanizmasının teorik olarak Pareto etkin bir sonuç üretmesine rağmen gerçek hayatta uygulanmasını engelleyen en önemli sorun nedir?', 'Bireylerin daha düşük vergi payı ödemek amacıyla kamusal mala verdikleri gerçek değeri gizleme güdüsü taşıması', ['Devletin topladığı kişiselleştirilmiş vergi gelirlerinin her zaman üretim maliyetinin altında kalması', 'Kamusal malların marjinal üretim maliyetinin sıfır olması nedeniyle hiçbir fiyat oranının tanımlanamaması', 'Kişiselleştirilmiş vergi oranlarının özel malların piyasa talebini tamamen ortadan kaldırması'], 'Vergi payı beyan edilen marjinal faydaya bağlandığında, rasyonel bireyler kamusal maldan hiç hoşlanmıyormuş gibi davranarak bedavacılık yapmaya yönelir.'),
  ('Charles Tiebout\'nun \'ayaklarıyla oy verme\' (voting with one\'s feet) hipotezine göre yerel kamusal mallarda tercih açıklaması sorunu hangi mekanizmayla aşılabilir?', 'Vatandaşların kendi vergi-hizmet paketi tercihlerine en uygun yerel yönetim bölgesine taşınarak yerleşmesiyle', ['Merkezi hükümetin tüm belediyelerde tek tip vergi oranı ve standart park hizmeti zorunluluğu getirmesiyle', 'Yerel seçimlerde oy kullanmayan seçmenlerin belediye sınırları dışına zorunlu göçe tabi tutulmasıyla', 'Belediye hizmetlerinin tamamının özelleştirilerek yalnızca kredi kartıyla tekil kullanıma açılmasıyla'], 'Tiebout modelinde tam hareketlilik ve çok sayıda yerel yönetim varsayımı altında bireyler istedikleri kamu hizmeti-vergi bileşimini sunan beldeye taşınarak tercihlerini açık eder.'),
  ('Özel hayır kurumlarının kamusal nitelikli bir hizmeti finanse etmek için yürüttüğü bağış kampanyasına devletin vergi gelirleriyle ek ödenek aktarması sonucunda gönüllü bağışların bire bir azalmasına ne ad verilir?', 'Tam dışlama etkisi (crowding-out)', ['Mali sürüklenme etkisi (fiscal drag)', 'Vergi yansıması etkisi (tax shifting)', 'Ölçek ekonomisi etkisi (economies of scale)'], 'Bireyler yalnızca kamusal malın toplam arz düzeyini önemsiyorsa (saf fedakârlık modeli), devletin vergiyle sunduğu her 1 TL özel gönüllü bağışları 1 TL azaltarak tam dışlama yaratabilir.'),
  ('Küçük ve birbirini tanıyan mahalle veya köy topluluklarında bedavacılık sorununun milyonluk metropollere kıyasla daha hafif yaşanmasının temel iktisadi açıklaması nedir?', 'Tekrarlanan yüz yüze ilişkiler sayesinde sosyal dışlama, itibar kaybı ve karşılıklı denetimin düşük maliyetle işleyebilmesi', ['Küçük yerleşim yerlerinde üretilen tüm malların teknik olarak tüketimde tam rekabetçi özel mallara dönüşmesi', 'Köy nüfusu azaldıkça kamusal malların marjinal üretim maliyetinin negatif değerler almaya başlaması', 'Küçük gruplardaki bireylerin kendi kişisel çıkarlarını tamamen unutarak yalnızca başkalarının tüketimini düşünmesi'], 'Mancur Olson\'un kolektif eylem kuramına göre küçük gruplarda bireysel pay daha görünürdür ve sosyal baskı/tekrarlı oyun mekanizmaları bedavacılığı caydırır.'),
  ('Bir kimya fabrikasının özel marjinal maliyeti MPC = 20 + 2Q, ürettiği birim başına çevreye verdiği marjinal dışsal zarar MED = Q ve piyasa ters talep eğrisi P = 110 - Q ise rekabetçi piyasa dengesi (Q_p) ile sosyal optimal üretim düzeyi (Q_s) sırasıyla kaçtır?', 'Q_p = 30 ve Q_s = 22,5', ['Q_p = 22,5 ve Q_s = 30', 'Q_p = 45 ve Q_s = 30', 'Q_p = 30 ve Q_s = 15'], 'Piyasa dengesinde P = MPC => 110 - Q = 20 + 2Q => 3Q = 90 => Q_p = 30. Sosyal optimumda MSB = MSC = MPC + MED = 20 + 3Q => 110 - Q = 20 + 3Q => 4Q = 90 => Q_s = 22,5.'),
  ('Üretimde negatif dışsallık bulunan rekabetçi bir piyasada devlet müdahalesi olmadığında ortaya çıkan refah (dara) kaybı grafiksel olarak hangi alana karşılık gelir?', 'Sosyal optimal miktar ile piyasa miktarı arasında, marjinal sosyal maliyet eğrisinin marjinal sosyal fayda eğrisini aştığı üçgensel alana', ['Sıfır üretim noktası ile sosyal optimal üretim miktarı arasında kalan toplam tüketici ve üretici rantı toplamına', 'Piyasa denge miktarının sağında yer alan ve hiçbir zaman üretilmeyen birimlerin özel marjinal maliyet alanına', 'Marjinal özel maliyet eğrisi ile yatay eksen arasında sıfırdan piyasa çıktısına kadar uzanan toplam değişken maliyete'], 'Q_s ile Q_p arasındaki her birimde topluma yüklenen maliyet (MSC) toplumun elde ettiği faydadan (MSB) büyüktür; bu farkların toplamı aşırı üretim kaynaklı dara kaybını verir.'),
  ('Çevre ekonomisinde sosyal optimal kirlilik düzeyinin genellikle \'sıfır kirlilik\' olmaması iktisadi açıdan nasıl açıklanır?', 'Üretimin sağladığı marjinal sosyal fayda pozitifken kirliliği sıfırlamanın marjinal arıtma maliyetinin çok yüksek düzeylere tırmanmasıyla', ['Ekonomistlerin çevre sağlığına ve ekosistem dengesine hiçbir refah ağırlığı vermemesiyle', 'Kirlilik miktarı sıfıra yaklaştıkça marjinal dışsal zararın sonsuza doğru artış göstermesiyle', 'Teknolojik olarak filtre ve arıtma tesislerinin emisyonları yüzde bir bile azaltma kapasitesinin bulunmamasıyla'], 'Optimal kirlilik düzeyi, marjinal azaltım (arıtma) maliyetinin (MAC) marjinal dışsal zarara (MD) eşitlendiği noktadır; kirliliği tamamen sıfırlamak çoğu kez faydasından çok daha büyük üretim kaybı yaratır.'),
  ('Bir tüketicinin komşularını rahatsız edecek düzeyde yüksek sesli müzik sistemi kullanması gibi \'tüketimde negatif dışsallık\' durumunda piyasa ve sosyal eğriler arasındaki ilişki nasıldır?', 'Marjinal sosyal fayda eğrisi, marjinal özel fayda (piyasa talebi) eğrisinin marjinal dışsal zarar kadar altında yer alır', ['Marjinal sosyal maliyet eğrisi, marjinal özel maliyet eğrisinin marjinal dışsal fayda kadar altında yer alır', 'Marjinal sosyal fayda eğrisi, marjinal özel fayda eğrisinin marjinal dışsal zarar kadar üzerinde yer alır', 'Piyasa denge miktarı sosyal optimal miktarın altında kalarak eksik tüketim sorunu ortaya çıkar'], 'Tüketimde negatif dışsallıkta MSB = MPB - MED olduğundan sosyal fayda eğrisi özel talep eğrisinin altındadır ve serbest piyasa sosyal optimumdan fazla tüketim üretir.'),
  ('Bir teknoloji firmasının özel marjinal faydası MPB = 100 - 2Q olan bir Ar-Ge yazılımı tükettiğini, her birimin sektöre MEB = 20 TL sabit dışsal fayda yaydığını ve arzın MC = 20 + 2Q olduğunu varsayalım. Piyasa miktarı ve sosyal optimal miktar kaçtır?', 'Piyasa miktarı 20, sosyal optimal miktar 25', ['Piyasa miktarı 25, sosyal optimal miktar 20', 'Piyasa miktarı 20, sosyal optimal miktar 30', 'Piyasa miktarı 15, sosyal optimal miktar 25'], 'Piyasada MPB = MC => 100 - 2Q = 20 + 2Q => 4Q = 80 => Q_p = 20. Sosyal optimumda MSB = MPB + MEB = 120 - 2Q = 20 + 2Q => 4Q = 100 => Q_s = 25.'),
  ('Ters talep eğrisi P = 80 - Q, özel marjinal maliyeti MPC = 20 + Q ve marjinal dışsal zararı MED = Q olan bir piyasada sosyal optimumu sağlayacak birim başına Pigou vergisi kaç TL olmalıdır?', '20 TL', ['30 TL', '15 TL', '40 TL'], 'Önce sosyal optimal çıktı bulunur: MSB = MSC => 80 - Q = 20 + Q + Q => 3Q = 60 => Q_s = 20. Bu noktadaki marjinal dışsal zarar MED(20) = 20 TL olduğundan optimal Pigou vergisi 20 TL\'dir.'),
  ('Çevre vergilerinde tartışılan \'çifte kazanç\' (double dividend) hipotezi aşağıdakilerden hangisini savunur?', 'Kirlilik vergisinin bir yandan çevresel zararı azaltırken diğer yandan sağladığı gelirle işgücü veya sermaye üzerindeki bozucu vergilerin indirilebilmesini', ['Çevre vergisi koyan ülkenin hem ithalatını hem de ihracatını aynı yıl içinde tam iki katına çıkarabilmesini', 'Kirletici firmaların hem devletten teşvik primi alıp hem de tüketicilere iki kat yüksek fiyattan mal satabilmesini', 'Toplanan çevre vergilerinin yarısının kirletici fabrikalara diğer yarısının ise yabancı yatırımcılara faizsiz kredi olarak dağıtılmasını'], 'Çifte kazanç hipotezine göre birinci kazanç çevre kalitesinin iyileşmesi, ikinci kazanç ise elde edilen kamu geliriyle gelir/ücret vergisi gibi dara kaybı yaratan vergilerin düşürülmesidir.'),
  ('Pigou vergisini uygulamada zorlaştıran en temel \'bilgi sorunu\' aşağıdakilerden hangisidir?', 'Düzenleyici kurumun binlerce farklı kaynağın marjinal azaltım maliyetlerini ve alıcıların marjinal zarar fonksiyonlarını tam olarak gözlemleyememesi', ['Maliye bakanlığının birim başına vergi tahsil etmek için kullanabileceği hiçbir yasal mevzuat aracının bulunmaması', 'Vergi oranının pozitif bir sayı olarak belirlenmesinin aritmetik kurallarına aykırı düşmesi', 'Tüketicilerin fiyat değişimlerine karşı talep esnekliğinin tüm mallarda mutlak olarak sonsuz olması'], 'Optimal vergiyi (t* = MED(Q_s)) hesaplamak için devletin sosyal optimum noktasını, dolayısıyla hem özel maliyet/azaltım eğrilerini hem de dışsal zarar eğrisini doğru bilmesi gerekir.'),
  ('Çevreyi kirleten bir fabrikada \'üretilen çelik tonu başına vergi\' yerine \'bacadan çıkan kükürt dioksit tonu başına emisyon vergisi\' konulması neden iktisaden daha etkindir?', 'Emisyon vergisinin firmayı yalnız üretimi kısmaya değil filtre takma ve temiz girdi kullanma gibi doğrudan kirlilik azaltıcı teknolojilere de yöneltmesi', ['Çıktı başına konulan verginin fabrikanın çelik üretim miktarını azaltmak yerine her zaman artırması', 'Emisyon ölçüm cihazlarının kurulumunun tüm sanayi kollarında tamamen sıfır maliyetle gerçekleştirilebilmesi', 'Kükürt dioksit vergisinin çelik tüketicilerinin ödediği piyasa fiyatını hiçbir koşulda etkilememesi'], 'Çıktı vergisi yalnız ölçek etkisiyle kirliliği azaltırken, doğrudan emisyon başına konulan vergi hem ölçek hem de temiz teknoloji ikamesi teşviki yaratarak aynı azaltımı daha düşük maliyetle sağlar.'),
  ('Büyük bir metropoldeki yüz binlerce otomobilin egzoz gazından milyonlarca kentlinin etkilenmesi durumunda Coasecu özel pazarlığın işlememesinin ana nedeni nedir?', 'Taraf sayısının çokluğu nedeniyle örgütlenme, koordinasyon, sözleşme yapma ve bedavacılığı önleme işlem maliyetlerinin aşırı yüksek olması', ['Otomobil egzozundan çıkan gazların insan sağlığı üzerinde hiçbir dışsal maliyet oluşturmaması', 'Kentteki otomobillerin tamamının özel mülkiyete değil belediyelerin ortak mülkiyetine ait olması', 'Sürücülerin yakıt fiyatlarındaki değişimlere karşı her zaman pozitif eğimli talep eğrisi sergilemesi'], 'Coase teoremi az sayıda taraf (komşu çiftçi ile sığır yetiştiricisi gibi) arasında anlamlıdır; milyonlarca kirletici ve mağdur olduğunda işlem maliyetleri (transaction costs) pazarlığı imkânsız kılar.'),
  ('Pazarlık sürecinde mağdur tarafın elindeki \'veto/durdurma emri\' gücünü kullanarak gerçek zararını abartması ve anlaşmayı kilitlemesi olgusuna hukuk ve iktisat literatüründe ne ad verilir?', 'Diretme / rehin tutma sorunu (holdout problem)', ['Ters seçim çarpanı (adverse selection multiplier)', 'Mali yanılsama etkisi (fiscal illusion effect)', 'Ricardo denklik teoremi (Ricardian equivalence)'], 'Özellikle birden fazla hak sahibinin onayının gerektiği durumlarda her bir tarafın pastadan daha büyük pay koparmak için son onay veren olmaya çalışması (holdout) Coasecu anlaşmayı bozar.'),
  ('Çevre politikasında \'komuta ve kontrol\' (command-and-control) yaklaşımı kapsamında tüm fabrikalara eşit miktarda emisyon azaltımı zorunluluğu getirilmesi neden maliyet-etkin değildir?', 'Farklı fabrikaların marjinal azaltım maliyetleri farklı olduğu için arıtması ucuz olanla pahalı olana aynı yükü bindirip toplam maliyeti büyütmesi', ['Yasal standartların fabrikaların emisyonlarını fiziksel olarak hiçbir koşulda bir gram bile düşürememesi', 'Eşit azaltım kuralının yalnızca arıtma maliyeti en düşük olan fabrikaları koruyup diğerlerini vergiden muaf tutması', 'Komuta ve kontrol yönteminde devletin fabrikalara piyasa fiyatının üzerinde karbon sertifikası satmak zorunda kalması'], 'Toplam azaltım maliyetinin minimum olması için tüm firmaların marjinal azaltım maliyetlerinin (MAC_A = MAC_B) eşitlenmesi gerekir; tek tip miktar standardı MAC farklılıklarını göz ardı eder.'),
  ('İki fabrikadan A\'nın marjinal emisyon azaltım maliyeti MAC_A = 2e_A ve B\'nin MAC_B = 6e_B\'dir. Toplam 40 birim emisyon azaltımı hedeflendiğinde en düşük toplam maliyet için A ve B sırasıyla kaç birim azaltım yapmalıdır?', 'A fabrikası 30 birim, B fabrikası 10 birim', ['A fabrikası 20 birim, B fabrikası 20 birim', 'A fabrikası 10 birim, B fabrikası 30 birim', 'A fabrikası 35 birim, B fabrikası 5 birim'], 'Maliyet etkinliği koşulu MAC_A = MAC_B => 2e_A = 6e_B => e_A = 3e_B. Toplam azaltım e_A + e_B = 40 olduğundan 3e_B + e_B = 40 => e_B = 10 birim ve e_A = 30 birim bulunur.'),
  ('Üst sınır ve ticaret (cap-and-trade / alınıp satılabilir kirlilik izinleri) sisteminde bir firmanın elindeki emisyon iznini satmak yerine tutup kendi emisyonunu azaltmayı seçmesi hangi koşulda gerçekleşir?', 'Firmanın marjinal azaltım maliyetinin izin piyasasındaki cari sertifika fiyatından düşük olduğu durumda (emisyonu azaltıp izni satar)', ['Firmanın marjinal azaltım maliyetinin piyasadaki sertifika fiyatının üç katı olduğu durumda (azaltım yapıp izin yakar)', 'İzin piyasasındaki sertifika fiyatının sıfır TL\'ye düştüğü ve hiçbir alıcının bulunmadığı durumda', 'Devletin toplam emisyon üst sınırını (cap) her yıl sınırsız biçimde genişlettiği durumda'], 'Not: Firma kendi MAC değeri izin fiyatından (P) düşükse emisyonu kendisi azaltır ve boşa çıkan izni piyasada P fiyatından satarak aradaki fark kadar kazanç sağlar; MAC > P olan firma ise izin satın alır.'),
  ('Çevreci bir sivil toplum kuruluşunun \'alınıp satılabilir emisyon borsasından\' kirlilik sertifikaları satın alıp bunları hiç kullanmadan emekliye ayırması (iptal etmesi) piyasayı nasıl etkiler?', 'Fiili toplam emisyon arzını daraltarak sertifika fiyatını yükseltir ve toplam kirliliği devletin koyduğu tavanın da altına çeker', ['Sertifika fiyatını düşürerek kirletici fabrikaların daha ucuza kömür yakmasına zemin hazırlar', 'Pigou vergisi sisteminde de aynı şekilde vergi makbuzları satın alınarak emisyon tavanı daraltılabilir', 'Fabrikaların marjinal özel üretim maliyetlerini sıfıra indirerek sanayi üretimini hızlandırır'], 'Cap-and-trade sisteminin önemli bir özelliği üçüncü tarafların (çevrecilerin) piyasadan izin çekerek temiz çevre için ödeme istekliliklerini doğrudan emisyon düşüşüne dönüştürebilmeleridir.'),
  ('Oylama döngüsünün (Condorcet paradoksunun) var olduğu bir mecliste komisyon başkanının oylama sırasını belirleme yetkisine (\'gündem belirleme gücü\') sahip olması neden kritik önem taşır?', 'Başkanın ikili eleme sırasını stratejik kurgulayarak kendi tercih ettiği seçeneği nihai kazanan haline getirebilmesi', ['Oylama sırası değiştiğinde milletvekillerinin bireysel tercih sıralamalarının anayasal olarak silinmesi', 'Gündem belirleme yetkisinin tüm oylamaları otomatik olarak oybirliği kuralına dönüştürmesi', 'Döngüsel tercihler altında hangi sıra seçilirse seçilsin her zaman aynı seçeneğin kazanmasının kesin olması'], 'A > B, B > C ve C > A döngüsünde başkan önce A ile B\'yi oylatıp (kazanan A) sonra C ile yarıştırırsa C kazanır; önce B ile C\'yi oylatırsa A kazanır.'),
  ('William Niskanen\'in bürokrasi modeline göre kamu kurumlarını yöneten bürokratların bilgi asimetrisinden yararlanarak maksimize etmeye çalıştıkları temel büyüklük nedir?', 'Başında bulundukları kamu dairesinin toplam bütçe büyüklüğü', ['Hazineye devredilecek yıl sonu bütçe tasarrufu ve harcanmayan ödenek fazlası', 'Kamu hizmetinin marjinal sosyal faydasının marjinal sosyal maliyetine tam eşitlendiği net refah fazlası', 'Kurumda çalışan personel sayısının en aza indirilmesiyle ulaşılan birim işgücü verimliliği'], 'Niskanen\'e göre bürokratın prestiji, gücü ve olanakları yönettiği bütçeyle doğru orantılıdır; maliyet bilgisi tekelini kullanarak meclisten toplam faydanın toplam maliyete eşit olduğu noktaya kadar aşırı bütçe koparabilir.'),
  ('Şeker üreticileri birliğinin ithal şekere yüksek gümrük duvarı koydurmayı kolayca başarabilmesinin temel nedeni, kamu tercihi kuramındaki hangi asimetriyle açıklanır?', 'Faydanın küçük ve iyi örgütlü bir üretici grubunda yoğunlaşması, maliyetin ise milyonlarca tüketiciye kişi başı küçük tutarlar halinde dağılması', ['Tüketicilerin şeker fiyatlarının yükselmesinden her zaman pozitif tüketici rantı elde etmesi', 'Ülkedeki seçmen sayısının şeker fabrikası sahiplerinin sayısından daha az olması', 'Gümrük vergilerinin yerli üreticilerin kârını düşürüp yalnızca yabancı ihracatçıları zenginleştirmesi'], 'Yoğunlaşmış faydalar - dağınık maliyetler (concentrated benefits, dispersed costs) yapısında üretici lobisinin örgütlenme getirisi çok yüksekken, tüketicilerin kişi başı kaybı lobi maliyetini karşılamaz.'),
  ('Vergi yükünün dağıtımında \'fayda (yararlanma) ilkesi\' ile \'ödeme gücü ilkesi\' arasındaki temel felsefi fark nedir?', 'Fayda ilkesi vergiyi kamu hizmetinden elde edilen yararlanmayla ilişkilendirirken, ödeme gücü ilkesi hizmet kullanımından bağımsız olarak gelir ve servet kapasitesini esas alır', ['Fayda ilkesi yalnızca yoksullardan yüksek vergi alınmasını savunurken, ödeme gücü ilkesi herkesten eşit kelle vergisi alınmasını savunur', 'Ödeme gücü ilkesi otoyol geçiş ücretleri için geçerliyken, fayda ilkesi işsizlik yardımlarının finansmanı için tek geçerli ilkedir', 'Her iki ilke de vergi oranlarının gelir düzeyi yükseldikçe sıfıra indirilmesini zorunlu kılar'], 'Fayda yaklaşımı (Wicksell, Lindahl) vergiyi kamu hizmetinin fiyatı gibi görür; ödeme gücü yaklaşımı ise yeniden dağılım hizmetlerini de kapsayacak şekilde mali iktidara göre vergilendirmeyi savunur.'),
  ('Aylık geliri 50.000 TL olan bir mükellef 9.000 TL vergi ödüyor ve geliri 60.000 TL\'ye çıktığında toplam vergi borcu 11.500 TL oluyorsa, bu mükellefin son gelir dilimindeki \'ortalama vergi oranı\' (OVO) ile \'marjinal vergi oranı\' (MVO) sırasıyla yüzde kaçtır?', 'Ortalama vergi oranı %19,17 civarı (11,5/60) iken marjinal vergi oranı %25\'tir', ['Ortalama vergi oranı %25 iken marjinal vergi oranı %18\'dir', 'Ortalama vergi oranı %18 iken marjinal vergi oranı %19,17\'dir', 'Hem ortalama vergi oranı hem de marjinal vergi oranı %23\'tür'], '60.000 TL gelirde OVO = 11.500 / 60.000 ≈ %19,17. Ek 10.000 TL gelir için ödenen ek vergi 11.500 - 9.000 = 2.500 TL olduğundan MVO = 2.500 / 10.000 = %25\'tir.'),
  ('Bir vergi tarifesinin iktisadi anlamda \'artan oranlı\' (müterakki / progressive) olarak tanımlanabilmesi için gerekli ve yeterli koşul nedir?', 'Gelir (matrah) arttıkça ortalama vergi oranının yükselmesi, yani marjinal vergi oranının ortalama vergi oranından büyük olması', ['Gelir arttıkça ödenen mutlak vergi tutarının TL cinsinden artması ancak ortalama oranın sabit kalması', 'Düşük gelirlilerden alınan vergi oranının yüksek gelirlilerden alınan vergi oranından daha yüksek olması', 'Marjinal vergi oranının sıfır olduğu tüm gelir dilimlerinde sabit tutarlı vergi tahsil edilmesi'], 'Yalnızca ödenen vergi tutarının artması düz oranlı vergide de görülür; artan oranlılık ortalama vergi oranının (T/Y) gelirle birlikte yükselmesini gerektirir.'),
  ('Herkesten geliri ne olursa olsun yıllık sabit 6.000 TL alınan bir \'baş vergisi\' (kelle vergisi / lump-sum tax), gelir düzeyi açısından nasıl bir tarife etkisi yaratır?', 'Gelir yükseldikçe ödenen verginin gelire oranı (ortalama vergi oranı) düştüğü için tersine artan oranlı (regresif) etki yaratır', ['Herkesten eşit TL tutarı tahsil edildiği için gelir dağılımı üzerinde tam düz oranlı (mütenasip) etki yaratır', 'Yüksek gelirlilerin marjinal vergi oranını %100\'e çıkardığı için güçlü bir artan oranlı etki yaratır', 'Düşük gelirlilerin harcanabilir gelirini artırdığı için Gini katsayısını sıfıra doğru yaklaştırır'], '6.000 TL vergi, 30.000 TL gelirli için %20 iken 600.000 TL gelirli için %1 ortalama vergi yükü demektir; ortalama oran gelirle düştüğünden regresiftir.'),
  ('Ekmek, un ve yemeklik yağ gibi zorunlu gıda maddeleri üzerinden tek tip oranda alınan Katma Değer Vergisi (KDV), hanehalklarının yıllık toplam gelirleri baz alındığında neden genellikle \'tersine artan oranlı\' (regresif) sonuç doğurur?', 'Düşük gelirli hanelerin gelirlerinin çok büyük kısmını gıdaya harcaması, yüksek gelirlilerin ise gelirlerinin önemli kısmını tasarruf etmesi yüzünden', ['Süpermarket kasalarında yüksek gelirli müşterilere yasal olarak daha düşük KDV oranı uygulanması yüzünden', 'Zengin hanelerin mutlak gıda harcaması tutarının yoksul hanelerin mutlak harcamasından TL bazında daha az olması yüzünden', 'Katma Değer Vergisi oranlarının enflasyon dönemlerinde kendiliğinden negatif değerlere düşmesi yüzünden'], 'Marjinal ve ortalama tüketim eğilimi gelir yükseldikçe azaldığından, temel tüketim üzerindeki sabit oranlı dolaylı vergiler yoksulların gelirinden oransal olarak daha büyük pay alır.'),
  ('Artan oranlı gelir vergisinde \'sınıf usulü\' ile \'dilim usulü\' tarifeler arasındaki en kritik fark aşağıdakilerden hangisidir?', 'Sınıf usulünde üst basamağa geçen matrahın tamamına yeni yüksek oran uygulanırken, dilim usulünde yüksek oran yalnızca eşiği aşan kısma uygulanır', ['Dilim usulünde üst dilime geçen mükellefin vergi sonrası net geliri bir önceki dilime göre mutlak olarak azalır', 'Sınıf usulünde marjinal vergi oranı basamak geçiş noktalarında her zaman sıfıra eşitlenir', 'Dilim usulü yalnızca dolaylı tüketim vergilerinde kullanılırken sınıf usulü modern gelir vergilerinin tamamında standarttır'], 'Sınıf usulünde basamak sınırını 1 TL aşmak tüm gelirin üst orandan vergilendirilmesine ve marjinal oranın %100\'ü aşmasına yol açar; dilim usulü bu sıçramayı önler.'),
  ('Gelir vergisi dilimleri şöyle tanımlanmıştır: 0–100.000 TL arası %15; 100.000–250.000 TL arası %20; 250.000 TL üzeri %30. Dilim usulüne göre 300.000 TL vergiye tabi geliri olan bir mükellef toplam kaç TL vergi öder?', '60.000 TL', ['90.000 TL', '67.500 TL', '55.000 TL'], 'İlk 100.000 TL için %15 = 15.000 TL; sonraki 150.000 TL (100 bin-250 bin arası) için %20 = 30.000 TL; son 50.000 TL (250 bin-300 bin arası) için %30 = 15.000 TL. Toplam = 15.000 + 30.000 + 15.000 = 60.000 TL.'),
  ('Enflasyonist bir ekonomide bireyin reel satın alma gücü hiç artmadığı halde nominal maaş zamları nedeniyle dilim usulü gelir vergisinde üst vergi dilimlerine kayarak reel vergi yükünün ağırlaşmasına ne ad verilir?', 'Mali sürüklenme / dilim kayması (bracket creep)', ['Olivera-Tanzi aşınma etkisi', 'Verginin sermayeleştirilmesi (amortismanı)', 'Vergi cenneti arbitrajı'], 'Vergi dilimi sınırları enflasyon oranında tam endekslenmezse, salt nominal gelir artışı mükellefi üst dilimlere taşır ve reel ortalama vergi oranını gizlice yükseltir.'),
  ('Yüksek enflasyon ortamında vergiyi doğuran olay ile verginin hazineye fiilen ödendiği tarih arasında geçen süre nedeniyle devletin topladığı vergi gelirlerinin reel değerinin erimesini açıklayan kavram hangisidir?', 'Olivera-Tanzi etkisi', ['Haavelmo denk bütçe çarpanı', 'Peacock-Wiseman sıçrama etkisi', 'Baumol maliyet hastalığı etkisi'], 'Tahakkuk ile tahsilat arasındaki gecikme süresi uzadıkça yüksek enflasyon devletin vergi tahsilatının reel alım gücünü aşındırır; buna Olivera-Tanzi etkisi denir.'),
  ('Rekabetçi bir mal piyasasında talep fiyat esnekliği mutlak değerce 0,5 (inancıl/esnek olmayan) ve arz fiyat esnekliği 2,0 (esnek) ise, konulan küçük bir birim verginin ekonomik yükü nasıl paylaşılır?', 'Vergi yükünün %80\'i talep esnekliği daha düşük olan tüketicilerin, %20\'si ise üreticilerin üzerinde kalır', ['Vergi yükünün %80\'i arz esnekliği yüksek olan üreticilerin, %20\'si ise tüketicilerin üzerinde kalır', 'Vergi kanunen üreticiden tahsil edildiği sürece %100\'ü üreticinin kârından karşılanır', 'Alıcı ve satıcılar her zaman vergiyi %50 - %50 eşit oranda paylaşır'], 'Tüketicinin payı = E_s / (E_s + |E_d|) = 2,0 / (2,0 + 0,5) = 2 / 2,5 = %80. Kural olarak piyasanın hangi tarafı fiyata daha az duyarlıysa (daha inelastikse) vergi yükünün büyük kısmını o taraf taşır.'),
  ('Arz miktarının tamamen sabit olduğu (arz fiyat esnekliğinin sıfır olduğu) imarsız ham arsa piyasasında, arsa rantı üzerine konulan yıllık verginin yansıması hakkında Henry George teoremiyle uyumlu olarak ne söylenebilir?', 'Arz tamamen esneksiz olduğu için vergi kiracılara yansıtılamaz, tamamı arsa sahibi üzerinde kalır ve üretimde dara kaybı yaratmaz', ['Arsa sahipleri verginin tamamını kira artışı yoluyla kiracılara yansıtarak arsa arzını yarı yarıya azaltır', 'Arz esnekliği sıfır olduğunda konulan her vergi piyasadaki denge işlem miktarını sıfıra indirir', 'Vergi yükü yalnızca arsayı gelecekte satın alacak kişilere yansır, mevcut arsa sahibinin serveti hiç değişmez'], 'Tam inelastik arzda (E_s = 0) arz eğrisi diktir; vergi denge miktarını değiştirmez (sıfır dara kaybı) ve verginin %100\'ü ekonomik rant sahibi olan toprak malikinde kalır.'),
  ('Rekabetçi bir piyasada birim başına vergi oranı (t) iki katına çıkarıldığında, doğrusal arz ve talep eğrileri altında verginin yarattığı \'aşırı yük\' (dara kaybı / Harberger üçgeni) yaklaşık kaç katına çıkar?', 'Dört katına çıkar', ['İki katına çıkar', 'Yarıya düşer', 'Değişmeden aynı kalır'], 'Verginin dara kaybı DWL = 0,5 * t * ΔQ formülüyle hesaplanır ve ΔQ da t ile orantılı olduğundan DWL vergi oranının karesiyle (t^2) orantılı büyür; oran 2 katına çıkınca refah kaybı 4 katına çıkar.'),
  ('Ücret geliri üzerine konulan gelir vergisinin bireyin çalışma-boş zaman (emek arzı) kararında yarattığı \'ikame etkisi\' ile \'gelir etkisi\' hangi yönlerde çalışır?', 'İkame etkisi boş zamanın fırsat maliyetini düşürerek çalışmayı azaltırken, gelir etkisi bireyi yoksullaştırdığı için daha çok çalışmaya iter', ['Hem ikame etkisi hem de gelir etkisi çalışma saatlerini kesin olarak her ücret düzeyinde artırır', 'İkame etkisi bireyi daha fazla mesai yapmaya zorlarken, gelir etkisi boş zaman tüketimini her zaman artırır', 'Ücret vergisi boş zamanın nispi fiyatını yükselttiği için ikame etkisi dinlenme süresini sıfıra indirir'], 'Net ücreti düşüren vergi, 1 saatlik boş zamandan vazgeçmenin getirisini azaltır (ikame etkisi -> daha az çalışma); aynı zamanda geliri düşen birey boş zaman normal malsa daha az dinlenip daha çok çalışmak ister (gelir etkisi).'),
  ('Devletin bütçeden doğrudan nakit sübvansiyon vermek yerine vergi kanunlarına koyduğu muafiyet, istisna, indirim ve indirimli oranlar yoluyla vazgeçtiği vergi gelirlerine bütçe literatüründe ne ad verilir?', 'Vergi harcaması', ['Bütçe dışı kefalet fonu', 'Parasal genişleme açığı', 'Otonom vergi fazlası'], 'Stanley Surrey tarafından kavramsallaştırılan vergi harcaması, standart vergi sisteminden sapmalar yoluyla belirli kesimlere sağlanan dolaylı mali destekleri ve vazgeçilen hasılatı ifade eder.'),
  ('Gelir dağılımı ölçütlerinde geçerli olan \'Pigou-Dalton transfer ilkesi\' neyi şart koşar?', 'Sıralamayı değiştirmeden daha zengin bir bireyden daha yoksul bir bireye yapılan kayıpsız gelir transferinin eşitsizlik endeksini kesinlikle düşürmesini', ['Yoksul bir bireyden zengin bir girişimciye yapılan servet transferinin Gini katsayısını her zaman sıfıra yaklaştırmasını', 'Ülkedeki tüm bireylerin gelirleri aynı oranda (%10 gibi) arttığında eşitsizlik katsayısının da %10 yükselmesini', 'Devletin topladığı transfer ödemelerinin idari işlem maliyetinin toplam vergi gelirinin yarısına eşit olmasını'], 'Tutarlı her eşitsizlik ölçütü (Gini, Atkinson, Theil dahil) zengin birinden yoksul birine yapılan geriletici olmayan (rank-preserving) transfer sonrasında eşitsizliğin azaldığını göstermelidir.'),
  ('Bir ülkedeki her vatandaşın geliri enflasyon veya ekonomik büyüme sonucunda tam iki katına çıkarsa Lorenz eğrisi ve Gini katsayısı nasıl değişir?', 'Göreli gelir payları değişmediği için ne Lorenz eğrisi kayar ne de Gini katsayısı değişir', ['Herkes zenginleştiği için Lorenz eğrisi mutlak eşitlik doğrusuna yaklaşır ve Gini katsayısı yarıya düşer', 'Zenginlerin mutlak TL artışı yoksullardan büyük olduğu için Gini katsayısı tam iki katına çıkar', 'Lorenz eğrisi 45 derece doğrusunun sol üst tarafına geçerek negatif Gini katsayısı üretir'], 'Gini katsayısı \'ölçekten bağımsızlık\' (scale invariance) özelliğine sahiptir; tüm gelirler sabit bir pozitif katsayıyla çarpıldığında yüzdesel paylar aynı kalır.'),
  ('Vergi ve sosyal transfer politikalarının gelir dağılımını düzeltme başarısı değerlendirilirken \'piyasa geliri Gini katsayısı\' 0,48 iken \'harcanabilir gelir Gini katsayısı\' 0,34 olarak ölçülmüşse bu fark neyi gösterir?', 'Artan oranlı vergiler ve nakdi sosyal transferlerin gelir eşitsizliğini 0,14 puan düşürerek yeniden dağıtıcı işlev gördüğünü', ['Maliye politikasının gelir dağılımını bozarak zenginlerden yoksullara değil yoksullardan zenginlere kaynak aktardığını', 'Ülkedeki kayıt dışı ekonominin milli gelirin tam %14\'üne ulaştığını ve vergi gelirlerinin sıfırlandığını', 'Dolaylı tüketim vergilerinin tek başına tüm gelir farklılıklarını ortadan kaldırıp tam eşitlik sağladığını'], 'Vergi ve transfer öncesi (piyasa/faktör geliri) Gini ile vergi düşülüp sosyal yardımlar eklendikten sonraki (harcanabilir gelir) Gini arasındaki düşüş maliye politikasının yeniden dağılım etkisini ölçer.'),
  ('Yalnızca yoksulluk sınırının altındaki kişi sayısının toplam nüfusa oranını gösteren \'kafa sayısı endeksi\'nin (headcount ratio) en önemli eksikliği nedir?', 'Yoksulların sınırın ne kadar altında yaşadığını (yoksulluk derinliğini) ve yoksullar arasındaki eşitsizliği dikkate almaması', ['Ülke nüfusu arttığında yoksul sayısı sabit kalsa bile oranı her zaman daha yüksek göstermesi', 'Yoksulluk sınırının üzerindeki milyarderlerin servet artışlarına karşı aşırı duyarlı olması', 'Hesaplanabilmesi için en az elli yıllık kesintisiz panel veri setine zorunlu ihtiyaç duyması'], 'Kafa sayısı oranında çok yoksul birinden sınırın hemen altındaki bir başka yoksula para aktarıp ikincisini sınırın üstüne çıkarmak yoksulluğu azalmış gösterir (Sen\'in eleştirisi); derinliği ölçmez.'),
  ('Milton Friedman\'ın yoksullukla mücadelede çalışma teşvikini tamamen öldürmemek için önerdiği \'Negatif Gelir Vergisi\' (Negative Income Tax) sistemi nasıl işler?', 'Belirlenen eşik gelirin altında kalanlara devletin nakit destek ödemesi, birey çalışıp kazandıkça desteğin %100\'den düşük bir marjinal kesinti oranıyla kademeli azalması', ['Çalışmaya başlayan her yoksul vatandaşın kazandığı ilk liradan itibaren tüm sosyal yardımının tek seferde tamamen kesilmesi', 'Yüksek gelirli mükelleflerin ödedikleri vergilerin yıl sonunda kendilerine faiziyle birlikte nakit olarak iade edilmesi', 'Asgari ücretle çalışan işçilerden %50 oranında ek bordro vergisi kesilerek işverenlere teşvik primi dağıtılması'], 'Klasik yardımlarda çalışmaya başlayınca yardımın bire bir kesilmesi %100 marjinal vergi (yoksulluk tuzağı) yaratır; Negatif Gelir Vergisi\'nde örneğin T = t*Y - G formülüyle kazanılan her 1 TL harcanabilir geliri (1-t) kadar artırır.'),
  ('Peacock ve Wiseman\'ın kamu harcamalarının tarihsel seyrini açıklayan \'Sıçrama Tezi\'nde (displacement effect) büyük savaş veya krizlerin rolü nedir?', 'Olağanüstü kriz dönemlerinde halkın katlanılabilir vergi yükü algısının yukarı kayması ve kriz bittiğinde harcamaların eski düşük düzeyine geri dönmeyip yüksek platoda kalması', ['Savaş dönemlerinde kamu harcamalarının tamamen durması ve tüm bütçenin özel şirketlere hibe olarak dağıtılması', 'Kriz biter bitmez vergi oranlarının kriz öncesinin de yarısına indirilerek devletin küçültülmesi', 'Kamu harcamalarının krizlerden hiç etkilenmeden her yıl tam sabit %2 oranında pürüzsüz biçimde büyümesi'], 'Barış zamanında vergi direnci kamu harcamalarını kısıtlar; büyük kriz/savaşlar vergi eşiğini yukarı sıçratır ve kriz sonrasında devlet yeni sivil sosyal sorumluluklar üstlenerek o yüksek harcama platosunda kalır.'),
  ('William Baumol\'un \'dengesiz büyüme / maliyet hastalığı\' modeli kamu hizmetlerinin milli gelir içindeki maliyet payının zamanla artmasını nasıl açıklar?', 'Eğitim ve sahne sanatları gibi emek yoğun kamu hizmetlerinde verimlilik yavaş artarken ücretlerin verimliliği hızlı artan sanayi sektörüyle paralel yükselmesiyle', ['Kamu sektöründe çalışan öğretmen ve doktorların maaşlarının yüz yıl boyunca nominal olarak sabit kalmasıyla', 'İmalat sanayiinde teknolojik ilerlemenin tamamen durup işgücü verimliliğinin sürekli gerilemesiyle', 'Devlet dairelerinde otomasyon ve robot kullanımının özel fabrikalardan on kat daha hızlı yaygınlaşmasıyla'], 'Bir öğretmenin kırk kişilik sınıfta ders anlatma verimliliği imalat kadar hızla artmaz ama öğretmen ücretleri ekonomideki genel ücret artışını izlemek zorundadır; bu da kamu hizmetlerinin nispi birim maliyetini sürekli yükseltir.'),
  ('Birinci Refah Teoremi\'nin \'rekabetçi piyasa dengesinin Pareto etkin olduğu\' sonucunun geçerliliğini bozan klasik piyasa başarısızlıkları arasında aşağıdakilerden hangisi YER ALMAZ?', 'Başlangıçtaki servet ve yetenek dağılımının toplumun adalet anlayışına göre eşitsiz olması', ['Tam kamusal malların dışlanamazlık nedeniyle özel piyasada eksik üretilmesi', 'Üretim ve tüketim süreçlerinde fiyatlandırılmamış pozitif veya negatif dışsallıkların bulunması', 'Asimetrik bilgi ve azalan ortalama maliyet kaynaklı doğal tekel gücünün varlığı'], 'Gelir dağılımı adaletsizliği bir \'piyasa başarısızlığı\' (etkinsizlik) değildir; rekabetçi piyasa çok adaletsiz bir dağılımla da Pareto etkin sonuç üretebilir (bölüşüm sorunu İkinci Refah Teoremi ve adalet alanına girer).'),
  ('Jeremy Bentham kaynaklı \'Faydacı\' (Utilitarian) toplumsal refah fonksiyonu (W = U_1 + U_2 + ... + U_n) ile John Rawls\'un \'Maximin\' toplumsal refah fonksiyonu (W = min{U_1, U_2, ..., U_n}) nasıl farklılaşır?', 'Faydacılık bireysel faydaların toplamını maksimize etmeye odaklanırken, Rawlsçu kriter yalnızca toplumdaki en kötü durumda olan bireyin refahını en yükseğe çıkarmayı hedefler', ['Faydacılık yalnızca en zengin bireyin faydasını dikkate alırken, Rawlsçu kriter tüm bireylerin gelirlerinin sıfırlanmasını savunur', 'Her iki refah fonksiyonu da bireyler arasında hiçbir gelir transferi yapılmamasını mutlak kural olarak benimser', 'Rawlsçu kriter eşitsizliğe karşı tamamen kayıtsızken, faydacı kriter azalan marjinal fayda olmasa bile tam eşitliği zorunlu kılar'], 'Rawls\'un \'bilgisizlik peçesi\' (veil of ignorance) ardında türettiği fark ilkesi (maximin), bir eşitsizliği ancak en dezavantajlı bireyin durumunu iyileştiriyorsa kabul eder.'),
  ('Faydacı (Utilitarian) bir toplumsal refah fonksiyonunda \'tüm bireylerin gelirden elde ettikleri marjinal fayda fonksiyonları özdeş ve azalan\' ise ve vergilendirmenin hiçbir çalışma teşviki kaybı (sızıntı) yoksa optimal gelir dağılımı nedir?', 'Bireylerin marjinal faydaları eşitlenene kadar zenginden yoksula transfer yapılarak ulaşılan tam eşit gelir dağılımı', ['Başlangıçtaki piyasa gelirlerinin hiçbir vergiye tabi tutulmadan olduğu gibi korunması', 'Milli gelirin yarısının devlette tutulup kalan yarısının kura yöntemiyle tek bir haneye verilmesi', 'Marjinal faydası düşük olan yüksek gelirlilere yoksullardan kaynak aktarılarak eşitsizliğin büyütülmesi'], 'Edgeworth\'un klasik sonucuna göre W = Σ U(Y_i) ve U\'\' < 0 iken sızıntısız transferde maksimum toplam fayda U\'(Y_1) = U\'(Y_2) = ... koşulunda, yani Y_1 = Y_2 = ... tam eşitlikte sağlanır.'),
  ('Kamu yatırım projelerinin (örneğin yeni bir hızlı tren hattının) yapılabilirliğini değerlendiren \'Sosyal Fayda-Maliyet Analizi\'ni özel bir şirketin kârlılık analizinden ayıran temel özellik nedir?', 'Yalnızca bilet geliri ve inşaat giderini değil zaman tasarrufu, trafik kazalarında azalma ve karbon salımı düşüşü gibi dışsal etkileri de gölge fiyatlarla hesaba katması', ['Gelecek yıllarda oluşacak fayda ve maliyetlere hiçbir iskonto oranı uygulamadan doğrudan toplaması', 'Projede çalıştırılan mühendis ve işçilere ödenen ücretleri maliyet kalemlerinden tamamen silmesi', 'Yalnızca ilk bir yıl içindeki nakit girişlerine bakıp uzun dönemli çevresel zararları yok sayması'], 'Sosyal fayda-maliyet analizi piyasa aksaklıklarını, dışsallıkları, tüketici rantı değişimlerini ve fırsat maliyetlerini (gölge fiyatları) kapsayarak net sosyal bugünkü değeri (NSBD) ölçer.'),
  ('İklim değişikliğiyle mücadele gibi faydaları 50-100 yıl sonrasına yayılan kamu projelerinde daha \'düşük\' bir sosyal iskonto oranının (örneğin %6 yerine %1,5) seçilmesi proje kararını nasıl etkiler?', 'Gelecek kuşakların elde edeceği uzak dönem faydaların bugünkü değerini büyüterek uzun vadeli çevre yatırımlarının kabul edilme olasılığını artırır', ['Uzak gelecekteki çevresel faydaların bugünkü değerini sıfıra indirerek tüm iklim projelerinin reddedilmesine yol açar', 'Projenin başlangıçtaki ilk yıl inşaat maliyetini on kat büyüterek kısa vadeli projeleri öne çıkarır', 'Bugünkü değer hesaplamasında iskonto oranının yüksek ya da düşük olmasının net bugünkü değer üzerinde hiçbir etkisi yoktur'], 'NBBD = Σ B_t / (1 + r)^t formülünde t büyükken (örneğin t=80) r\'nin küçük olması paydadaki küçültme etkisini azaltır ve gelecekteki faydaların bugünkü ağırlığını ciddi ölçüde yükseltir (Stern-Nordhaus tartışması).'),
  ('Piyasada alınıp satılmayan bir sulak alanın veya milli parkın korunmasına halkın biçtiği değeri doğrudan anketlerle \'korunması için en çok kaç TL ödersiniz?\' diye sorarak tahmin eden yönteme ne ad verilir?', 'Koşullu değerleme yöntemi', ['Hedonik fiyatlama yöntemi', 'Seyahat maliyeti yöntemi', 'Savunmacı harcama yöntemi'], 'Koşullu değerleme (stated preference), varsayımsal senaryolar üzerinden anketle ödeme istekliliğini (WTP) ölçer ve kullanım dışı \'varlık değerini\' (existence value) de yakalayabilen tek yöntemdir.'),
  ('Hava kirliliği yüksek mahallelerdeki konutların, diğer tüm fiziksel özellikleri aynı olan temiz havalı mahallelerdeki konutlara göre ne kadar daha ucuza satıldığını ekonometrik olarak inceleyerek temiz havanın zımni değerini tahmin eden yöntem hangisidir?', 'Hedonik fiyatlama yöntemi', ['Koşullu anket oylaması yöntemi', 'Girdi-çıktı matrisi yöntemi', 'Lorenz ayrıştırma yöntemi'], 'Hedonik fiyatlama (açıklanmış tercih / revealed preference), konut veya işgücü gibi farklılaştırılmış piyasa mallarının fiyat farklılıklarından çevresel kalite veya risk özelliklerinin gölge fiyatını çıkarır.'),
  ('Bir kamu politikası değişikliğinde kazananların elde ettiği parasal kazanç kaybedenlerin uğradığı parasal kayıptan büyükse, fiilen tazminat ödenmese bile politikanın toplumsal refahı artırdığını kabul eden ölçüt hangisidir?', 'Kaldor-Hicks potansiyel tazminat ölçütü', ['Mutlak Pareto iyileşmesi ölçütü', 'Rawlsçu en yoksulu koruma ölçütü', 'Condorcet oybirliği ölçütü'], 'Sıkı Pareto iyileşmesi hiç kimsenin zarar görmemesini şart koşar; gerçek dünyadaki projelerde hemen her zaman kaybedenler olduğu için fayda-maliyet analizi Kaldor-Hicks (potansiyel Pareto iyileşmesi) kriterine dayanır.'),
  ('Sermaye ve nitelikli işgücünün ülkeler veya eyaletler arasında serbestçe hareket edebildiği bir ortamda yönetimlerin yatırımcıyı çekmek için kurumlar ve sermaye vergisi oranlarını birbirinden aşağı çekmesine ne ad verilir?', 'Vergi rekabeti / dibe doğru yarış (tax competition / race to the bottom)', ['Vergi uyumlaştırması (tax harmonization)', 'Mali sürüklenme (fiscal drag)', 'Tam vergi ihracı (tax exporting)'], 'Bir bölgenin sermaye vergisini indirmesi komşu bölgelerden sermaye çekerek onlara negatif mali dışsallık yükler; misillemeler sonucunda tüm bölgelerde sermaye vergileri ve kamusal mal arzı optimalin altına inebilir.'),
  ('Turistik bir kıyı belediyesinin kendi belde sakinlerinin emlak vergisini düşük tutup bütçesini büyük ölçüde dışarıdan gelen turistlerin ödediği otel konaklama vergisiyle finanse etmesine mali yerelleşme literatüründe ne ad verilir?', 'Vergi ihracı (tax exporting)', ['Sinek kağıdı etkisi (flypaper effect)', 'Dikey mali dengesizlik', 'Pigoucu sübvansiyon içselleştirmesi'], 'Vergi ihracı, bir yerel yönetimin koyduğu verginin ekonomik yükünü kendi seçmenleri dışındaki yerleşik olmayan kişilere (turistlere, diğer bölge tüketicilerine) yansıtmasıdır; bu durum yerel kamu harcamalarında aşırı genişlemeye yol açabilir.'),
  ('Merkezi yönetimin yerel yönetimlere \'yalnızca ilkokul yapımında kullanılması ve belediyenin koyduğu her 1 TL\'ye merkezin de 1 TL eklemesi\' koşuluyla verdiği mali transfer türü hangisidir?', 'Koşullu eşleştirmeli (matching) hibe', ['Koşulsuz genel bütçe payı', 'Götürü baş vergisi iadesi', 'Karşılıklı hazine borç takası'], 'Eşleştirmeli (matching) koşullu hibeler yerel yönetim açısından desteklenen hizmetin nispi fiyatını düşürdüğü için (burada yarı yarıya ucuzlatır) hem gelir hem de ikame etkisi yaratarak hedef harcamayı blok hibeden daha güçlü uyarır.'),
  ('Bir ilin temizlediği nehrin akış yönündeki komşu illere de temiz su sağlaması gibi \'bölgeler arası pozitif yayılma etkisi\' (spillover) varlığında merkezi hükümetin yerel yönetime nasıl müdahale etmesi etkinliği sağlar?', 'Komşu illere taşan marjinal dışsal fayda oranında yerel yönetime eşleştirmeli (Pigoucu) koşullu hibe sağlaması', ['Nehri temizleyen belediyenin bütçesine ceza keserek su arıtma tesisini kapatmaya zorlaması', 'Komşu illerin nehir suyunu kullanmasını önlemek için il sınırında nehrin yatağını beton setle kurutması', 'Yerel arıtma hizmetinin maliyetinin tamamını nehirden bin kilometre uzaktaki kurak illere yüklemesi'], 'Yerel yönetim yalnızca kendi seçmenlerinin faydasını hesaba kattığından yayılma etkisini ihmal eder ve eksik arıtma yapar; merkezin dışsal fayda payı kadar eşleştirmeli hibe vermesi dışsallığı içselleştirir.'),
  ('Sağlık sigortasında hastanın tedavi masraflarının tamamı üçüncü taraf (devlet veya sigorta) tarafından karşılandığında bireyin marjinal maliyeti sıfır görerek gereksiz tetkik ve hastane başvurusu talep etmesi hangi kavramla açıklanır?', 'Ahlaki tehlike (moral hazard) kaynaklı aşırı tüketim', ['Ters seçim (adverse selection) kaynaklı havuz daralması', 'Bedavacılık kaynaklı eksik kamusal aşılama', 'Parasal dışsallık kaynaklı doktor göçü'], 'Tam sigorta kapsamı hizmetin kullanıcı açısından marjinal fiyatını sıfıra indirir; marjinal faydası gerçek üretim maliyetinden (MC) çok düşük olan sağlık hizmetlerinin de talep edilmesi dara kaybı (moral hazard) doğurur ve katkı payı (co-payment) bu nedenle uygulanır.'),
  ('Kamu borçlanmasında Robert Barro\'nun yeniden biçimlendirdiği \'Ricardo Denklik Teoremi\' (Ricardian Equivalence) neyi öne sürer?', 'Kamu harcamaları sabitken vergi indiriminin borçlanmayla finanse edilmesinin, rasyonel mükellefler gelecekteki vergi artışını öngörüp tasarruflarını artıracağı için toplam talebi değiştirmeyeceğini', ['Devletin iç borçlanma yerine dış borçlanmaya gitmesinin her zaman enflasyonu sıfıra indireceğini', 'Bütçe açıklarının özel yatırımları faiz artışı kanalıyla her koşulda bire bir dışlayacağını', 'Kamu borç stokunun milli gelire oranı %100\'ü aştığında tüketicilerin tüm tasarruflarını harcamaya dönüştüreceğini'], 'Kuşaklar arası fedakâr bağlar, tam sermaye piyasaları ve bozucu olmayan vergiler varsayımı altında bugünkü vergi indirimi net servet olarak görülmez; gelecekteki vergileri ödemek üzere tasarruf edilir.'),
  ('Karbon kaçağı (carbon leakage) sorunu uluslararası çevre ve vergi politikasında hangi riski ifade eder?', 'Yalnızca tek bir ülkenin sıkı karbon vergisi koyması halinde ağır sanayinin vergi olmayan ülkelere taşınarak küresel emisyonun düşmemesi', ['Karbon yakalama tesislerinde depolanan gazların yer altından sızarak içme sularını tatlandırması', 'Alınıp satılabilir emisyon sertifikalarının kağıt kalitesinin düşmesi nedeniyle borsada sahtesinin basılması', 'Gelişmiş ülkelerin topladıkları çevre vergilerini az gelişmiş ülkelere karşılıksız iklim hibesi olarak göndermesi'], 'Sera gazları küresel kamusal zarardır; tek taraflı sert karbon vergisi yerli üretimi rekabet dezavantajına sokup üretimi gevşek mevzuatlı ülkelere kaydırabilir (bu nedenle sınırda karbon düzenleme mekanizmaları tasarlanır).'),
  ('Trafik sıkışıklığı yaşayan bir kent merkezine günün zirve saatlerinde giriş yapan araçlardan \'tıkanıklık ücreti\' (congestion pricing — Londra veya Singapur örneği) alınmasının iktisadi mantığı nedir?', 'Yola giren son aracın kendi zaman kaybı dışında arkadaki tüm araçları yavaşlatarak yarattığı marjinal dışsal zaman maliyetini sürücüye içselleştirmek', ['Kent merkezindeki tüm ticari dükkanları kapatarak şehir içi ulaşım talebini kalıcı olarak sıfırlamak', 'Boş gece saatlerinde yoldan geçen araçlardan zirve saatlere göre on kat daha yüksek geçiş ücreti tahsil etmek', 'Trafik sıkışıklığının bir tam kamusal mal olması nedeniyle yola giren araç sayısını teşviklerle artırmak'], 'Sürücü yalnızca kendi ortalama seyahat süresini (APC) dikkate alır, oysa kalabalık yola katıldığında arkadaki yüzlerce aracı geciktirir (MSC > APC); Pigoucu tıkanıklık ücreti bu farka eşitlenir.'),
  ('Dört haneden oluşan bir ekonomide hanelerin yıllık gelirleri sırasıyla 10.000 TL, 20.000 TL, 30.000 TL ve 40.000 TL\'dir. Devlet en zengin haneden 6.000 TL vergi alıp en yoksul haneye 6.000 TL nakit transfer yaparsa Gini katsayısı hangi yönde ve nasıl etkilenir?', 'Sıralamayı bozmayan (16 bin, 20 bin, 30 bin, 34 bin TL) bu Pigou-Dalton transferi Lorenz eğrisini 45 derece doğrusuna yaklaştırır ve Gini katsayısını düşürür', ['Toplam milli gelir 100.000 TL\'de sabit kaldığı için Lorenz eğrisi ve Gini katsayısı hiçbir biçimde değişmez', 'Orta gelirli iki haneye hiç dokunulmadığı için Gini katsayısı düşmek yerine artış gösterir', 'En zengin hanenin geliri azaldığı için ekonomideki toplam eşitsizlik endeksi iki katına çıkar'], 'Transfer sonrası gelirler (16, 20, 30, 34 bin TL) olur: en alt %25\'in payı %10\'dan %16\'ya, en alt %50\'nin payı %30\'dan %36\'ya, en alt %75\'in payı %60\'tan %66\'ya çıkar; Lorenz eğrisi her noktada yukarı kayar ve Gini düşer.'),
  ('Kurumlar vergisi sisteminde bir anonim şirketin kârı önce kurum bünyesinde vergilendirildikten sonra kalan net kâr ortaklara temettü olarak dağıtıldığında ortakların kişisel gelir vergisine de tabi tutulmasına ne ad verilir?', 'Ekonomik anlamda çifte vergilendirme', ['Vergi mahsubu ve tam entegrasyon sistemi', 'Kaynakta nihai stopaj muafiyeti', 'Tersine vergi harcaması sübvansiyonu'], 'Aynı kâr akışının önce tüzel kişilikte (kurumlar vergisi) sonra gerçek kişi hissedarda (temettü gelir vergisi) iki kez vergilendirilmesi ekonomik çifte vergilendirmedir ve şirketleri özsermaye yerine borçla finansmana yöneltebilir.'),
  ('Negatif üretim dışsallığının bulunduğu ve devlet müdahalesinin olmadığı rekabetçi bir piyasada denge üretim miktarı ile sosyal açıdan optimal üretim miktarı arasındaki ilişki nasıldır?', 'Piyasa üretim miktarı sosyal optimal düzeyden fazladır', ['Piyasa üretim miktarı sosyal optimal düzeyden düşüktür', 'Piyasa üretim miktarı sosyal optimal düzeye tam eşittir', 'Piyasa üretimi sıfıra inerek tamamen durma noktasına gelir'], 'Üretici dışsal maliyeti dikkate almadığı için piyasada aşırı üretim gerçekleşir.'),
  ('Pozitif tüketim dışsallığı yaratan eğitim hizmetlerinin yalnızca serbest piyasa koşullarına bırakılması durumunda aşağıdakilerden hangisi gerçekleşir?', 'Sosyal açıdan arzu edilen düzeyin altında tüketim yapılır', ['Sosyal açıdan arzu edilen düzeyin üstünde aşırı tüketim olur', 'Marjinal özel fayda marjinal sosyal faydadan yüksek kalır', 'Toplumsal refah kaybı oluşmadan tam etkinlik kendiliğinden sağlanır'], 'Dışsal fayda bireysel talebe yansımadığı için piyasada eksik tüketim ortaya çıkar.'),
  ('Bir kağıt fabrikasının ton başına marjinal özel maliyeti 400 TL ve nehre bıraktığı atığın ton başına marjinal dışsal maliyeti 120 TL ise, bu üretimin ton başına marjinal sosyal maliyeti kaç TL olur?', '520 TL', ['280 TL', '400 TL', '480 TL'], 'Marjinal sosyal maliyet, marjinal özel maliyet ile marjinal dışsal maliyetin toplamıdır (400 + 120 = 520 TL).'),
  ('Bir malın tüketiminden sağlanan marjinal özel fayda 90 TL, topluma yaydığı marjinal dışsal fayda 35 TL ise sosyal optimumu sağlamak için devletin birim başına vermesi gereken Pigou sübvansiyonu kaç TL olmalıdır?', '35 TL', ['90 TL', '55 TL', '125 TL'], 'Optimal Pigou sübvansiyonu sosyal optimumdaki marjinal dışsal faydaya (35 TL) eşit olmalıdır.'),
  ('Negatif üretim dışsallığı bulunan bir endüstride marjinal sosyal maliyet eğrisinin marjinal özel maliyet eğrisine göre konumu aşağıdakilerden hangisinde doğru verilmiştir?', 'Marjinal özel maliyet eğrisinin üzerinde ve solunda yer alır', ['Marjinal özel maliyet eğrisinin altında ve sağında yer alır', 'Marjinal özel maliyet eğrisiyle her üretim düzeyinde çakışır', 'Yatay eksene paralel olarak marjinal özel maliyeti dik keser'], 'Dışsal maliyet eklendiği için her çıktıda sosyal maliyet özel maliyetten yüksektir; eğri yukarı/sola kayar.'),
  ('Üretim miktarı arttıkça birim başına çevreye verilen zararın da arttığı bir sektörde marjinal özel maliyet ile marjinal sosyal maliyet eğrileri nasıl bir seyir izler?', 'Üretim arttıkça iki eğri arasındaki dikey mesafe giderek açılır', ['Üretim arttıkça iki eğri birbirine yaklaşarak tek noktada birleşir', 'İki eğri arasındaki dikey uzaklık her üretim miktarında sabit kalır', 'Marjinal sosyal maliyet eğrisi üretim arttıkça aşağı doğru eğimlenir'], 'Birim başına dışsal zarar arttıkça iki maliyet eğrisi arasındaki dikey fark büyür.'),
  ('Pigou vergisinin temel iktisadi işlevi aşağıdakilerden hangisiyle en doğru biçimde açıklanır?', 'Dışsal maliyeti üreticinin özel maliyet hesabına dahil ederek içselleştirmek', ['Devletin genel bütçe açıklarını kapatmak için en esnek malları vergilendirmek', 'Pozitif dışsallık yayan yenilikçi firmaların araştırma maliyetlerini karşılamak', 'Gelir dağılımındaki eşitsizliği doğrudan artan oranlı tarife ile ortadan kaldırmak'], 'Pigou vergisi marjinal dışsal maliyeti fiyat mekanizmasına katarak dışsallığı içselleştirir.'),
  ('Coase teoremine göre mülkiyet hakkının kirleten fabrikaya mı yoksa zarar gören balıkçılara mı verildiğinin kaynak dağılımında etkinlik açısından sonucu nedir?', 'İşlem maliyeti yoksa her iki durumda da aynı etkin üretim düzeyine ulaşılır', ['Yalnızca balıkçılara mülkiyet hakkı verilirse etkin üretim düzeyi sağlanabilir', 'Yalnızca fabrikaya kirletme hakkı tanındığında toplumsal refah en yüksek olur', 'Mülkiyet hakkı kime verilirse üretim miktarı daima sıfır kirlilik noktasına iner'], 'İşlem maliyeti sıfırken mülkiyet hakkının dağılımı gelir bölüşümünü etkiler ama etkin çıktı düzeyini değiştirmez.'),
  ('Komuta-kontrol yaklaşımı (standart belirleme) yerine Pigou vergisi veya emisyon ticareti gibi piyasa temelli çevre politikalarının tercih edilmesinin temel iktisadi gerekçesi nedir?', 'Aynı toplam kirlilik azaltımını daha düşük toplam toplumsal maliyetle gerçekleştirmesi', ['Kirletici firmaların hiçbir teknolojik yenilik yapmadan mevcut üretimini sürdürmesi', 'Devletin kirlilik ölçümü ve denetimi yapma ihtiyacını bütünüyle ortadan kaldırması', 'Tüm fabrikaların marjinal azaltım maliyetleri farklı olsa bile eşit miktarda azaltım yapması'], 'Piyasa temelli araçlar azaltımı maliyeti en düşük olan firmalara yaptırarak maliyet etkinliği sağlar.'),
  ('Emisyon azaltım maliyeti düşük olan A firması ile azaltım maliyeti yüksek olan B firmasının yer aldığı bir emisyon ticareti piyasasında izin alışverişi nasıl gerçekleşir?', 'A firması daha fazla emisyon azaltıp artan izinlerini B firmasına satar', ['B firması daha fazla emisyon azaltıp artan izinlerini A firmasına satar', 'Her iki firma da izin ticareti yapmadan emisyonlarını eşit miktarda kısar', 'Azaltım maliyeti düşük olan A firması piyasadan ek kirletme izni satın alır'], 'Düşük maliyetli A firması ucuza azaltım yapıp izin satar, yüksek maliyetli B firması izin satın alır.'),
  ('Bir nehir kıyısında faaliyet gösteren boya atölyesi arıtma cihazı takarsa 50.000 TL maliyet katlanacaktır. Arıtma yapılmazsa aşağıdaki alabalık çiftliği 80.000 TL zarar görmektedir. Kirletme hakkı boya atölyesinde ve işlem maliyeti sıfırsa Coase teoremine göre hangi anlaşma yapılır?', 'Alabalık çiftliği atölyeye 50.000 TL ile 80.000 TL arasında ödeme yaparak arıtma taktırır', ['Boya atölyesi alabalık çiftliğine 80.000 TL tazminat ödeyerek nehri kirletmeye devam eder', 'Arıtma maliyeti zarardan düşük olduğu halde mülkiyet hakkı atölyede olduğundan arıtma takılmaz', 'Devlet boya atölyesini tamamen kapatmadıkça taraflar arasında hiçbir uzlaşma gerçekleşemez'], 'Çiftliğin zararı (80.000 TL) arıtma maliyetinden (50.000 TL) büyük olduğundan çiftlik ödeme yaparak arıtmayı sağlatır ve her iki taraf kazançlı çıkar.'),
  ('Aynı nehir örneğinde boya atölyesinin arıtma maliyeti 90.000 TL, alabalık çiftliğinin zararı 60.000 TL olsaydı ve temiz su hakkı balık çiftliğine verilseydi işlem maliyetsiz Coase pazarlığı nasıl sonuçlanırdı?', 'Boya atölyesi çiftliğe 60.000 TL ile 90.000 TL arası tazminat ödeyip arıtmasız üretime devam ederdi', ['Boya atölyesi 90.000 TL harcayarak arıtma cihazını kurmak zorunda kalır ve hiç ödeme yapmazdı', 'Alabalık çiftliği boya atölyesine 60.000 TL ödeyerek arıtma cihazı kurulmasını finanse ederdi', 'Her iki işletme de faaliyetini aynı anda sonlandırarak nehir kenarından tamamen taşınırdı'], 'Arıtma maliyeti (90.000 TL) zarardan (60.000 TL) yüksek olduğundan etkin çözüm tazminat ödeyerek üretimi sürdürmektir.'),
  ('Çevre vergilerinden elde edilen gelirlerin istihdam veya gelir üzerindeki bozucu vergileri indirmek amacıyla kullanılmasıyla hem çevresel iyileşme hem de ekonomik etkinlik kazancı sağlanmasına ne ad verilir?', 'Çifte kazanç (double dividend) hipotezi', ['Mali sürüklenme (fiscal drag) etkisi', 'Dışlama (crowding out) mekanizması', 'Ricardocu denklik varsayımı'], 'Çevre vergisi geliriyle bozucu vergilerin azaltılmasıyla elde edilen iki yönlü faydaya çifte kazanç hipotezi denir.'),
  ('Ortak bir merada her köylünün sürüye eklediği ilave koyunun meradaki ot miktarını azaltarak diğer köylülerin koyunlarının verimini düşürmesi hangi iktisadi mekanizmayla açıklanır?', 'Bireysel marjinal getirinin sosyal marjinal getiriden yüksek olması nedeniyle negatif dışsallık doğması', ['Meranın kullanımında tüketimde rekabet olmaması ve dışlama maliyetinin sıfır düzeyinde bulunması', 'Köylülerin marjinal özel maliyetlerinin marjinal sosyal maliyetten her zaman daha yüksek çıkması', 'Pozitif üretim dışsallığı sebebiyle merada sosyal optimumun çok altında hayvan otlatılması'], 'Her köylü kendi koyununun tam getirisini alırken aşırı otlatma maliyetini tüm köylülerle paylaşır; bu da negatif dışsallık ve aşırı kullanım yaratır.'),
  ('Sosyal açıdan optimal kirlilik düzeyinin genellikle sıfır kirlilik olmaması iktisadi açıdan nasıl gerekçelendirilir?', 'Sıfır kirliliğe yaklaştıkça marjinal arıtma maliyetinin marjinal çevresel faydadan çok daha yüksek olması', ['Devletin çevre vergilerinden sürekli gelir elde edebilmek için kirliliğin artmasını teşvik etmesi', 'Üretilen tüm tüketim mallarının marjinal sosyal faydasının her çıktı düzeyinde sıfıra eşit olması', 'Teknolojik gelişmenin emisyon azaltım maliyetlerini her zaman sonsuz düzeye çıkarması'], 'Optimal kirlilik, marjinal dışsal zararın marjinal azaltım maliyetine eşitlendiği noktadır; sıfır kirliliğin maliyeti toplumsal faydasını aşar.'),
  ('Ar-Ge faaliyetlerinin yarattığı pozitif dışsallıkları teşvik etmek için devletin uygulayabileceği politikalar arasında aşağıdakilerden hangisi yer almaz?', 'Buluş yapan firmalara ek karbon vergisi yüklemek', ['Yenilikçi projelere doğrudan araştırma sübvansiyonu vermek', 'Geçici süreli sınai mülkiyet ve patent koruması sağlamak', 'Araştırma harcamalarına kurumlar vergisi indirimi tanımak'], 'Ek karbon vergisi negatif çevre dışsallığına yöneliktir; pozitif Ar-Ge dışsallığını teşvik etmez.'),
  ('Bir malın üretiminde negatif dışsallık, tüketiminde ise hiçbir dışsallık bulunmuyorsa ve devlet optimal Pigou vergisini üreticiye uygularsa piyasa fiyatı ve miktarı nasıl değişir?', 'Denge fiyatı yükselir, denge üretim miktarı azalarak sosyal optimuma geriler', ['Denge fiyatı düşer, denge üretim miktarı artarak sosyal optimuma ulaşır', 'Denge fiyatı sabit kalır, yalnızca üreticinin kâr marjı artış gösterir', 'Denge fiyatı yükselir ve denge üretim miktarı da aynı oranda artış gösterir'], 'Optimal Pigou vergisi arz eğrisini yukarı kaydırarak fiyatı artırır ve aşırı üretimi sosyal optimuma düşürür.'),
  ('Üretim miktarı yerine doğrudan atmosfere salınan kirletici gaz birimi üzerinden alınan verginin çevre koruma açısından çıktı vergisine göre üstünlüğü nedir?', 'Firmaları hem çıktıyı ayarlamaya hem de daha temiz üretim teknolojisi kullanmaya teşvik etmesi', ['Ölçüm ve izleme maliyetlerinin her sektörde kesinlikle sıfır düzeyinde gerçekleşmesi', 'Tüketici fiyatlarını hiçbir koşulda etkilemeden yalnız devlet gelirini artırması', 'Firmaların filtre ve arıtma yatırımı yapma gereksinimini tamamen ortadan kaldırması'], 'Doğrudan emisyon vergisi firmayı arıtma teknolojisi kullanarak birim çıktı başına kirliliği düşürmeye yöneltir.'),
  ('Özel marjinal maliyeti 60 TL olan bir fidanlığın diktiği her ağaç çevrede erozyonu önleyerek topluma 25 TL dışsal fayda sağlıyorsa, fidanlığın sosyal marjinal maliyeti net olarak kaç TL\'dir?', '35 TL', ['85 TL', '60 TL', '25 TL'], 'Pozitif üretim dışsallığında sosyal marjinal maliyet, özel marjinal maliyetten dışsal faydanın çıkarılmasıyla bulunur (60 - 25 = 35 TL).'),
  ('Gürültülü çalışan bir eğlence mekanının üst katında oturan apartman sakinlerinin uykusuz kalması durumunda, yasal mevzuat sessizlik hakkını apartman sakinlerine tanımışsa Coase çerçevesinde ne beklenir?', 'Eğlence mekanı ses yalıtımı yapar veya sakinlerin rızasını alacak miktarda tazminat öder', ['Apartman sakinleri eğlence mekanına ses yalıtımı yapması için zorunlu ödeme yapar', 'Mülkiyet hakkı sakinlerde olduğu için hiçbir koşulda pazarlık yapılmasına izin verilmez', 'Eğlence mekanı hiçbir maliyete katlanmadan dilediği ses düzeyinde çalışmayı sürdürür'], 'Sessizlik hakkı sakinlerde olduğundan mekan ya daha ucuzsa yalıtım yapar ya da sakinlerin kabul edeceği tazminatı öder.'),
  ('Emisyon ticareti sisteminde başlangıçtaki kirletme izinlerinin firmalara ücretsiz dağıtılması (grandfathering) ile açık artırmayla satılması arasındaki temel fark nedir?', 'Toplam emisyon azaltım etkinliği değişmez ancak gelir dağılımı ve kamu geliri değişir', ['Ücretsiz dağıtımda emisyon ticareti tamamen durur ve kirlilik azaltımı gerçekleşmez', 'Açık artırma yönteminde düşük maliyetli firmalar arıtma yapmaktan bütünüyle vazgeçer', 'Ücretsiz dağıtım yapıldığında izinlerin ikinci el piyasa fiyatı her zaman sıfır olur'], 'Coase mantığıyla işlem maliyeti düşükse başlangıç tahsisi etkinliği bozmaz, yalnızca rantın kimde kalacağını belirler.'),
  ('Bir güneş paneli kurulumunun ev sahibine sağladığı marjinal özel fayda P = 150 - Q ve şebekeye sağladığı marjinal dışsal fayda sabit 30 birimdir. Marjinal maliyet MC = 90 ise serbest piyasa ile sosyal optimum arasındaki miktar farkı kaçtır?', '30 birim', ['60 birim', '90 birim', '15 birim'], 'Serbest piyasada 150 - Qp = 90 -> Qp = 60. Sosyal optimumda 180 - Q* = 90 -> Q* = 90. Fark = 90 - 60 = 30 birim.'),
  ('Parasal dışsallıklar ile teknolojik (gerçek) dışsallıklar arasındaki en kritik iktisadi fark aşağıdakilerden hangisidir?', 'Parasal dışsallıklar fiyat sistemi içinde gerçekleştiğinden Pareto etkinliğini bozmaz', ['Parasal dışsallıklar her zaman devletin Pigou vergisi uygulamasını zorunlu kılar', 'Teknolojik dışsallıklar yalnızca tam rekabetçi piyasalarda gelir transferi yaratır', 'Parasal dışsallıklarda marjinal sosyal maliyet marjinal özel maliyetten sürekli büyüktür'], 'Parasal dışsallıklar arz-talep değişimlerinin fiyatlara yansımasıdır ve piyasa başarısızlığı oluşturmaz.'),
  ('Bir belediye toplu taşıma biletlerine yolcu başına 12 TL sübvansiyon vererek özel araç kaynaklı trafik dışsallığını azaltmayı hedefliyor. Günde 50.000 yolcu taşınıyorsa belediyenin günlük sübvansiyon bütçesi ne kadardır?', '600.000 TL', ['500.000 TL', '720.000 TL', '480.000 TL'], 'Günlük toplam sübvansiyon tutarı = 50.000 yolcu * 12 TL = 600.000 TL\'dir.'),
  ('Karbon kaçağı (carbon leakage) kavramı uluslararası çevre ekonomisinde hangi durumu ifade eder?', 'Sıkı karbon vergisi uygulayan ülkelerdeki kirletici üretimin çevre kuralları gevşek ülkelere kayması', ['Emisyon ticareti piyasasında dağıtılan izin belgelerinin sahte yollarla çoğaltılması', 'Fabrika bacalarına takılan filtrelerin zamanla aşınarak doğaya daha az gaz salması', 'Devletin topladığı karbon vergisi gelirlerinin hazine hesaplarında değer kaybetmesi'], 'Ulusal karbon maliyetinden kaçan üretimin denetimsiz ülkelere taşınması küresel emisyonu düşürmeyebilir; buna karbon kaçağı denir.'),
  ('Antibiyotiklerin gereksiz ve aşırı kullanımı sonucunda dirençli bakterilerin gelişerek toplumdaki diğer hastaların tedavisini zorlaştırması nasıl bir iktisadi sorundur?', 'Bireysel tüketimin toplumsal ilaç etkinliği havuzunu tükettiği negatif tüketim dışsallığı', ['İlaç firmalarının üretim maliyetlerini düşüren pozitif ölçek ekonomisi etkisi', 'Hastaların sağlık hizmetlerinden dışlanmasını engelleyen pozitif ağ dışsallığı', 'Tam rekabetçi ilaç piyasasında arz fazlasından kaynaklanan fiyat katılığı sorunu'], 'Aşırı antibiyotik kullanımı gelecekteki ve diğer hastalar için direnç maliyeti yaratan negatif dışsallıktır.'),
  ('Bir enerji santralinin megavatsaat başına üretim maliyeti 800 TL, satış fiyatı 950 TL ve hava kirliliği nedeniyle yarattığı sağlık maliyeti 200 TL ise üretilen bu son birimin net toplumsal etkisi nedir?', '50 TL net toplumsal refah kaybı yaratır', ['150 TL net toplumsal refah artışı sağlar', '200 TL net toplumsal refah kazancı doğurur', 'Toplumsal refah üzerinde sıfır net etki bırakır'], 'Marjinal sosyal fayda (fiyat) 950 TL, marjinal sosyal maliyet 800 + 200 = 1000 TL\'dir; son birim 50 TL net zarar üretir.'),
  ('Bir sanayi bölgesinde tüm fabrikalara mevcut kirliliklerini yüzde 30 oranında azaltma zorunluluğu getiren tek tip yasal standart neden iktisadi açıdan etkinsizdir?', 'Farklı fabrikaların marjinal azaltım maliyetlerini eşitlemediği için toplam azaltım maliyetini yükseltir', ['Fabrikaların üretim miktarını artırmasını zorunlu kılarak hammadde israfına neden olur', 'Yüzde 30 azaltım oranı her zaman marjinal sosyal faydayı negatif bölgeye düşürür', 'Devletin vergi gelirlerini aşırı artırarak özel sektör yatırımlarını tamamen dışlar'], 'Maliyet etkinliği için marjinal azaltım maliyetlerinin eşitlenmesi gerekir; tek tip oran düşük ve yüksek maliyetli firmaları aynı kefeye koyar.'),
  ('Bir yazılım şirketinin açık kaynaklı bir kod kütüphanesi geliştirip herkesin kullanımına açması sonucunda diğer girişimlerin yazılım geliştirme maliyetlerinin düşmesi neyi gösterir?', 'Bilgi yayılımı kaynaklı pozitif üretim dışsallığını', ['Aşırı kullanıma bağlı ortak kaynak tükenmesini', 'Girdi piyasasında oluşan negatif teknik dışsallığı', 'Tekelci fiyat farklılaştırmasının refah etkisini'], 'Bilginin bedelsiz yayılıp diğer üreticilerin maliyetini düşürmesi pozitif üretim dışsallığıdır.'),
  ('Coase teoreminde gelir etkisinin bulunmadığı (tercihlerin yarı-doğrusal olduğu) varsayımı kaldırılırsa pazarlık sonucuyla ilgili hangi değişiklik ortaya çıkabilir?', 'Mülkiyet hakkının kime verildiği tarafların ödeme gücünü değiştirerek etkin çıktı düzeyini etkileyebilir', ['İşlem maliyetleri sıfır olsa bile taraflar hiçbir koşulda masaya oturup anlaşma yapamaz', 'Devletin uygulayacağı Pigou vergisi kirliliği azaltmak yerine her zaman iki katına çıkarır', 'Negatif dışsallık kendiliğinden pozitif dışsallığa dönüşerek toplumsal fayda yaratır'], 'Güçlü gelir etkisi varsa başlangıçtaki mülkiyet hakkı zenginliği ve dolayısıyla marjinal ödeme isteğini değiştirerek etkin denge noktasını kaydırabilir.'),
  ('Bir çiftçinin kullandığı böcek ilacının kutu başına fiyatı 100 TL\'dir. İlaç yeraltı suyuna karışarak kutu başına 40 TL arıtma maliyeti doğurmaktadır. Çiftçinin marjinal ürün geliri kutu başına MRP = 220 - 20X ise sosyal açıdan optimal ilaç kullanımı kaç kutudur?', '4 kutu', ['6 kutu', '5 kutu', '3 kutu'], 'Sosyal marjinal maliyet = 100 + 40 = 140 TL. Sosyal optimumda MRP = MSC -> 220 - 20X = 140 -> 20X = 80 -> X = 4 kutu.'),
  ('Tarihi bir binanın sahibi tarafından restore edilmesiyle mahalledeki turistik hareketliliğin ve komşu dükkanların cirolarının artması hangi durumu örneklendirir?', 'Mülk sahibinin tüm sosyal faydayı yakalayamadığı pozitif dışsallık', ['Komşu esnafın satışlarını düşüren negatif tüketim dışsallığı', 'Tam rekabet piyasasında ölçeğe göre azalan getiri durumu', 'Kamusal mallarda tüketimde tam rekabet ve dışlanabilirlik'], 'Restorasyon komşu esnafa bedelsiz gelir artışı sağladığı için pozitif dışsallık üretir.'),
  ('Aşı, temel eğitim ve toplu taşıma gibi alanlarda pozitif dışsallık bulunmasına rağmen devletin bazen sübvansiyon yanında yasal zorunluluk da getirmesinin nedeni nedir?', 'Bireylerin bilgi eksikliği veya miyopik tercihleri yüzünden sübvansiyona rağmen optimal tüketime ulaşamaması', ['Sübvansiyon uygulandığında talep eğrisinin her zaman sola kayarak tüketimi sıfırlaması', 'Pozitif dışsallık yayan hizmetlerin marjinal sosyal faydasının negatif değer alması', 'Zorunlu tüketimin kamu bütçesi üzerinde hiçbir idari veya mali yük oluşturmaması'], 'Eksik bilgi ve davranışsal engeller nedeniyle yalnız fiyat teşviki toplumsal bağışıklık veya okullaşma eşiğine yetmeyebilir.'),
  ('"Kirleten öder" ilkesinin iktisadi temeli aşağıdakilerden hangisine dayanır?', 'Çevresel zararın maliyetini kirletici birime yükleyerek kaynak dağılımında etkinliği sağlamaya', ['Çevre kirliliğinden zarar gören mağdurların arıtma tesislerini kendi bütçeleriyle kurmasına', 'Tüm çevre koruma harcamalarının yalnızca düşük gelirli tüketicilerden alınan vergilerle karşılanmasına', 'Kirletici sanayi kuruluşlarının üretim miktarını artırdıkça daha az vergi ödemesine'], 'Kirleten öder ilkesi, çevresel dışsal maliyetin kaynağında içselleştirilmesini öngörür.'),
  ('Bir tekstil fabrikası atık suyunu arıtmadan dereye verdiğinde aşağı havzadaki sebze üreticilerinin yıllık kârı 120.000 TL azalmaktadır. Fabrikanın yıllık kârı 300.000 TL, arıtma sisteminin yıllık maliyeti ise 75.000 TL\'dir. Toplumsal net refahı en yüksek yapan çözüm hangisidir?', 'Fabrikanın 75.000 TL maliyetle arıtma kurarak üretime devam etmesi', ['Fabrikanın tamamen kapatılarak 300.000 TL üretim kârından vazgeçilmesi', 'Arıtma kurulmayarak sebze üreticilerinin 120.000 TL zarar etmesine göz yumulması', 'Sebze üreticilerinin tarımı bırakıp fabrikanın arıtmasız çalışmayı sürdürmesi'], 'Arıtma maliyeti (75.000 TL) hem fabrika kârından (300.000 TL) hem de sebze üreticisinin zararından (120.000 TL) düşük olduğundan arıtma kurmak toplumsal refahı maksimize eder.'),
  ('Üreticinin ödediği bir satış vergisini malın satış fiyatını yükselterek tüketicilere aktarmasına maliye literatüründe ne ad verilir?', 'İleriye doğru vergi yansıması', ['Geriye doğru vergi yansıması', 'Verginin sermayeleşmesi', 'Vergiden kaçınma davranışı'], 'Verginin fiyat artışıyla alıcıya (tüketiciye) devredilmesi ileriye doğru yansımadır.'),
  ('Bir mal üzerine konulan vergiyi üreticinin tüketici fiyatına yansıtamayıp hammadde tedarikçilerinin veya işçilerin ücret ve girdi fiyatlarını düşürerek aktarmasına ne denir?', 'Geriye doğru vergi yansıması', ['İleriye doğru vergi yansıması', 'Sınırsız çapraz vergi yansıması', 'Kanuni vergi ikamesi süreci'], 'Vergi yükünün girdi fiyatlarını veya ücretleri düşürerek üretim faktörlerine aktarılması geriye doğru yansımadır.'),
  ('Rekabetçi bir mal piyasasında birim başına konulan spesifik bir verginin ekonomik yükünün kimde daha fazla kalacağını belirleyen temel unsur nedir?', 'Arz ve talebin göreli fiyat esneklikleri', ['Verginin kanunen alıcıdan mı satıcıdan mı tahsil edildiği', 'Üretici sayısının tek mi yoksa çift sayı mı olduğu', 'Devletin bütçe fazlası veya bütçe açığı veriyor olması'], 'Vergi yükü her zaman fiyat esnekliği daha düşük (daha inelastik) olan piyasa tarafında daha fazla kalır.'),
  ('Talebin fiyat esnekliğinin sıfır (tam inelastik), arz eğrisinin ise pozitif eğimli olduğu bir ilaç piyasasında birim başına konulan verginin ekonomik yükü nasıl dağılır?', 'Vergi yükünün tamamı tüketicilerin üzerinde kalır', ['Vergi yükünün tamamı ilaç üreticilerinin üzerinde kalır', 'Vergi yükü üretici ve tüketici arasında yarı yarıya paylaşılır', 'Vergi konulduğunda ilaç satışı anında sıfıra düşer'], 'Talep tam inelastik olduğunda tüketici miktardan vazgeçemez; fiyat tam vergi tutarı kadar artar ve tüm yük tüketiciye biner.'),
  ('Arzın tam esnek (yatay eksene paralel), talebin ise negatif eğimli olduğu uzun dönem rekabetçi bir endüstride konulan birim verginin fiyat üzerindeki etkisi nedir?', 'Tüketici fiyatı tam vergi tutarı kadar yükselir ve tüm yük tüketiciye yansır', ['Tüketici fiyatı hiç değişmez ve verginin tamamını üretici üstlenir', 'Tüketici fiyatı verginin yarısı kadar artar, kalan yarısını üretici öder', 'Tüketici fiyatı vergi tutarından daha az artar ancak üretim miktarı büyür'], 'Tam esnek arzda üreticinin kabul ettiği net fiyat değişmez; vergi tamamen tüketici fiyatına eklenir.'),
  ('Doğrusal talep fonksiyonu Qd = 120 - 2P ve arz fonksiyonu Qs = 30 + P olan bir piyasada birim başına 9 TL vergi konulursa tüketicinin ödeyeceği yeni fiyat kaç TL olur?', '33 TL', ['39 TL', '30 TL', '36 TL'], 'Vergisiz denge: 120 - 2P = 30 + P -> 3P = 90 -> P = 30 TL. Vergili arz Qs = 30 + (Pt - 9) = 21 + Pt -> 120 - 2Pt = 21 + Pt -> 3Pt = 99 -> Pt = 33 TL.'),
  ('Aynı piyasada (Qd = 120 - 2P, Qs = 30 + P ve birim vergi t = 9 TL) 9 TL\'lik birim verginin kaç TL\'si tüketiciye, kaç TL\'si üreticiye yansımıştır?', 'Tüketiciye 3 TL, üreticiye 6 TL yansımıştır', ['Tüketiciye 6 TL, üreticiye 3 TL yansımıştır', 'Tüketiciye 4,5 TL, üreticiye 4,5 TL yansımıştır', 'Tüketiciye 9 TL, üreticiye 0 TL yansımıştır'], 'Vergisiz fiyat 30 TL iken vergili alıcı fiyatı 33 TL (3 TL artış), satıcının eline geçen net fiyat 24 TL (6 TL düşüş) olmuştur.'),
  ('Dilimli artan oranlı gelir vergisi tarifesinde ilk 100.000 TL için oran %15, 100.000 TL\'yi aşan kısım için oran %25\'tir. Yıllık vergiye tabi geliri 180.000 TL olan bir mükellefin ödeyeceği toplam vergi ve ortalama vergi oranı nedir?', 'Toplam vergi 35.000 TL, ortalama oran yaklaşık %19,44', ['Toplam vergi 45.000 TL, ortalama oran tam %25,00', 'Toplam vergi 27.000 TL, ortalama oran tam %15,00', 'Toplam vergi 38.000 TL, ortalama oran yaklaşık %21,11'], 'Vergi = (100.000 * 0,15) + (80.000 * 0,25) = 15.000 + 20.000 = 35.000 TL. Ortalama oran = 35.000 / 180.000 = %19,44.'),
  ('Dilimli artan oranlı bir gelir vergisi sisteminde mükellefin gelir düzeyi üst vergi dilimlerine geçtikçe marjinal vergi oranı ile ortalama vergi oranı arasındaki ilişki nasıldır?', 'Marjinal vergi oranı, ilk dilim aşıldıktan sonra daima ortalama vergi oranından yüksektir', ['Ortalama vergi oranı her gelir diliminde marjinal vergi oranından daha yüksek seyreder', 'Marjinal vergi oranı ile ortalama vergi oranı tüm gelir düzeylerinde birbirine eşittir', 'Gelir arttıkça marjinal vergi oranı yükselirken ortalama vergi oranı sürekli düşer'], 'Artan oranlı dilimli tarifede ek gelire uygulanan marjinal oran ortalamayı yukarı çeker ve ortalamanın üzerinde kalır.'),
  ('Yüksek enflasyon dönemlerinde bireylerin reel satın alma gücü artmadığı halde nominal gelirlerinin yükselmesi sonucu daha üst gelir vergisi dilimlerine girerek reel vergi yüklerinin artmasına ne ad verilir?', 'Mali sürüklenme', ['Olivera-Tanzi etkisi', 'Verginin sermayeleşmesi', 'Laffer gelir sıçraması'], 'Nominal gelir artışıyla üst vergi dilimine kayıp reel vergi oranının yükselmesine mali sürüklenme (bracket creep) denir.'),
  ('Laffer eğrisine göre vergi oranının yüzde sıfır (%0) ve yüzde yüz (%100) olduğu iki uç noktada devletin toplayacağı vergi hasılatı için ne söylenebilir?', 'Her iki uç noktada da vergi hasılatı sıfır olur', ['Yüzde sıfırda sıfır, yüzde yüzde maksimum hasılat toplanır', 'Her iki uç noktada da vergi hasılatı maksimum düzeye ulaşır', 'Yüzde sıfırda maksimum, yüzde yüzde minimum pozitif hasılat doğar'], '%0 oranda vergi alınmaz; %100 oranda ise yasal ekonomik çalışma ve üretim güdüsü tamamen yok olacağından matrah ve hasılat sıfırlanır.'),
  ('Bir ekonomide mevcut vergi oranı Laffer eğrisinin tepe noktasının sağında (yasak/etkinsiz bölgede) yer alıyorsa vergi oranında yapılacak ölçülü bir indirim hangi sonucu doğurur?', 'Ekonomik faaliyeti ve vergi matrahını genişleterek toplam vergi gelirini artırır', ['Vergi matrahını daraltarak devletin toplam vergi gelirini hızla sıfıra düşürür', 'Kayıt dışı ekonomiyi büyütürken resmi vergi gelirini aynı oranda azaltır', 'Lorenz eğrisini mutlak eşitsizlik noktasına taşıyarak üretimi durdurur'], 'Tepe noktasının sağında yüksek vergi matrahı boğmuştur; oran düşürülünce arz yönlü genişleme ve kayıt dışından dönüş hasılatı artırır.'),
  ('Arz yönlü iktisatçıların Laffer eğrisine dayanarak yüksek marjinal gelir vergisi oranlarının düşürülmesini savunmalarının temel mikroiktisadi dayanağı nedir?', 'Çalışma-boş zaman ve tasarruf-tüketim tercihlerinde ikame etkisinin güçlü çalışarak emek arzı ve yatırımı artırması', ['Vergi indirimlerinin toplam talebi daraltarak enflasyonu ve üretimi aynı anda düşürmesi', 'Düşük vergi oranlarının bireyleri kayıtlı sektörden kayıt dışı sektöre geçmeye zorlaması', 'Devlet harcamalarının çarpan etkisinin her zaman vergi çarpanından daha küçük olması'], 'Yüksek marjinal vergi çalışmanın ve yatırımın net getirisini düşürür; oran inince ikame etkisiyle emek arzı ve sermaye birikimi artar.'),
  ('Lorenz eğrisi grafiğinde mutlak eşitlik doğrusu ile Lorenz eğrisi arasında kalan alan A = 0,18 ve Lorenz eğrisinin altında kalan alan B = 0,32 birimkare ise Gini katsayısı kaçtır?', '0,36', ['0,18', '0,56', '0,64'], 'Mutlak eşitlik doğrusunun altındaki toplam üçgen alan A + B = 0,18 + 0,32 = 0,50\'dir. Gini = A / (A + B) = 0,18 / 0,50 = 0,36.'),
  ('Bir ekonomide Gini katsayısı 0,44 olarak ölçülmüştür. Mutlak eşitlik doğrusunun altındaki toplam alan 0,5 birimkare olduğuna göre Lorenz eğrisinin altında kalan alan (B alanı) kaç birimkaredir?', '0,28 birimkare', ['0,22 birimkare', '0,44 birimkare', '0,16 birimkare'], 'Gini = A / 0,5 = 0,44 -> A = 0,22 birimkare. B = 0,50 - 0,22 = 0,28 birimkaredir.'),
  ('Devletin artan oranlı gelir vergisi toplayıp elde ettiği geliri düşük gelirli hane halklarına nakdi sosyal yardım olarak aktarması Lorenz eğrisini ve Gini katsayısını nasıl etkiler?', 'Lorenz eğrisini mutlak eşitlik doğrusuna yaklaştırır ve Gini katsayısını düşürür', ['Lorenz eğrisini mutlak eşitlik doğrusundan uzaklaştırır ve Gini katsayısını yükseltir', 'Lorenz eğrisinin eğimini dikleştirerek Gini katsayısını tam 1 değerine ulaştırır', 'Lorenz eğrisinin konumunu hiç etkilemez, yalnız Laffer eğrisini sağa kaydırır'], 'Yeniden dağıtıcı vergi ve transfer politikası harcanabilir gelir dağılımını iyileştirir, Lorenz eğrisini içe çeker ve Gini\'yi düşürür.'),
  ('Yüksek enflasyon yaşanan bir ekonomide devletin yasal değişiklik yapmaması halinde spesifik vergiler ile ad valorem vergilerin reel hasılatı nasıl farklılaşır?', 'Spesifik vergilerin reel hasılatı erirken ad valorem vergiler fiyat artışına paralel nominal artış göstererek reel değerini korur', ['Spesifik vergilerin reel hasılatı hızla artarken ad valorem vergilerin nominal hasılatı sıfıra düşer', 'Her iki vergi türünün de reel hasılatı enflasyon oranı kadar otomatik olarak artış gösterir', 'Ad valorem vergiler miktar üzerinden alındığı için fiyat artışlarından hiçbir şekilde etkilenmez'], 'Spesifik vergi birim başına sabit TL olduğundan enflasyonda reel olarak aşınır; ad valorem vergi ise yükselen fiyat üzerinden yüzdeyle alınır.'),
  ('Getirisi olan bir gayrimenkul veya menkul kıymet üzerine sürekli bir vergi konulduğunda, bu varlığın piyasa satış fiyatının gelecekteki vergilerin bugünkü değeri kadar düşmesine ne ad verilir?', 'Verginin sermayeleşmesi', ['İleriye doğru tam vergi yansıması', 'Mali sürüklenme kaynaklı matrah artışı', 'Verginin gelir etkisiyle telafisi'], 'Sürekli verginin varlığın gelecekteki net getirisini düşürerek satış fiyatını indirmesine verginin sermayeleşmesi denir.'),
  ('Bir verginin kanuni mükellefinin, vergi sonrası azalan net gelirini telafi etmek amacıyla daha çok çalışarak veya üretim maliyetlerini düşürücü yenilikler yaparak vergi yükünü gidermesine ne denir?', 'Verginin giderilmesi', ['Kanun dışı vergi kaçakçılığı', 'Geriye doğru fiyat yansıması', 'Vergi muafiyeti ve istisnası'], 'Mükellefin verimlilik ve çalışma artışıyla vergi kaybını kendi içinde kapatmasına verginin giderilmesi (transformation) denir.'),
  ('Ramsey optimal emtia vergilendirmesi kuralına göre, devlet belirli bir vergi gelirini toplarken toplumsal refah kaybını (aşırı vergi yükünü) en aza indirmek için tüketim mallarını nasıl vergilendirmelidir?', 'Talebin fiyat esnekliği düşük olan mallara daha yüksek, esnekliği yüksek olan mallara daha düşük vergi oranı uygulamalıdır', ['Tüm lüks mallara sıfır vergi uygulayıp yalnız talebi sonsuz esnek olan malları yüksek oranda vergilendirmelidir', 'Fiyat esnekliğine bakmaksızın yalnız ithal edilen ara malları üzerinden tek tip spesifik vergi almalıdır', 'Arz ve talep esnekliği en yüksek olan mallara en yüksek vergi oranını koyarak tüketimi tamamen durdurmalıdır'], 'Dara kaybı esneklikle doğru orantılı olduğundan Ramsey kuralı esnekliği düşük malların daha yüksek oranda vergilendirilmesini öngörür.'),
  ('Vergilemede "yatay adalet" ve "dikey adalet" ilkeleri aşağıdakilerden hangisinde bir arada doğru tanımlanmıştır?', 'Yatay adalet aynı ekonomik güçtekilerin eşit, dikey adalet farklı ekonomik güçtekilerin farklı vergilendirilmesidir', ['Yatay adalet dolaylı vergilerin, dikey adalet ise yalnız gümrük vergilerinin uygulanmasıdır', 'Yatay adalet herkesin eşit tutarda baş vergisi ödemesi, dikey adalet zenginlerin vergiden muaf tutulmasıdır', 'Yatay adalet bölgeler arası eşitliği, dikey adalet ise kuşaklar arası borç transferini ifade eder'], 'Ödeme gücü yaklaşımında eşit durumda olanlara eşit (yatay), farklı durumda olanlara ödeme gücüne göre farklı (dikey) muamele yapılır.'),
  ('Kamu hizmetlerinin finansmanında "faydalanma ilkesi" ile "ödeme gücü ilkesi" karşılaştırıldığında aşağıdakilerden hangisi faydalanma ilkesine en uygun örnektir?', 'Otoyol ve köprüleri kullanan sürücülerden geçiş ücreti veya akaryakıt vergisi alınması', ['Yüksek gelir elde eden serbest meslek sahiplerinden artan oranlı gelir vergisi alınması', 'İşsiz ve yoksul vatandaşlara genel bütçeden karşılıksız sosyal yardım bağlanması', 'Miras yoluyla intikal eden büyük servetlerden veraset ve intikal vergisi tahsil edilmesi'], 'Faydalanma ilkesinde kamu hizmetinden yararlanan kişi, yararlandığı ölçüde bedel veya vergi öder.'),
  ('İktisadi etkinlik açısından sıfır dara kaybı yaratmasına rağmen götürü (baş) vergisinin modern maliye sistemlerinde temel gelir kaynağı olarak kullanılmamasının ana nedeni nedir?', 'Ödeme gücünü hiç dikkate almayıp yoksullarda çok ağır azalan oranlı yük yaratarak adaleti bozması', ['İdari tahsilat ve hesaplama formüllerinin dilimli gelir vergisinden çok daha karmaşık olması', 'Yüksek gelirli mükelleflerin çalışma şevkini kırarak Laffer eğrisini aşındırması', 'Enflasyonist dönemlerde para arzını otomatik olarak artırıp hiperenflasyona yol açması'], 'Herkesten aynı sabit tutarı almak yoksulun gelirinin büyük kısmını götürürken zengini etkilemez; bu durum sosyal adaletle bağdaşmaz.'),
  ('Bir ülkede vergi gelirlerinin %72\'si KDV ve ÖTV gibi harcama vergilerinden, %28\'i ise gelir ve kurumlar vergisinden oluşuyorsa bu vergi sisteminin gelir dağılımı üzerindeki muhtemel etkisi nedir?', 'Dolaylı vergi ağırlığı yüksek olduğu için gelir dağılımını düzeltici etkisi zayıf veya bozucu yöndedir', ['Dolaysız vergi ağırlığı baskın olduğu için Gini katsayısını hızla sıfıra yaklaştırır', 'Yalnızca servet sahiplerini vergilendirdiği için dikey adaleti en üst düzeyde sağlar', 'Tüketim eğilimi yüksek olan düşük gelirli grupların vergi yükünü tamamen sıfırlar'], 'Dolaylı vergiler kişisel ödeme gücünü ve ailevi durumu gözetmediğinden yüksek dolaylı vergi payı gelir adaletini zayıflatır.'),
  ('Aylık geliri 20.000 TL olan Ali gelirinin tamamını harcarken, aylık geliri 100.000 TL olan Veli gelirinin 50.000 TL\'sini harcayıp kalanını tasarruf etmektedir. Tüm harcamalardan %20 KDV alınıyorsa Ali ve Veli\'nin ödediği KDV\'nin kendi gelirlerine oranı sırasıyla yüzde kaçtır?', 'Ali için %20, Veli için %10 (azalan oranlı etki)', ['Ali için %10, Veli için %20 (artan oranlı etki)', 'Ali için %20, Veli için %20 (düz oranlı etki)', 'Ali için %15, Veli için %25 (artan oranlı etki)'], 'Ali 20.000 * 0,20 = 4.000 TL (%20); Veli 50.000 * 0,20 = 10.000 TL (10.000 / 100.000 = %10) vergi öder; gelire göre oran azalmıştır.'),
  ('Düz oranlı bir gelir vergisinde 50.000 TL tutarında vergiden muaf tutulan temel geçim istisnası vardır ve aşan kısma %20 sabit vergi uygulanmaktadır. Geliri 100.000 TL olan A kişisi ile 250.000 TL olan B kişisinin ortalama vergi oranları sırasıyla yüzde kaçtır?', 'A için %10, B için %16', ['A için %20, B için %20', 'A için %16, B için %10', 'A için %15, B için %20'], 'A\'nın vergisi = (100.000 - 50.000)*0,20 = 10.000 TL -> ortalama %10. B\'nin vergisi = (250.000 - 50.000)*0,20 = 40.000 TL -> 40.000/250.000 = %16.'),
  ('Vergi yansımasında piyasa yapısının rolü düşünüldüğünde, doğrusal talep eğrisi ve sabit marjinal maliyet altında faaliyet gösteren kâr maksimizasyoncu bir tekelci birim başına t TL vergi konulduğunda fiyatı ne kadar artırır?', 'Vergi tutarının yarısı (0,5t) kadar artırır', ['Vergi tutarının tamamı (t) kadar artırır', 'Vergi tutarının iki katı (2t) kadar artırır', 'Fiyatı hiç değiştirmeden sabit tutar'], 'Doğrusal ters talep P = a - bQ ve MR = a - 2bQ iken MC\'nin t kadar artması miktarı t/(2b) azaltır ve fiyatı 0,5t artırır.'),
  ('Bir ülkede nüfusun %20\'lik dilimlerinin (en yoksuldan en zengine doğru beş dilim) milli gelirden aldığı paylar sırasıyla %5, %10, %15, %25 ve %45\'tir. En zengin %20\'lik dilimin gelirinin en yoksul %20\'lik dilimin gelirine oranı (P80/P20 pay oranı) kaçtır?', '9 kat', ['5 kat', '4,5 kat', '8 kat'], 'En üst %20\'lik dilim (%45) / en alt %20\'lik dilim (%5) = 45 / 5 = 9 kat.'),
  ('Bir ülkede vergi ve sosyal transferler öncesi piyasa geliri Gini katsayısı 0,48 iken, vergi ve transferler sonrası harcanabilir gelir Gini katsayısı 0,31\'e düşüyorsa bu durum neyi kanıtlar?', 'Maliye politikasının (vergi ve transfer sisteminin) gelir eşitsizliğini önemli ölçüde azaltıcı yönde çalıştığını', ['Ülkede yalnızca azalan oranlı dolaylı vergilerin uygulandığını ve sosyal yardımların bulunmadığını', 'Ekonominin Laffer eğrisinin yasak bölgesinde bulunarak vergi gelirlerinin sıfırlandığını', 'Kayıt dışı ekonominin büyüyerek üst gelir gruplarının hiç vergi ödemediğini'], 'Piyasa Gini\'si ile harcanabilir gelir Gini\'si arasındaki 0,17 puanlık düşüş, mali sistemin güçlü yeniden dağıtım başarısını gösterir.'),
  ('Kurumlar vergisinin sermaye şirketlerinin net kazancı üzerinden sabit bir oranda alınmasına rağmen kar payı (temettü) dağıtıldığında ortakların gelir vergisine de tabi tutulması hangi mali tartışmayı doğurur?', 'Ekonomik çifte vergilendirme sorunu', ['Negatif dışsallığın eksik içselleştirilmesi', 'Geriye doğru tam emek yansıması', 'Mali sürüklenme ve dilim daralması'], 'Aynı kurumsal kazancın önce kurum bünyesinde sonra ortak elinde tekrar vergilendirilmesi ekonomik çifte vergilendirmedir.'),
  ('Kısa dönem ile uzun dönem karşılaştırıldığında, bir malın arz ve talep esneklikleri uzun dönemde arttığı için konulan yeni bir tüketim vergisinin uzun dönemdeki aşırı vergi yükü (refah kaybı) nasıl değişir?', 'Uzun dönemde miktar tepkisi büyüdüğü için aşırı vergi yükü kısa döneme göre artar', ['Uzun dönemde esneklikler sıfıra yaklaştığı için aşırı vergi yükü tamamen ortadan kalkar', 'Kısa ve uzun dönemde aşırı vergi yükü esnekliklerden bağımsız olarak sabit kalır', 'Uzun dönemde devletin topladığı vergi geliri artarken dara kaybı yarıya düşer'], 'Uzun dönemde ikame olanakları ve esneklikler büyüdüğünden vergi miktarı daha çok daraltır; vergi geliri düşerken dara kaybı büyür.'),
  ('Olivera-Tanzi etkisi yüksek enflasyonist ekonomilerde kamu maliyesinde hangi bozulmayı açıklar?', 'Vergiyi doğuran olay ile verginin tahsil edildiği tarih arasındaki gecikme nedeniyle enflasyonun reel vergi gelirlerini eritmesini', ['Enflasyon düştükçe mükelleflerin üst gelir dilimlerine çıkarak daha yüksek oranda vergi ödemesini', 'Merkez bankasının faiz oranlarını artırmasıyla dolaylı vergi gelirlerinin iki katına çıkmasını', 'Gelir dağılımını gösteren Lorenz eğrisinin enflasyonla birlikte mutlak eşitlik doğrusuna çakışmasını'], 'Tahakkuk ile tahsilat arasındaki süre uzadığında yüksek enflasyon devletin topladığı verginin satın alma gücünü düşürür; buna Olivera-Tanzi etkisi denir.'),
  ('Bir ekonomide toplam vergi gelirleri 2,4 trilyon TL ve Gayrisafi Yurt İçi Hasıla (GSYİH) 12 trilyon TL ise bu ülkedeki makroekonomik "toplam vergi yükü" oranı yüzde kaçtır?', 'Yüzde 20', ['Yüzde 24', 'Yüzde 15', 'Yüzde 50'], 'Makro vergi yükü = Toplam Vergi Gelirleri / GSYİH = 2,4 / 12 = 0,20 (%20).'),
  ('Lüks yat, mücevher veya özel kürk gibi talebinin fiyat esnekliği çok yüksek olan mallara çok yüksek oranda özel tüketim vergisi konulduğunda beklenen sonuç aşağıdakilerden hangisidir?', 'Tüketiciler bu mallardan kolayca kaçındığı için vergi zenginlerden ziyade o malları üreten sektördeki işçileri ve esnafı vurur', ['Talep çok esnek olduğu için satış miktarı hiç düşmez ve devlet rekor düzeyde vergi geliri elde eder', 'Vergi yükünün tamamı zengin alıcılar üzerinde kalır ve sektörde istihdam iki katına çıkar', 'Arz eğrisi tamamen dikey hale gelerek malın satış fiyatını vergi öncesinin altına çeker'], 'Lüks mal talebi çok esnekse alıcılar tüketimden vazgeçer (veya yurt dışına yönelir); satışlar çöker ve yük sektördeki inelastik emek/üretici üzerinde kalır.'),
  ('Arz fonksiyonu Qs = 2P ve talep fonksiyonu Qd = 180 - P olan bir piyasada devlet satıcıdan birim başına 15 TL vergi almaktadır. Vergi sonrası piyasa işlem hacmi (denge miktarı) kaç birim azalır?', '10 birim azalır', ['15 birim azalır', '20 birim azalır', '5 birim azalır'], 'Vergisiz denge: 2P = 180 - P -> P = 60, Q0 = 120. Vergili arz Qs = 2(Pt - 15) = 2Pt - 30 -> 2Pt - 30 = 180 - Pt -> 3Pt = 210 -> Pt = 70, Q1 = 110. Azalış = 120 - 110 = 10 birim.'),
  ('Bir ülkede ekonomik büyüme sonucunda herkesin reel geliri tam iki katına çıkarsa (örneğin 10.000 TL kazanan 20.000 TL, 50.000 TL kazanan 100.000 TL kazanırsa) Lorenz eğrisi ve Gini katsayısı nasıl değişir?', 'Göreli gelir payları değişmediği için Lorenz eğrisi ve Gini katsayısı aynı kalır', ['Herkesin geliri arttığı için Gini katsayısı yarı yarıya düşerek eşitlik artar', 'Zenginlerin mutlak gelir artışı daha büyük olduğu için Gini katsayısı iki katına çıkar', 'Lorenz eğrisi 45 derecelik mutlak eşitlik doğrusunun üzerine taşınır'], 'Gini katsayısı ölçekten bağımsızdır (scale invariance); tüm gelirler aynı pozitif sabitle çarpıldığında kümülatif yüzdeler ve Gini değişmez.'),
  ('Bir ülkede dört kişilik bir grubun yıllık gelirleri sırasıyla 10, 20, 30 ve 40 birimdir (toplam gelir 100 birim). En düşük gelirli %50\'lik nüfusun toplam gelirden aldığı kümülatif pay yüzde kaçtır?', 'Yüzde 30', ['Yüzde 25', 'Yüzde 50', 'Yüzde 20'], 'İlk iki kişinin gelir toplamı 10 + 20 = 30 birimdir; toplam gelir 100 birim olduğundan kümülatif pay %30\'dur.'),
  ('Pigou-Dalton transfer ilkesine göre, bireylerin gelir sıralamasını değiştirmeden zengin bir bireyden daha yoksul bir bireye karşılıksız gelir transferi yapıldığında Gini katsayısı nasıl etkilenir?', 'Gini katsayısı kesin olarak azalır', ['Gini katsayısı kesin olarak artar', 'Gini katsayısı hiçbir şekilde değişmez', 'Gini katsayısı önce 1\'e çıkar sonra sıfırlanır'], 'Pigou-Dalton ilkesine göre zenginden yoksula sızıntısız transfer eşitsizliği azaltır ve Lorenz eğrisini yukarı taşıyarak Gini\'yi düşürür.'),
  ('Bir malın alıcısından kanunen tahsil edilen birim vergi ile aynı tutarda satıcısından kanunen tahsil edilen birim vergi tam rekabet piyasasında karşılaştırıldığında denge miktar ve net fiyatlar için ne söylenebilir?', 'Vergi yansıması nedeniyle her iki durumda da alıcının ödediği brüt fiyat, satıcının aldığı net fiyat ve işlem miktarı birebir aynı olur', ['Vergi alıcıdan alındığında tüm yük alıcıda, satıcıdan alındığında tüm yük satıcıda kalır', 'Satıcıdan alınan vergi üretimi azaltırken alıcıdan alınan vergi üretimi artırır', 'Alıcıdan alınan vergide devletin topladığı toplam vergi geliri iki kat daha yüksek çıkar'], 'Verginin ekonomik yansıması kanuni mükellefiyetten bağımsızdır (vergi denkliği ilkesi); nihai yük dağılımı her iki durumda da aynıdır.'),
  ('Tam özel mallarda piyasa talep eğrisi bireysel talep eğrilerinin yatay toplamıyla elde edilirken tam kamusal mallarda nasıl elde edilir?', 'Bireysel talep eğrilerinin dikey toplanmasıyla', ['En yüksek gelirli grubun talebinin alınmasıyla', 'Bireysel talep eğrilerinin aritmetik ortalamasıyla', 'Marjinal maliyet eğrisinin yatay kaydırılmasıyla'], 'Kamusal mal miktarı herkes için sabit olduğundan her miktar düzeyinde bireylerin ödemeye razı olduğu fiyatlar dikey toplanır.'),
  ('Bir ekonomide kamu bütçe gelirleri 900 milyar TL, faiz dışı harcamalar 820 milyar TL ve borç faiz ödemeleri 130 milyar TL ise bütçe dengesi ve faiz dışı denge sırasıyla nedir?', '50 milyar TL açık ve 80 milyar TL fazla', ['80 milyar TL açık ve 50 milyar TL fazla', '50 milyar TL fazla ve 80 milyar TL açık', '130 milyar TL açık ve 80 milyar TL fazla'], 'Toplam gider 950 milyar TL olduğundan bütçe 50 milyar TL açık verir; faiz hariç gider 820 milyar TL olduğundan 80 milyar TL faiz dışı fazla oluşur.'),
  ('Paul Samuelson tarafından geliştirilen tam kamusal mallarda Pareto etkin üretim koşulu aşağıdakilerden hangisini gerektirir?', 'Bireylerin marjinal ikame oranları toplamının marjinal dönüşüm oranına eşitlenmesini', ['Her bir tüketicinin marjinal ikame oranının ayrı ayrı marjinal maliyete eşitlenmesini', 'Kamusal mal fiyatının tüketicilerin ortalama gelir düzeyine sabitlenmesini', 'Toplam marjinal faydanın sıfır olduğu noktada üretimin durdurulmasını'], 'Samuelson koşuluna göre kamusal mallarda etkin çıktı düzeyi ΣMRS = MRT eşitliğinde sağlanır.'),
  ('Ortak kaynakların serbest piyasada aşırı kullanılmasının temelinde yatan dışsallık mekanizması nasıl işler?', 'Bireysel kullanıcının diğer kullanıcılara yüklediği stok azaltma maliyetini hesaba katmaması', ['Üreticilerin tekel gücü kullanarak malın arzını yapay biçimde kısması', 'Devletin ortak kaynaklara yüksek oranlı mülkiyet vergisi uygulaması', 'Tüketicilerin ortak kaynağın kalitesi hakkında eksik bilgiye sahip olması'], 'Her kullanıcı kendi özel faydasına odaklanıp diğerlerinin avlama veya kullanma maliyetini artırdığı için negatif dışsallık doğar.'),
  ('Üç kişilik bir mahallede park aydınlatması için Ali 40 TL, Veli 50 TL ve Ayşe 70 TL marjinal fayda sağlıyorsa ve lambanın marjinal maliyeti 150 TL ise etkin karar ne olmalıdır?', 'Toplam marjinal fayda maliyeti aştığı için lamba kurulmalıdır', ['Hiçbir birey tek başına 150 TL ödemediği için kurulmamalıdır', 'Maliyet 70 TL\'ye düşene kadar yatırım süresiz ertelenmelidir', 'Yalnızca Ayşe\'nin ödeyeceği vergiyle lamba finanse edilmelidir'], 'Toplam marjinal fayda 40 + 50 + 70 = 160 TL olup 150 TL\'lik marjinal maliyeti aştığından kurulması sosyal açıdan etkindir.'),
  ('Erik Lindahl\'ın gönüllü değişim modelinde kamusal malların finansmanı için önerilen vergi fiyatları neye göre belirlenir?', 'Bireylerin kamusal maldan elde ettikleri marjinal faydalarla orantılı olmasına göre', ['Tüm vatandaşlardan gelir düzeyine bakılmaksızın eşit tutarda alınmasına göre', 'Yalnızca kamusal malı hiç kullanmayan yüksek gelirlilerin vergilendirilmesine göre', 'Üretimde kullanılan girdilerin ithalat paylarına göre kademelendirilmesine göre'], 'Lindahl dengesinde her birey kamusal maldan sağladığı marjinal faydaya eşit bir vergi fiyatı öder.'),
  ('Yarı kamusal mallar olarak da nitelendirilen eğitim ve sağlık hizmetlerinin tam kamusal mallardan ayrılan en belirgin yönü nedir?', 'Fiyat mekanizmasıyla dışlanabilir olmaları ve kapasite sınırında rekabet doğurmaları', ['Topluma hiçbir pozitif dışsallık sağlamadan yalnızca bireysel fayda üretmeleri', 'Devlet bütçesinden kesinlikle finanse edilemeyip sadece vakıflarca sunulmaları', 'Tüketildikleri anda ülke genelindeki tüm vatandaşlara eşit miktarda yayılmaları'], 'Okul ve hastaneler ücretle dışlanabilir ve kontenjan dolduğunda rakip hale gelir ancak yüksek pozitif dışsallık yayarlar.'),
  ('Kamu borcu stokunun milli gelire oranının düşürülmesinde faiz dışı fazlanın kritik rol oynamasının matematiksel mantığı nedir?', 'Reel faiz oranı büyüme oranını aştığında borç oranını sabit tutmak için pozitif faiz dışı fazla gerekmesi', ['Faiz dışı fazla verildiğinde merkez bankasının otomatik olarak para basmayı durdurması', 'Bütçe açığı artsa bile faiz dışı fazlanın dış ticaret açığını bire bir kapatması', 'Faiz dışı fazlanın doğrudan özel sektör yatırım harcamalarına eklenerek GSYH\'yi ikiye katlaması'], 'Reel faiz büyümeden büyükse borç/GSYH oranının patlamaması için devletin faiz dışı fazla üretmesi zorunludur.'),
  ('Devletin emeklilere 50 milyar TL ikramiye ödemesi ile 50 milyar TL tutarında otoyol yaptırmasının milli gelir denklemi üzerindeki ilk aşama etkileri nasıl farklılaşır?', 'Otoyol yapımı kamu harcamalarını doğrudan 50 milyar TL artırırken ikramiye harcanan kısmı kadar tüketimi artırır', ['Her iki harcama da milli geliri ilk aşamada tam 50 milyar TL tutarında doğrudan yükseltir', 'Emekli ikramiyesi milli geliri çarpan etkisiyle düşürürken otoyol yapımı sabit bırakır', 'İkramiye ödemesi ihracatı doğrudan artırırken otoyol yapımı yalnızca ithalatı azaltır'], 'Yatırım harcaması doğrudan GSYH içindeki G kalemine girer; transfer ise harcanabilir geliri artırıp marjinal tüketim eğilimi oranında tüketime yansır.'),
  ('James Buchanan tarafından geliştirilen kulüp teorisinde bir kulübün optimal üye sayısı ve tesis büyüklüğü nasıl belirlenir?', 'Yeni üyenin getirdiği maliyet paylaşımı faydasının yarattığı kalabalıklaşma maliyetine eşitlendiği noktada', ['Kulüp tesisinin fiziksel olarak alabileceği maksimum insan sayısına ulaşıldığı noktada', 'Üyelik aidatının sıfıra indirilerek tüm toplumun kulübe dahil edildiği noktada', 'Kulüp yöneticilerinin kar marjının toplam üye sayısını aştığı en düşük kapasitede'], 'Optimal kulüp büyüklüğü ek üyenin kişi başı maliyeti düşürme avantajı ile sıkışıklık maliyetinin dengelendiği yerdir.'),
  ('Erdemli malların varlığı tüketici egemenliği ilkesiyle neden gerilim halindedir?', 'Devletin bireyin kendi çıkarını en iyi bildiği varsayımını reddederek tercihlerine müdahale etmesi nedeniyle', ['Tüketicilerin tüm gelirlerini erdemli mallara harcayarak özel tasarrufları sıfırlaması nedeniyle', 'Üretici firmaların erdemli malları üretmeyi reddedip tamamen piyasadan çekilmesi nedeniyle', 'Erdemli malların yalnızca uluslararası kuruluşlar tarafından ülkelere zorla satılması nedeniyle'], 'Paternalist yaklaşım bireyin eksik bilgi veya irade zayıflığı yüzünden yanlış seçim yaptığını savunarak tüketici egemenliğini sınırlar.'),
  ('Marjinal tüketim eğiliminin 0,75 olduğu dışa kapalı sabit fiyatlı bir ekonomide devlet transfer harcamalarını 100 birim artırırsa denge milli gelir kaç birim artar?', '300 birim', ['400 birim', '75 birim', '100 birim'], 'Transfer çarpanı c / (1 - c) = 0,75 / 0,25 = 3 olduğundan 100 birimlik transfer artışı geliri 300 birim artırır.'),
  ('Açık erişimli bir yeraltı su havzasından tarımsal sulama yapan çiftçilerin su seviyesini hızla tüketmesini önlemek için uygulanabilecek piyasa temelli çözüm hangisidir?', 'Çekilen su miktarı üzerinden kota tahsisi ve alınıp satılabilir su hakları tanımlanması', ['Tarımsal sulamada kullanılan elektrik ve mazot fiyatlarının devletçe sıfırlanması', 'Bölgedeki tüm çiftçilere kuyu açma maliyetlerini karşılayan hibe kredisi verilmesi', 'Üretilen tarım ürünlerine taban fiyat uygulanarak alım garantisi getirilmesi'], 'Mülkiyet hakları ve ticareti yapılabilir kotalar ortak kaynak üzerindeki aşırı kullanım güdüsünü ortadan kaldırır.'),
  ('Küçük gruplarda bedavacılık sorununun büyük gruplara kıyasla daha kolay aşılabilmesinin temel nedeni Mancur Olson\'a göre nedir?', 'Bireysel katkının toplam sonuca etkisinin görünür olması ve sosyal denetimin kolay işlemesi', ['Küçük gruplardaki insanların doğuştan tamamen özgecil tercihlere sahip olması', 'Devletin küçük gruplara her zaman karşılıksız bütçe sübvansiyonu sağlaması', 'Küçük gruplarda kamusal malın üretim maliyetinin her zaman sıfır olması'], 'Küçük gruplarda kimin ödeme yapmadığı kolayca fark edilir ve her bireyin katkısı malın sunumu için belirleyicidir.'),
  ('Kamu bütçesinde sermaye transferleri ile doğrudan yatırım harcamaları arasındaki temel fark nedir?', 'Sermaye transferinde devletin kendisi mal üretmeyip özel kesimin yatırım yapması için kaynak aktarması', ['Doğrudan yatırım harcamalarının bütçe gideri sayılmayıp yalnızca bilanço dipnotunda izlenmesi', 'Sermaye transferlerinin sadece memur maaşlarını ödemek amacıyla kısa vadeli kullanılması', 'Doğrudan yatırımların milli geliri düşürürken sermaye transferlerinin cari açığı kapatması'], 'Özel sektöre fabrika kurması için verilen yatırım teşvik hibesi sermaye transferidir; devletin köprü yapması doğrudan yatırımdır.'),
  ('Bir belediyenin kurduğu kablosuz internet ağına şifre koymadan herkesin girmesine izin vermesi ve binlerce kişinin bağlanmasıyla hızın düşmesi malın niteliğini nasıl değiştirir?', 'Tam kamusal mal görünümünden ortak kaynak niteliğine dönüştürür', ['Ortak kaynak yapısından tam özel mal statüsüne geçirir', 'Kulüp malı özelliğinden tam kamusal mal sınıfına taşır', 'Erdemsiz mal grubundan erdemli mal kategorisine yükseltir'], 'Şifresiz erişim dışlanamama yaratırken bant genişliğinin dolup hızın düşmesi tüketimde rekabet doğurur.'),
  ('Ronald Coase\'un deniz fenerleri üzerine yaptığı tarihsel inceleme iktisat teorisindeki hangi yerleşik kabulü sorgulamıştır?', 'Deniz fenerlerinin hiçbir koşulda özel sektör tarafından işletilip finanse edilemeyeceği görüşünü', ['Deniz feneri ışığının geceleri gemiler tarafından aynı anda görülebildiği gerçeğini', 'Deniz ticaretinin ülke ekonomilerinin büyümesine olumlu katkı sağladığı tezini', 'Devletin liman vergisi toplama yetkisinin anayasal kurallara dayandığı ilkesini'], 'Coase, İngiltere tarihinde özel girişimcilerin liman rüsumları aracılığıyla deniz feneri inşa edip karla işlettiklerini göstermiştir.'),
  ('Erdemsiz mallara uygulanan yüksek özel tüketim vergilerinin maliye politikasındaki çift yönlü amacı nedir?', 'Zararlı tüketimi caydırarak negatif dışsallığı azaltmak ve kamu bütçesine gelir sağlamak', ['Malın fiyatını düşürerek dar gelirli tüketicilerin alım gücünü doğrudan desteklemek', 'Yerli üreticilerin ihracat pazarlarındaki rekabet gücünü vergi iadesiyle artırmak', 'Tüketicileri özel tasarruf yerine lüks ithal malları satın almaya yönlendirmek'], 'Günah vergileri olarak da bilinen bu vergiler hem tüketimi kısar hem de sağlık maliyetlerini karşılayacak bütçe geliri yaratır.'),
  ('Bir ülkede GSYH 20 trilyon TL, bütçe açığı 600 milyar TL ve faiz giderleri 900 milyar TL ise faiz dışı fazlanın GSYH\'ye oranı yüzde kaçtır?', 'Yüzde 1,5', ['Yüzde 3,0', 'Yüzde 4,5', 'Yüzde 0,5'], 'Faiz dışı denge = Bütçe dengesi + Faiz giderleri = -600 + 900 = +300 milyar TL; 300 milyar / 20 trilyon = %1,5 bulunur.'),
  ('Tam kamusal malların özel bağışlarla finanse edildiği bir ortamda gönüllü katkıların sosyal optimumun altında kalmasının oyun teorisindeki karşılığı nedir?', 'Baskın stratejinin katkıda bulunmamak olduğu çok oyunculu mahkumların ikilemi', ['Tüm oyuncuların en yüksek ödemeyi seçtiği saf koordinasyon oyunu', 'İlk hamleyi yapanın tüm maliyeti gönüllü üstlendiği lider-takipçi dengesi', 'Oyuncuların sırayla birbirini ödüllendirdiği sıfır toplamlı rekabet oyunu'], 'Diğerleri ödese de ödemese de bireyin ödememesi kendi kazancını maksimize ettiğinden Nash dengesi eksik üretimdir.'),
  ('Ekonomik istikrar açısından işsizlik sigortası ödemeleri gibi transfer harcamalarının otomatik istikrarlandırıcı sayılmasının nedeni nedir?', 'Ekonomik daralma dönemlerinde yasa değişikliği gerekmeden kendiliğinden artarak toplam talebi desteklemesi', ['Enflasyon yükseldiğinde işsizlik maaşlarının otomatik olarak iki katına çıkarılması', 'Ekonomik büyüme hızlandığında bütçe fazlalarını sıfırlayarak tüketimi körüklemesi', 'Merkez bankasının faiz kararlarına paralel olarak her ay meclis oylamasıyla belirlenmesi'], 'Durgunlukta işsiz sayısı artınca transfer ödemeleri otomatik yükselir ve harcanabilir gelirdeki düşüşü frenler.'),
  ('Bir malın dışlanamama özelliğinin salt fiziksel değil aynı zamanda teknolojik ve ekonomik bir kavram olduğunu hangi örnek en iyi kanıtlar?', 'Elektronik geçiş sistemlerinin icadıyla şehir içi yollarda araçlardan düşük maliyetle ücret alınabilmesi', ['Güneş ışığının bulutlu günlerde yeryüzüne daha az ulaşarak tarımsal verimi düşürmesi', 'Açık denizlerdeki balıkların mevsimsel göç yollarını su sıcaklığına göre değiştirmesi', 'Merkez bankasının bastığı kağıt paraların zamanla yıpranarak tedavülden kaldırılması'], 'Eskiden gişe kurmanın çok maliyetli olduğu yollar, elektronik sensörler sayesinde düşük maliyetle dışlanabilir hale gelmiştir.'),
  ('İki tüketicili bir ekonomide kamusal malın miktarı Q iken ters talep fonksiyonları P1 = 100 - Q ve P2 = 80 - 2Q olup marjinal maliyet MC = 60 ise sosyal açıdan etkin üretim miktarı kaçtır?', '40', ['30', '60', '20'], 'Dikey toplam P1 + P2 = 180 - 3Q = 60 eşitliğinden 3Q = 120 ve Q = 40 bulunur (bu noktada P1=60>0 ve P2=0>=0 sağlanır).'),
  ('Kamu bütçesinde vergi harcamaları kavramı transfer harcamalarıyla karşılaştırıldığında neyi ifade eder?', 'Belirli gruplara doğrudan nakit vermek yerine vergi istisna ve muafiyetleriyle bütçe gelirinden vazgeçilmesini', ['Vergi dairelerinin bina kirası, personel maaşı ve tahsilat yazılımı için yaptığı idari giderleri', 'Devletin topladığı vergileri yalnızca altyapı projelerinde kullanmasını zorunlu kılan yasal kuralı', 'Mükelleflerin vergi beyannamesi hazırlarken mali müşavirlere ödedikleri hizmet bedellerini'], 'Vergi indirimleri ve muafiyetleri ekonomik etki bakımından örtülü birer transfer veya sübvansiyon niteliğindedir.'),
  ('Uluslararası iklim değişikliğiyle mücadelede sera gazı azaltımının küresel bir tam kamusal mal niteliği taşıması ülkeler arasında hangi temel sorunu doğurur?', 'Emisyon azaltma maliyetini üstlenmeyen ülkelerin temizlenen atmosferden eşit yararlanarak bedavacılık yapması', ['Karbon emisyonunu azaltan ülkelerin kendi sınırları içindeki havayı diğer ülkelerden tamamen izole edebilmesi', 'Atmosfer kalitesinin iyileşmesinin yalnızca ekvator kuşağındaki ülkelerde tüketimde rekabet yaratması', 'Küresel ısınmayı önleme yatırımlarının ülkelerin kısa vadeli faiz dışı fazlalarını otomatik artırması'], 'Atmosferin iyileşmesinden hiçbir ülke dışlanamadığı için ülkeler maliyeti başkalarının üstlenmesini bekler.'),
  ('Charles Tiebout\'un "ayaklarıyla oy verme" hipotezi yerel kamusal mallar bağlamında bedavacılık sorununa nasıl bir çözüm mekanizması önerir?', 'Bireylerin vergi ve yerel hizmet paketlerini tercihlerine en uygun buldukları belediyelere taşınarak taleplerini açıklaması', ['Vatandaşların yerel seçimlerde sandığa gitmeyerek belediye bütçelerini geçersiz kılması', 'Merkezi yönetimin tüm belediyelerde tek tip vergi ve standart park hizmeti dayatması', 'Yerel yönetimlerin tüm kamusal parkları özelleştirerek yüksek giriş ücreti koyması'], 'Farklı vergi-hizmet kombinasyonları sunan yerel birimler arasında göç imkanı, bireylerin gerçek tercihlerini ortaya koymasını sağlar.'),
  ('Devlet bütçesinde vergi gelirleri 1.200 birim, vergi dışı normal gelirler 200 birim, cari harcamalar 600 birim, yatırım harcamaları 350 birim ve transfer harcamaları (300 birimi faiz olmak üzere) 550 birim ise faiz dışı fazla kaç birimdir?', '200 birim', ['100 birim', '150 birim', '250 birim'], 'Toplam gelir = 1.400; toplam gider = 600 + 350 + 550 = 1.500; faiz dışı gider = 1.500 - 300 = 1.200; faiz dışı fazla = 1.400 - 1.200 = 200 birimdir.'),
  ('Patent ve telif hakları sistemi bilgi ve buluşların iktisadi niteliğinde nasıl bir dönüşüm gerçekleştirir?', 'Doğası gereği rakip olmayan bilgiyi yasal olarak dışlanabilir kılarak yapay bir kulüp veya tekel malına dönüştürür', ['Bilginin tüketimde rakip olmama özelliğini yok ederek her kullanımda bilginin fiziksel olarak tükenmesini sağlar', 'Yeni buluşların topluma yaydığı pozitif dışsallıkları anında sıfırlayarak tam özel tüketime hapseder', 'Araştırma ve geliştirme maliyetlerini tamamen devlet bütçesindeki transfer harcamalarına yıkar'], 'Bilgi doğası gereği rakip değildir; patent yasası izinsiz kullanımı engelleyerek (dışlanabilirlik yaratarak) yenilik güdüsünü korur.'),
  ('Ekonomik sınıflandırmada devletin zarar eden kamu iktisadi teşebbüslerine görev zararı karşılığı yaptığı ödemeler hangi kalemde yer alır?', 'Ekonomik transfer harcamaları', ['Sabit sermaye yatırımları', 'Cari mal ve hizmet alımları', 'Faiz dışı sermaye gelirleri'], 'Üretici birimlere maliyetlerini desteklemek amacıyla karşılıksız aktarılan kaynaklar ekonomik transferdir.'),
  ('Erdemli malların desteklenmesinde nakdi gelir transferi yerine gıda kuponu veya eğitim çeki gibi ayni yardımların tercih edilmesinin paternalist gerekçesi nedir?', 'Yardım alan bireyin nakit parayı devletin hedeflediği erdemli mal yerine başka tüketim alanlarına kaydırmasını önlemek', ['Ayni yardımların yönetim ve dağıtım maliyetinin banka havalesinden her zaman daha ucuz olması', 'Kupon uygulamalarının tüketicinin kayıtsızlık eğrilerini değiştirmeden faydasını nakitten daha çok artırması', 'Gıda ve eğitim kuponlarının piyasadaki üretici firmaların kar marjlarını sıfırlaması'], 'Paternalist devlet sadece gelir artışını değil, belirli bir malın (eğitim, beslenme) asgari düzeyde tüketilmesini garanti altına almak ister.'),
  ('Bir balıkçı köyünde göle gönderilen tekne sayısı x iken toplam balık avı geliri TR = 120x - 2x² ve her teknenin maliyeti TC = 20x ise serbest giriş dengesinde ve sosyal optimumda göle kaç tekne açılır?', 'Serbest girişte 50 tekne, sosyal optimumda 25 tekne', ['Serbest girişte 25 tekne, sosyal optimumda 50 tekne', 'Serbest girişte 60 tekne, sosyal optimumda 30 tekne', 'Serbest girişte 40 tekne, sosyal optimumda 20 tekne'], 'Serbest girişte ortalama gelir maliyete eşitlenir: 120 - 2x = 20 -> x = 50; sosyal optimumda marjinal gelir maliyete eşitlenir: 120 - 4x = 20 -> x = 25.'),
  ('Kamu bütçesinde birincil açık (faiz dışı açık) veren bir ülkenin borç dinamikleri hakkında ne söylenebilir?', 'Devletin mevcut borçlarının faizini ödemek bir yana günlük kamu hizmetlerini yürütmek için bile yeni borç aldığı', ['Ülkenin toplam kamu borcu stokunun bir sonraki mali yılda kesinlikle sıfırlanacağı', 'Merkez bankasının döviz rezervlerinin bütçe fazlaları sayesinde hızla biriktiği', 'Toplam bütçe gelirlerinin faiz ödemeleri dahil tüm kamu giderlerinden yüksek olduğu'], 'Faiz dışı açık, vergi ve diğer gelirlerin faiz hariç temel giderleri bile karşılayamadığını ve borç yükünün ağırlaştığını gösterir.'),
  ('Bir otoyolun gece yarısı boşken kulüp malı, sabah iş çıkış saatinde gişeli olmasına rağmen tıkandığında ise özel mala yaklaşmasının sebebi nedir?', 'Gişeler dışlanabilirliği sürekli sağlarken yoğun saatlerde ek aracın diğerlerini yavaşlatarak rekabet yaratması', ['Gece saatlerinde otoyol gişelerinin yasal olarak ücret toplama yetkisini kaybetmesi', 'Sabah saatlerinde devletin otoyolu tüm vatandaşlara ücretsiz hale getirmesi', 'Otoyol asfaltının yalnızca gündüz saatlerinde aşınıp gece hiç yıpranmaması'], 'Ücretli gişe dışlanabilirlik sağlar; trafik sıkışıklığı başladığında rakip olmama özelliği kaybolur ve mal hem dışlanabilir hem rakip olur.'),
  ('Gelir dağılımı adaletini sağlamaya yönelik maliye politikasında artan oranlı gelir vergisi ile sosyal transfer harcamaları birlikte uygulandığında nasıl bir etki doğar?', 'Yüksek gelirlilerden alınan kaynak düşük gelirlilere aktarılarak Lorenz eğrisi mutlak eşitlik doğrusuna yaklaşır', ['Gini katsayısı sıfırdan bire doğru yükselerek gelir eşitsizliği en üst düzeye çıkar', 'Marjinal tüketim eğilimi düşük olan grupların toplam harcamadaki payı hızla artar', 'Kamu bütçesindeki yatırım harcamaları otomatik olarak toplam gelirin tamamını kapsar'], 'Yeniden dağıtıcı vergi ve transfer politikası gelir uçurumunu daraltarak Gini katsayısını düşürür ve Lorenz eğrisini eşitlik çizgisine yaklaştırır.'),
  ('Ortak mülkiyetteki bir otlakta her köylünün sürüye eklediği fazladan bir ineğin köylüye sağladığı özel fayda ile köye yüklediği sosyal maliyet arasındaki ilişki nasıldır?', 'Ek ineğin tüm kazancı sahibine giderken otlağın verim kaybı tüm köylüler arasında paylaşıldığından özel fayda özel maliyeti aşar', ['Ek ineğin süt verimi tüm köylülere eşit dağıtılırken yem maliyeti yalnızca sürü sahibine yüklenir', 'Özel marjinal fayda ile sosyal marjinal maliyet her otlatma düzeyinde birbirine tam eşittir', 'Sürüye yeni inek eklendikçe otlağın doğal çimlenme hızı artarak pozitif dışsallık yaratır'], 'Faydanın özelleşmesi ve maliyetin ortaklaşması bireyleri sosyal optimumun üzerinde hayvan otlatmaya iter.'),
  ('Bir ekonomide vergi gelirleri 500 birim, kamu cari ve yatırım harcamaları toplamı 420 birim, sosyal transferler 110 birim ve borç faiz ödemeleri 90 birim ise bütçe açığı ve faiz dışı denge nedir?', '120 birim bütçe açığı ve 30 birim faiz dışı açık', ['120 birim bütçe açığı ve 60 birim faiz dışı fazla', '30 birim bütçe açığı ve 90 birim faiz dışı fazla', '210 birim bütçe açığı ve 30 birim faiz dışı açık'], 'Toplam gider = 420 + 110 + 90 = 620, bütçe dengesi = 500 - 620 = -120; faiz dışı gider = 420 + 110 = 530, faiz dışı denge = 500 - 530 = -30\'dur.'),
  ('Radyo ve şifresiz karasal televizyon yayınlarının iktisat ders kitaplarında tam kamusal mal olarak sınıflandırılmasının dayanağı nedir?', 'Verici kurulduktan sonra ek bir alıcının yayını dinlemesinin diğerlerinin sinyal kalitesini düşürmemesi ve açık sinyalin engellenememesi', ['Radyo kanallarının tamamının yalnızca devlet bütçesinden toplanan gelir vergileriyle işletilmesi', 'Radyo programlarının dinleyiciler üzerinde hiçbir zaman reklam etkisi yaratmaması', 'Televizyon cihazlarının mağazalarda ücretsiz olarak tüm vatandaşlara dağıtılması'], 'Karasal açık yayın hem rakip olmama (marjinal maliyet sıfır) hem de şifresiz olduğu sürece dışlanamama özelliği taşır.'),
  ('Uyuşturucu maddelerin yasaklanması ve kumar faaliyetlerinin ağır kısıtlamalara tabi tutulması devletin hangi mal grubuna müdahalesini yansıtır?', 'Erdemsiz mallar', ['Erdemli mallar', 'Tam kamusal mallar', 'Kulüp malları'], 'Bireye ve topluma ciddi zarar veren ve irade kaybı yaratan ürünlerin yasaklanması erdemsiz mal politikasıdır.'),
  ('Özel yüzme havuzları ve spor salonlarının üyelik sistemiyle çalışması bu hizmetleri neden ortak kaynak olmaktan korur?', 'Üyelik ücreti ve turnike sistemiyle dışlanabilirlik sağlanarak aşırı kalabalıklaşmanın fiyat yoluyla kontrol edilebilmesi', ['Havuz suyunun hiçbir zaman kirlenmeyip sonsuz sayıda insanı aynı anda alabilmesi', 'Spor salonlarının kar amacı gütmeden tamamen mahalle muhtarlıklarınca yönetilmesi', 'Üyelerin spor salonunu kullandıkça diğer üyeler için boş alan miktarının artması'], 'Giriş kontrolü (dışlanabilirlik) sayesinde kulüp işletmecisi kapasiteyi aşacak talebi aidatla sınırlar ve ortakların trajedisini önler.'),
  ('Marjinal tasarruf eğiliminin 0,20 ve götürü vergilerin geçerli olduğu dışa kapalı bir ekonomide devlet sosyal transferleri 50 birim artırıp bunu 50 birimlik götürü vergi artışıyla finanse ederse denge milli gelir nasıl değişir?', 'Hiç değişmez', ['50 birim artar', '200 birim artar', '250 birim azalır'], 'Transfer çarpanı c/(1-c) = +4 ve götürü vergi çarpanı -c/(1-c) = -4 olduğundan eşit miktardaki artışların net etkisi (50×4) + (50×-4) = 0 olur.'),
  ('İlköğretimin devlet tarafından zorunlu ve ücretsiz hale getirilmesi hangi iki iktisadi kavramın kesişiminde gerekçelendirilir?', 'Yüksek pozitif dışsallık yayan yarı kamusal mal olması ve bireysel ihmale bırakılamayacak erdemli mal niteliği taşıması', ['Tüketimde hiçbir maliyeti olmayan serbest doğa malı olması ve dış ticaret fazlası yaratması', 'Tamamen dışlanamaz bir mal olması ve hiçbir özel okulun teknik olarak açılamaması', 'Ülkenin borç faiz ödemelerini kısa vadede doğrudan sıfırlayan bir transfer kalemi olması'], 'Eğitim hem toplumsal verimlilik ve yurttaşlık bilinciyle pozitif dışsallık üretir hem de çocukların geleceğini koruyan erdemli maldır.'),
  ('Devletin tarım üreticilerine gübre ve mazot desteği olarak yaptığı karşılıksız nakit ödemeler kamu harcamalarının ekonomik sınıflandırmasında ne olarak değerlendirilir?', 'Üreticiye yönelik ekonomik transfer', ['Kamu sabit sermaye yatırımı', 'Devlet cari tüketim harcaması', 'Borç servisi faiz ödemesi'], 'Üretim maliyetlerini düşürmek amacıyla işletmelere karşılıksız verilen sübvansiyonlar ekonomik transfer harcamasıdır.'),
  ('İki kişilik bir odada klima takılması kamusal mal niteliğindedir; Ahmet\'in klimaya verdiği değer 4.000 TL, Mehmet\'in verdiği değer 3.500 TL ve klimanın fiyatı 6.000 TL iken maliyeti eşit (3.000\'er TL) paylaşma teklifi oylanırsa sonuç ne olur?', 'Her ikisinin de net faydası pozitif olacağından oybirliğiyle kabul edilir ve sosyal etkinlik sağlanır', ['Ahmet kabul ederken Mehmet net zarar edeceği için teklifi reddeder ve klima alınamaz', 'Toplam değer 6.000 TL\'nin altında kaldığı için her ikisi de teklifi reddeder', 'Mehmet bedavacılık yaparak ödemeyi reddeder ve Ahmet tek başına 6.000 TL ödeyerek klimayı alır'], '3.000 TL\'lik maliyet payı Ahmet\'e 1.000 TL, Mehmet\'e 500 TL net tüketici rantı sağladığından ikisi de evet oyu verir.'),
  ('Ortak kaynak niteliğindeki açık deniz balıkçılığında avlanma teknolojisinin (sonar ve dev ağlar) hızla gelişmesi düzenleme yoksa uzun dönemde balıkçıların gelirini nasıl etkiler?', 'Kısa vadede avı artırsa da balık stokunu hızla çökertip birim av maliyetini yükselterek uzun dönem aşırı karları sıfırlar', ['Balık sürülerinin üreme hızını teknolojik olarak artırarak tüm balıkçıları kalıcı zenginliğe ulaştırır', 'Denizdeki balık miktarını sabit tutarken balık fiyatlarını kalıcı olarak sıfıra indirir', 'Açık denizleri kendiliğinden özel mülkiyete dönüştürerek dışlanamama sorununu çözer'], 'Regülasyon olmayan ortak kaynakta teknolojik ilerleme aşırı avlanmayı hızlandırır ve biyolojik stoku eriterek ekonomik rantı yok eder.'),
  ('Kamu bütçesinde "kalkınma carileri" olarak adlandırılan eğitim ve sağlık personeli maaşlarının klasik cari harcamalardan farkı nedir?', 'Fiziksel bina yatırımı olmasa da beşeri sermayeyi geliştirerek uzun dönemli büyüme kapasitesini artırmaları', ['Karşılıksız olarak emeklilere ödenen sosyal transfer harcamaları içinde sınıflandırılmaları', 'Yalnızca yabancı para cinsinden dış borç faizlerini ödemek için kullanılmaları', 'İçinde bulunulan mali yıl bittiğinde ekonomiye hiçbir kalıcı fayda bırakmadan tamamen tükenmeleri'], 'Öğretmen ve doktor maaşları cari görünse de insan kaynağına yatırım niteliği taşıdığından kalkınma carisi sayılır.'),
  ('Adolph Wagner\'in "kamu harcamalarının artış yasası" sanayileşen ve gelir düzeyi yükselen toplumlarda bütçe büyüklüğünün nasıl değişeceğini öngörür?', 'Eğitim, sağlık, kentleşme ve düzenleyici kamusal mal talebinin gelir esnekliği birden büyük olduğundan kamu harcamalarının milli gelirdeki payının artacağını', ['Ekonomik büyüme sağlandıkça kamusal mallara olan ihtiyacın azalarak devlet bütçesinin tamamen küçüleceğini', 'Sanayileşme sürecinde yalnızca borç faiz ödemelerinin artıp reel kamu yatırımlarının sıfırlanacağını', 'Kamu harcamalarının milli gelire oranının tüm ülkelerde tarihsel olarak sabit bir yüzdede donacağını'], 'Wagner\'e göre refah ve karmaşıklık arttıkça kamusal ve yarı kamusal hizmetlere talep gelirden daha hızlı büyür.'),
  ('Bir ekonomide toplam bütçe giderleri 2.400 milyar TL, bütçe açığı 300 milyar TL ve faiz dışı fazla 150 milyar TL ise devletin yaptığı faiz ödemeleri kaç milyar TL\'dir?', '450 milyar TL', ['150 milyar TL', '300 milyar TL', '600 milyar TL'], 'Gelirler = 2.400 - 300 = 2.100; faiz dışı giderler = 2.100 - 150 = 1.950; faiz ödemeleri = 2.400 - 1.950 = 450 milyar TL (veya FDF - Bütçe Dengesi = 150 - (-300) = 450).'),
  ('Ortak bir balıkçılık alanında bireysel avlanabilir ve devredilebilir kota (ITQ) sisteminin uygulanması ekonomik etkinliği hangi yolla sağlar?', 'Toplam avı sürdürülebilir düzeyde sınırlarken kotaların düşük verimli balıkçılardan yüksek verimli balıkçılara satılmasıyla maliyetleri minimize etmesiyle', ['Denizdeki tüm balıkları devletin avlayıp balıkçılara eşit miktarda sosyal transfer olarak dağıtmasıyla', 'Balık fiyatlarını piyasa dengesinin altına çekerek tüketicilerin aşırı balık tüketmesini sağlamasıyla', 'Kota sahiplerinin avlanma mevsimi boyunca hiçbir maliyet katlanmadan sübvansiyon almasıyla'], 'Devredilebilir kota hem biyolojik stoku korur (dışlanabilir mülkiyet hakkı) hem de ticaret yoluyla en düşük maliyetli üreticilerin avlanmasını sağlar.'),
  ('Peacock ve Wiseman tarafından geliştirilen "sıçrama tezi" kamu bütçesindeki harcama ve vergi düzeyinin zaman içindeki seyrini nasıl açıklar?', 'Savaş ve büyük ekonomik kriz dönemlerinde katlanılabilir vergi yükü eşiğinin yukarı kayarak kriz sonrasında da harcamaların eski düşük seviyesine dönmemesiyle', ['Kamu harcamalarının her seçim yılında iki katına çıkıp seçim ertesi yılda yarıya düşmesiyle', 'Teknolojik icatların her on yılda bir tam kamusal malları özel mallara dönüştürerek bütçeyi küçültmesiyle', 'Faiz dışı fazlanın her mali yılda sabit bir aritmetik diziyle kesintisiz yükselmesiyle'], 'Büyük toplumsal sarsıntılar vatandaşların vergi toleransını artırır ve kamu bütçesi yeni bir yüksek platoya sıçrar.'),
  ('Marjinal tüketim eğilimi 0,6 ve gelir vergisi oranı 0,25 olan dışa kapalı bir ekonomide devlet otonom transfer harcamalarını 220 birim artırırsa denge milli gelir kaç birim artar?', '240 birim', ['300 birim', '132 birim', '220 birim'], 'İlk tur tüketim artışı 0,6 × 220 = 132 birimdir; vergi oranlı çarpan 1 / [1 - 0,6(1 - 0,25)] = 1 / 0,55 = 20/11 olduğundan ΔY = 132 × (20/11) = 240 birim bulunur.'),
  ('Şekerli gazlı içeceklere veya yüksek kalorili işlenmiş gıdalara "obezite vergisi" konulmasına yöneltilen gelir dağılımı temelli en önemli iktisadi eleştiri nedir?', 'Düşük gelirli hanelerin bütçelerinde bu ürünlerin payı daha yüksek olduğundan dolaylı verginin tersine artan oranlı (regresif) etki yaratması', ['Bu verginin yüksek gelirli bireylerin tasarruf oranlarını sıfıra indirerek yatırımları durdurması', 'Obezite vergisinin devlet bütçesinde doğrudan faiz ödemelerini artırarak bütçe açığı doğurması', 'Vergi konulduğunda tüketicilerin bu malları Giffen malı gibi daha fazla satın almaya başlaması'], 'Erdemsiz mallara konan spesifik tüketim vergileri dar gelirlilerin gelirinden oransal olarak daha büyük pay alır; bu etki sağlık yardımlarıyla dengelenmeye çalışılır.'),
  ('Kamu bütçesinde "görev zararı" ödemeleri ile "vergi iadesi / ihracat teşviki" ödemelerinin ortak iktisadi özelliği nedir?', 'Her ikisinin de karşılıksız kaynak aktarımı niteliğinde ekonomik transfer harcaması olması', ['Her ikisinin de devletin doğrudan makine ve teçhizat üretimi yaptığı yatırım gideri olması', 'Her ikisinin de yalnızca yabancı devletlere ödenen dış borç anapara taksiti olması', 'Her ikisinin de kamu bütçesinde gelir kalemi olarak pozitif bakiye yaratması'], 'Devletin KİT\'lerin sübvansiyonlu satış zararını karşılaması ve ihracatçıyı desteklemesi üretim birimine yapılan ekonomik transferdir.'),
  ('Deneysel iktisatta yürütülen "kamusal mal oyunları" (public goods games) standart oyun teorisinin "sıfır katkı" öngörüsüyle karşılaştırıldığında ne tür bulgular ortaya koymuştur?', 'İlk turlarda oyuncuların önemli düzeyde gönüllü katkı yaptığı ancak bedavacıları cezalandırma imkanı yoksa katkıların tekrarlayan turlarda giderek düştüğü', ['İnsanların deneyin ilk turundan son turuna kadar istisnasız sıfır birim katkıda bulunduğu', 'Katılımcıların her turda tüm paralarını kamusal havuza yatırarak yüzde yüz işbirliği sağladığı', 'Grup büyüklüğü azaldıkça bedavacılık oranının her zaman keskin biçimde arttığı'], 'Deneyler koşullu işbirlikçilerin varlığını gösterir; bedavacılar cezalandırılamadığında işbirlikçiler de katkıyı keser, cezalandırma seçeneği eklendiğinde ise katkılar yükselir.'),
  ('Bir kulüp tesisinin sabit kurulum maliyeti 10.000 TL olup üye sayısı N iken her üyenin tesisten aldığı brüt fayda 500 TL ve kalabalıklaşma maliyeti üye başına 4N TL ise mevcut üyelerin net faydasını maksimize eden optimal üye sayısı kaçtır?', '50 üye', ['100 üye', '25 üye', '125 üye'], 'Üye başına net fayda 500 - 4N - (10.000 / N) fonksiyonunun türevi sıfıra eşitlendiğinde -4 + 10.000/N² = 0 denkleminden N² = 2.500 ve N = 50 üye bulunur.'),
  ('Yerel yönetimlerin sunduğu itfaiye hizmetinin bir yangın çıktığında komşu binalara sıçramasını önlemesi hangi iktisadi kavramla açıklanır?', 'Yüksek pozitif dışsallık ve yerel kamusal mal niteliği', ['Negatif tüketim dışsallığı ve ortakların trajedisi', 'Tam özel mal fiyatlaması ve ölçek ekonomisi', 'Erdemsiz mal kısıtlaması ve mali sürüklenme'], 'Yangın söndürme hizmeti hem yanan binayı kurtarır hem de mahallenin tamamını koruyarak dışlanamayan geniş bir dışsal fayda üretir.'),
  ('Kamu bütçesinde "mali sürüklenme" (fiscal drag) enflasyonist bir ortamda transfer harcamaları ve vergi gelirleri üzerinden bütçe dengesini kısa vadede nasıl etkiler?', 'Nominal geliri artan mükelleflerin üst vergi dilimlerine geçmesiyle reel vergi gelirlerini artırıp sabit tutarlı transferlerin reel değerini eriterek faiz dışı fazlayı yapay iyileştirir', ['Vergi tahsilatını tamamen durdurup transfer ödemelerini enflasyonun iki katı hızla artırarak faiz dışı açığı büyütür', 'Kamu yatırımlarının maliyetini sıfırlayarak bütçenin tüm harcama kalemlerini denk hale getirir', 'Devlet tahvillerinin vadesini otomatik olarak uzatarak iç borç stokunu tamamen siler'], 'Artan oranlı tarifede enflasyon mükellefleri üst dilime iter (gelir artar) ve endekslenmemiş sosyal yardımların reel yükü düşer.'),
  ('İki kişilik bir toplumda savunma harcaması G birimin toplam maliyeti TC = 10G² iken Birey 1\'in marjinal faydası MB1 = 120 - 2G ve Birey 2\'nin marjinal faydası MB2 = 80 - 3G ise Pareto etkin savunma düzeyi G kaç birimdir?', '8 birim', ['10 birim', '16 birim', '4 birim'], 'Toplam marjinal fayda MB1 + MB2 = 200 - 5G ve marjinal maliyet MC = 20G olduğundan 200 - 5G = 20G -> 25G = 200 -> G = 8 birim bulunur.'),
  ('Sübvansiyonlar ile sosyal transfer harcamaları arasındaki ayrım ulusal gelir muhasebesinde piyasa fiyatları ve faktör fiyatları arasındaki farkı nasıl etkiler?', 'Üreticiye verilen sübvansiyonlar piyasa fiyatını faktör maliyetinin altına çekerken hane halkına yapılan sosyal transferler doğrudan harcanabilir gelire eklenir', ['Sosyal transferler malların dolaylı vergi oranını artırırken sübvansiyonlar emekli maaşlarını düşürür', 'Her iki ödeme türü de gayrisafi yurtiçi hasılanın üretim yöntemiyle hesabına net artış olarak eklenir', 'Sübvansiyonlar yalnızca ithal tüketim mallarına verilirken sosyal transferler yalnızca ihracatçı firmalara ödenir'], 'Ekonomik transfer olan sübvansiyonlar ürün maliyetini düşürerek piyasa fiyatını etkiler; sosyal transferler ise faktör gelirlerinden bağımsız olarak kişisel geliri artırır.'),
  ('Açık kaynaklı yazılımların (örneğin Linux çekirdeği) binlerce gönüllü yazılımcı tarafından bedavacılık sorununa rağmen başarıyla üretilebilmesi iktisadi olarak nasıl açıklanır?', 'Yazılımcıların itibar kazanma, beşeri sermaye geliştirme ve iş piyasasında sinyal verme gibi özel yan faydalar (ortak ürün) elde etmesiyle', ['Açık kaynak yazılımların kopyalanmasının her yeni kullanıcıda yüksek fiziksel aşınma maliyeti yaratmasıyla', 'Devletlerin açık kaynak kod yazmayan tüm bilgisayar mühendislerine ağır para cezası uygulamasıyla', 'Açık kaynak yazılımların şifreli donanımlarla korunarak ödeme yapmayanların sistemden dışlanmasıyla'], 'Cornes ve Sandler\'ın "ortak ürün" (joint product) modeline göre kamusal mal katkısı aynı zamanda bireye özel fayda (prestij, kariyer sinyali) sağlıyorsa gönüllü üretim gerçekleşir.'),
  ('Bir ekonomide faiz dışı kamu harcamaları 1.600 birim, vergi gelirleri 1.500 birim, özelleştirme hariç vergi dışı normal gelirler 250 birim ve iç-dış borç faiz giderleri 320 birim ise bütçe dengesi ve faiz dışı denge sırasıyla nedir?', '170 birim bütçe açığı ve 150 birim faiz dışı fazla', ['150 birim bütçe fazlası ve 170 birim faiz dışı açık', '320 birim bütçe açığı ve 150 birim faiz dışı fazla', '70 birim bütçe açığı ve 250 birim faiz dışı fazla'], 'Toplam normal gelir = 1.750; faiz dışı denge = 1.750 - 1.600 = +150; toplam gider = 1.600 + 320 = 1.920; bütçe dengesi = 1.750 - 1.920 = -170\'tir.'),
  ('Yoksullukla mücadelede uygulanan "şartlı nakit transferi" programları hangi iki iktisadi amacı aynı potada birleştirir?', 'Dar gelirli hanelere gelir desteği sağlayarak yoksulluğu azaltmayı ve çocukların okul/aşı devamlılığını şart koşarak erdemli mal tüketimini artırmayı', ['Ülkenin dış borç faizlerini kapatmayı ve kamu iktisadi teşebbüslerinin kar paylarını özelleştirmeyi', 'Tam kamusal malları özel mallara dönüştürmeyi ve ortak kaynaklardaki mülkiyet haklarını kaldırmayı', 'Yüksek gelirli grupların tasarruf eğilimini artırmayı ve lüks tüketim vergilerini sıfırlamayı'], 'Şartlı nakit transferi hem sosyal transfer işlevi görür hem de eğitim ve sağlık gibi erdemli malların tüketimini zorunlu kılarak beşeri sermayeyi korur.'),
  ('Bir doğal parkın girişine yüksek bir ücret konulması parktaki kalabalıklaşmayı önlese bile park kapasitesinin çok altında ziyaretçi gelmesine yol açıyorsa burada hangi etkinsizlik söz konusudur?', 'Tüketimde henüz rakip olmayan (marjinal maliyeti sıfır olan) bir kaynağın aşırı fiyatla dışlanarak atıl kapasite ve refah kaybı yaratılması', ['Ortakların trajedisi nedeniyle doğal parkın biyolojik çeşitliliğinin bir günde yok olması', 'Bedavacılık sorunu yüzünden parkın bakım giderlerinin ziyaretçiler tarafından iki kez ödenmesi', 'Giriş ücreti konulduğu için parkın tam kamusal mal niteliğinin daha da güçlenmesi'], 'Kapasite dolmamışken ek ziyaretçinin marjinal sıkışıklık maliyeti sıfırdır; yüksek giriş ücreti pozitif fayda alacak kişileri dışlayarak dara kaybı üretir.'),
  ('Üç daireli bir apartmanda çatı onarımının maliyeti 30.000 TL olup dairelerin onarımdan sağlayacağı faydalar Daire 1 için 18.000 TL, Daire 2 için 12.000 TL ve Daire 3 için 6.000 TL ise Lindahl fiyatlaması mantığıyla her daire kaç TL ödemelidir?', 'Daire 1: 15.000 TL, Daire 2: 10.000 TL, Daire 3: 5.000 TL', ['Her üç daire de eşit olarak 10.000\'er TL', 'Daire 1: 18.000 TL, Daire 2: 12.000 TL, Daire 3: 0 TL', 'Daire 1: 20.000 TL, Daire 2: 8.000 TL, Daire 3: 2.000 TL'], 'Toplam fayda = 36.000 TL olup maliyet 30.000 TL\'dir (oran 5/6); faydalarla orantılı maliyet paylaşımında 18.000×(5/6)=15.000, 12.000×(5/6)=10.000 ve 6.000×(5/6)=5.000 TL ödenir.'),
  ('Kamu bütçesinde özelleştirme gelirlerinin uluslararası mali analizlerde (örneğin IMF tanımlı program bütçe dengesinde) faiz dışı fazla hesabına dahil edilmemesinin temel gerekçesi nedir?', 'Özelleştirmenin tek seferlik bir varlık satışı (finansman kalemi) olması ve devletin sürdürülebilir vergi-harcama performansını yansıtmaması', ['Özelleştirme gelirlerinin yasal olarak yalnızca yabancı ülkelere dış yardım olarak gönderilmesi', 'Kamu varlıklarının satışından elde edilen paranın ülke içinde tedavül yeteneğinin bulunmaması', 'Özelleştirme işlemlerinin her zaman bütçe giderlerini gelirlerinden daha fazla artırması'], 'Varlık satışı devletin net servetini değiştirmeyen bir bilanço finansman işlemidir; sürekli gelir gibi sayılırsa yapısal bütçe açığını gizler.'),
  ('Negatif gelir vergisi (Milton Friedman\'ın önerisi) geleneksel çok parçalı ayni ve nakdi sosyal transfer bürokrasisine kıyasla hangi iktisadi avantajı hedefler?', 'Belirli bir gelir eşiğinin altındakilere otomatik nakit destek verip gelir arttıkça desteği kademeli azaltarak çalışma şevkini kırmamayı (yoksulluk tuzağını önlemeyi) ve idari maliyeti düşürmeyi', ['Düşük gelirli vatandaşların tüm kazançlarına yüzde yüz vergi koyarak onları tamamen devlet yurtlarında barındırmayı', 'Sosyal yardımları yalnızca gıda ve giyim kuponlarına bağlayarak tüketicilerin nakit para kullanmasını yasaklamayı', 'Ülke genelindeki tüm dolaysız vergileri kaldırıp bütçeyi yalnızca gümrük vergileriyle finanse etmeyi'], 'Klasik yardımlarda işe giren kişinin yardımının aniden kesilmesi %100\'e varan efektif marjinal vergi yaratır; negatif gelir vergisi kademeli geçişle çalışma güdüsünü korur.'),
  ('Açık erişimli bir merada otlatılan koyun sayısı S iken toplam süt geliri TR = 80S - S² ve koyun başına bakım maliyeti 20 birim ise mülkiyet hakkı tanımlanıp mera tek bir kooperatife devredildiğinde meradan elde edilecek maksimum net ekonomik rant kaç birim olur?', '900 birim', ['0 birim', '1.200 birim', '600 birim'], 'Tek mülkiyette marjinal gelir marjinal maliyete eşitlenir: 80 - 2S = 20 -> S = 30 koyun; TR = 80(30) - 900 = 1.500 ve TC = 20(30) = 600 olduğundan maksimum rant = 1.500 - 600 = 900 birimdir (serbest girişte S=60 ve rant=0 olurdu).'),
  ('Bilimsel temel araştırmaların (örneğin teorik fizik veya saf matematik teoremleri) uygulama aşamasındaki endüstriyel Ar-Ge\'ye göre daha güçlü bir tam kamusal mal özelliği taşımasının nedeni nedir?', 'Temel bilimsel teoremlerin patentlenemeyip yayımlandığı anda tüm insanlığın ortak ve rakip olmayan bilgi havuzuna katılması', ['Teorik fizik araştırmalarının hiçbir laboratuvar veya araştırmacı maaşı gerektirmeden ücretsiz üretilmesi', 'Temel bilim sonuçlarının yalnızca araştırmayı yapan üniversitenin öğrencileri tarafından anlaşılabilmesi', 'Endüstriyel Ar-Ge faaliyetlerinin topluma her zaman negatif dışsallık yayarak büyümeyi düşürmesi'], 'Temel bilim sonuçları doğası gereği dışlanamaz ve rakip değildir; bu nedenle üniversiteler ve kamu bütçesi tarafından finanse edilmesi gerekir.'),
  ('Kamu harcamalarının fonksiyonel sınıflandırması ile ekonomik sınıflandırması arasındaki fark bir devlet okulu inşaatı örneği üzerinden nasıl açıklanır?', 'Fonksiyonel sınıflandırmada "eğitim hizmetleri" altında yer alırken ekonomik sınıflandırmada "sermaye (yatırım) giderleri" altında izlenir', ['Fonksiyonel sınıflandırmada "transfer harcaması" sayılırken ekonomik sınıflandırmada "faiz gideri" olarak kaydedilir', 'Her iki sınıflandırma sisteminde de "genel kamu personel maaşı" olarak aynı kodla gösterilir', 'Fonksiyonel sınıflandırmada bütçe dışı tutulurken ekonomik sınıflandırmada vergi geliri olarak yazılır'], 'Fonksiyonel sınıflandırma harcamanın hangi kamu hizmeti amacına (eğitim, savunma, sağlık) gittiğini, ekonomik sınıflandırma ise iktisadi niteliğini (cari, yatırım, transfer) gösterir.'),
  ('Kamu maliyesinde "vergi takozu" veya saptırıcı vergiler nedeniyle transfer harcamalarının yeniden dağıtım sürecinde oluşan kayıpları anlatan Arthur Okun\'un ünlü metaforu hangisidir?', 'Sızdıran kova metaforu', ['Görünmez el metaforu', 'Ortakların trajedisi metaforu', 'Deniz feneri metaforu'], 'Okun\'a göre zenginlerden yoksullara gelir taşırken bürokratik maliyetler ve çalışma/tasarruf şevkindeki düşüş nedeniyle kova yol boyunca su sızdırır.'),
  ('Bir ekonomide toplam kamu gelirleri 3.000 birim, cari harcamalar 1.350 birim, yatırım harcamaları 500 birim, faiz dışı transfer harcamaları 700 birim ve faiz giderleri 650 birim ise faiz dışı fazla toplam gelirlerin yüzde kaçıdır?', 'Yüzde 15,0', ['Yüzde 25,0', 'Yüzde 10,0', 'Yüzde 20,0'], 'Faiz dışı giderler 1.350 + 500 + 700 = 2.550 birimdir; faiz dışı fazla 3.000 - 2.550 = 450 birim olup 450 / 3.000 = %15,0 bulunur.'),
  ('Devletin özel tiyatrolara, senfoni orkestralarına ve sanat galerilerine bütçeden karşılıksız mali destek sağlaması hangi iki kavramla açıklanır?', 'Sanat etkinliklerinin erdemli mal sayılması ve üreticiye yönelik transfer (sübvansiyon) uygulanması', ['Sanat galerilerinin tam kamusal savunma malı olması ve dış borç ödemesi sayılması', 'Tiyatroların ortak havuz kaynağı olması ve negatif dışsallık vergisine tabi tutulması', 'Kültür hizmetlerinin erdemsiz mal olması ve tüketiminin kısıtlanmak istenmesi'], 'Kültür ve sanat faaliyetleri toplumsal gelişim için erdemli mal kabul edilir ve sübvansiyonlarla desteklenir.'),
  ('Bir ülkenin kamu bütçesi manşette açık verirken aynı zamanda yüksek oranda faiz dışı fazla veriyorsa bu ülkenin mali yapısı hakkında hangi çıkarım kesinlikle doğrudur?', 'Bütçe açığının tamamından daha büyük bir borç faiz yükü olduğu, ancak güncel vergi gelirlerinin faiz hariç tüm kamu hizmetlerini fazlasıyla karşıladığı', ['Ülkenin geçmiş dönemlerden kalan hiçbir iç veya dış kamu borcunun bulunmadığı', 'Devletin memur maaşlarını ve emekli aylıklarını ödeyemeyecek düzeyde cari gelir darlığı çektiği', 'Kamu yatırım ve transfer harcamaları toplamının bütçe gelirlerinin iki katına ulaştığı'], 'Bütçe Dengesi = Faiz Dışı Denge - Faiz Giderleri olduğundan FDF > 0 iken Bütçe Dengesi < 0 ise Faiz Giderleri > FDF > 0 demektir.'),
  ('Dört daireli bir binada güvenlik kamerası sistemi 12.000 TL\'dir; her dairenin kameradan alacağı fayda 4.000 TL olup sistem en az 3 dairenin 4.000\'er TL ödemesiyle (toplam 12.000 TL) kurulabiliyorsa ve fazla toplanan para iade edilmiyorsa bu "eşik kamusal mal" oyununda ne görülür?', 'Tam üç dairenin ödeyip bir dairenin bedavacı olduğu çoklu saf strateji Nash dengeleri ortaya çıkar', ['Hiçbir dairenin ödeme yapmaması tek ve baskın strateji dengesi olmaktan çıkıp herkesin 4.000 TL ödemesi tek denge olur', 'Dört dairenin toplam faydası maliyeti aşmadığı için kamera sistemi sosyal açıdan etkinsizdir', 'Her daire 12.000 TL ödeyerek toplam 48.000 TL bütçe fazlası oluşturur'], 'Eşik (provision point) oyununda 3 kişi öderken 4. kişinin ödemesine gerek yoktur (bedavacı olur), ancak 2 kişi öderken 3. kişi öderse 4.000 TL verip 4.000 TL fayda alarak kayıtsız kalır (fayda 4.500 olsaydı kesin öderdi; 4.000\'de zayıf denge dahil 3 ödeyenli dengeler oluşur).'),
  ('Kamu bütçesinde emekli sandığı veya sosyal güvenlik kurumunun gelir-gider farkını kapatmak için merkezi yönetim bütçesinden yapılan "açık finansmanı" ödemeleri hangi niteliktedir?', 'Sosyal güvenlik amaçlı kurumsal transfer harcaması', ['Sabit sermaye ve altyapı yatırım harcaması', 'Vergi dışı mülk ve teşebbüs geliri', 'Kamu personeli cari maaş ödemesi'], 'Sosyal güvenlik sisteminin aktüeryal açıklarını kapatmak üzere bütçeden aktarılan karşılıksız tutarlar transfer harcamasıdır.'),
  ('Bir ekonomide GSYH 10 trilyon TL, vergi ve diğer bütçe gelirleri 2,2 trilyon TL, toplam bütçe harcamaları 2,5 trilyon TL ve faiz giderleri 450 milyar TL ise faiz dışı fazla / GSYH oranı yüzde kaçtır?', 'Yüzde 1,5', ['Yüzde 3,0', 'Yüzde 4,5', 'Yüzde 2,2'], 'Faiz dışı harcamalar = 2.500 - 450 = 2.050 milyar TL; faiz dışı fazla = 2.200 - 2.050 = 150 milyar TL; 150 milyar / 10.000 milyar = %1,5\'tir.'),
  ('Devletin üniversite hastanelerine ve araştırma enstitülerine aktardığı hazine yardımları kamu bütçesinde hangi harcama kalemi içinde değerlendirilir?', 'Kurumsal transfer harcaması', ['Sabit sermaye yatırımı', 'Dış borç faiz ödemesi', 'Vergi harcaması'], 'Özel bütçeli veya özerk kurumların finansman ihtiyacını karşılamak üzere hazineden yapılan karşılıksız aktarımlar transferdir.'),
  ('Ortak mülkiyetteki bir nehirde üst havzadaki fabrikanın atık bırakarak alt havzadaki balıkçılara zarar vermesi mülkiyet hakları açısından neden ortak kaynak sorunuyla özdeştir?', 'Nehrin temiz su kapasitesi üzerinde dışlanabilir mülkiyet hakkı tanımlanmadığı için fabrikanın nehri ücretsiz bir atık havuzu gibi aşırı kullanması', ['Balıkçıların nehirdeki tüm suyu tüketerek fabrikanın üretimini fiziksel olarak durdurması', 'Devletin nehir kenarındaki tüm arazilere yüksek oranlı servet vergisi koyması', 'Temiz nehir suyunun tüketimde rakip olmama özelliğini her koşulda koruması'], 'Çevre kirliliği, temiz hava ve su gibi ortak mülkiyet varlıklarının mülkiyet belirsizliği nedeniyle aşırı tüketilmesi (kirletilmesi) sorunudur.'),
  ('Bir belediye parkının yıllık bakım maliyeti 120.000 TL olup mahalledeki 400 hanenin her biri parktan yılda 450 TL fayda sağlıyorsa gönüllü bağış yerine eşit emlak vergisiyle finansman sağlandığında mahallede oluşan toplam net sosyal refah artışı kaç TL olur?', '60.000 TL', ['180.000 TL', '120.000 TL', '45.000 TL'], 'Toplam fayda = 400 × 450 = 180.000 TL; toplam maliyet = 120.000 TL; net sosyal fayda = 180.000 - 120.000 = 60.000 TL olur.'),
  ('Kamu maliyesinde "mali yanılsama" (fiscal illusion) kavramı seçmenlerin kamusal mallar ve transfer harcamaları karşısındaki tutumunu nasıl çarpıtır?', 'Dolaylı vergiler ve borçlanmayla gizlenen vergi maliyetini olduğundan düşük algılayan seçmenlerin aşırı kamu harcaması ve transfer talep etmesine yol açar', ['Seçmenlerin kamu hizmetlerinin faydasını sıfır sanarak tüm okulların kapatılmasını istemesine neden olur', 'Vatandaşların ödedikleri vergileri gerçek tutarının on katı büyüklüğünde hesaplamasına sebep olur', 'Hükümetlerin faiz dışı fazlayı her yıl gizlice artırarak bütçe harcamalarını tamamen durdurmasını sağlar'], 'Puviani ve Buchanan\'a göre vergi yükü görünmez kılındığında (stopaj, KDV, borçlanma) seçmen kamusal malın bedavaya yakın olduğunu sanıp aşırı harcama ister.'),
];
